async function loadTasks() {
  await showViewOnly('tasks');
  const response = await apiCached('tasks', {});
  if (!response.ok) {
    document.querySelector('#tasksSummary').innerHTML = '';
    document.querySelector('#tasksBoard').innerHTML = `<p class="empty">${escapeHtml(response.error || 'Could not load tasks.')}</p>`;
    return;
  }
  const legacyRows = [
    ...(response.pendingLoa || []),
    ...(response.pendingTransfers || []),
    ...(response.pendingSupervisorRequests || []),
    ...(response.pendingCourseBookings || []),
    ...(response.pendingAppeals || []),
    ...(response.probationReviews || []),
    ...(response.performanceReviews || []),
    ...(response.restrictionReviews || []),
    ...(response.activityReviews || []),
    ...(response.trainingNeedsReview || []),
    ...(response.accountRequests || []),
    ...(response.retrospectiveShifts || []),
    ...(response.operationalReviews || []),
    ...(response.afterActionReviews || []),
    ...(response.actionReviews || []),
  ];
  state.allTasks = response.allTasks || legacyRows;
  state.tasks = response.myTasks || state.allTasks.filter((row) => row.IsMine || row.AssignedToMe || row.MySupervisee);
  updateTaskNavBadge(response.counts?.mine ?? state.tasks.length);
  const counts = response.counts || {};
  document.querySelector('#tasksSummary').innerHTML = [
    stat('My Open Tasks', counts.mine || state.tasks.length),
    stat('Due Soon', counts.dueSoon || 0),
    stat('Amendments', counts.amendments || 0),
    stat('Available Queue', counts.available || state.allTasks.length),
  ].join('');
  renderTaskView();
}

function renderTaskView() {
  document.querySelectorAll('[data-task-scope]').forEach((button) => button.classList.toggle('active', button.dataset.taskScope === state.taskScope));
  const sourceRows = state.taskScope === 'all' ? state.allTasks : state.tasks;
  updateTaskFilterOptions(sourceRows);
  const query = String(document.querySelector('#taskSearchFilter')?.value || '').trim().toLowerCase();
  const type = document.querySelector('#taskTypeFilter')?.value || '';
  const priority = document.querySelector('#taskPriorityFilter')?.value || '';
  const status = document.querySelector('#taskStatusFilter')?.value || '';
  const due = document.querySelector('#taskDueFilter')?.value || '';
  const sort = document.querySelector('#taskSortFilter')?.value || 'priority';
  const now = new Date(); const today = new Date(now.getFullYear(), now.getMonth(), now.getDate()); const week = new Date(today); week.setDate(week.getDate() + 7);
  const rows = sourceRows.filter((row) => {
    const searchable = [row.TaskType, row.Officer, row.Rank, row.Subject, row.Reason, row.Status, row.Supervisor, row.IncidentNumber, row.Reference].join(' ').toLowerCase();
    if (query && !searchable.includes(query)) return false;
    if (type && row.TaskType !== type) return false;
    if (priority && taskPriority(row) !== priority) return false;
    if (status && row.Status !== status) return false;
    const date = row.EndDate ? new Date(row.EndDate) : null; const day = date && !Number.isNaN(date.getTime()) ? new Date(date.getFullYear(), date.getMonth(), date.getDate()) : null;
    if (due === 'none' && day) return false; if (due === 'overdue' && (!day || day >= today)) return false; if (due === 'today' && (!day || day.getTime() !== today.getTime())) return false; if (due === 'week' && (!day || day < today || day > week)) return false;
    return true;
  }).sort((a, b) => {
    if (sort === 'due') return taskDateValue(a) - taskDateValue(b);
    if (sort === 'newest') return new Date(b.CreatedAt || b.RequestedAt || 0) - new Date(a.CreatedAt || a.RequestedAt || 0);
    if (sort === 'officer') return String(a.Officer || '').localeCompare(String(b.Officer || ''));
    return taskPriorityRank(taskPriority(a)) - taskPriorityRank(taskPriority(b)) || taskDateValue(a) - taskDateValue(b);
  });
  const board = document.querySelector('#tasksBoard');
  document.querySelector('#tasksFilterSummary').textContent = `${rows.length} of ${sourceRows.length} task${sourceRows.length === 1 ? '' : 's'} shown`;
  board.innerHTML = rows.length ? rows.map(taskCard).join('') : '<div class="task-empty-state"><strong>No matching tasks</strong><p>Adjust the filters or switch task queues.</p></div>';
}

function updateTaskFilterOptions(rows) {
  const update = (selector, values, fallback) => { const select = document.querySelector(selector); if (!select) return; const selected = select.value; select.innerHTML = `<option value="">${fallback}</option>${[...new Set(values.filter(Boolean))].sort().map((value) => `<option${value === selected ? ' selected' : ''}>${escapeHtml(value)}</option>`).join('')}`; };
  update('#taskTypeFilter', rows.map((row) => row.TaskType), 'All types');
  update('#taskStatusFilter', rows.map((row) => row.Status), 'All statuses');
}

function taskPriority(row) {
  if (row.Priority) return row.Priority;
  if (String(row.Status).toLowerCase().includes('overdue') || String(row.TaskType).includes('Amendment')) return 'Critical';
  if (String(row.TaskType).includes('Review') || String(row.TaskType).includes('Signature')) return 'High';
  return 'Normal';
}

function taskPriorityRank(priority) { return ({ Critical: 0, High: 1, Normal: 2, Low: 3 })[priority] ?? 2; }
function taskDateValue(row) { const value = row.EndDate ? new Date(row.EndDate).getTime() : Number.MAX_SAFE_INTEGER; return Number.isNaN(value) ? Number.MAX_SAFE_INTEGER : value; }

function taskDueLabel(row) {
  if (!row.EndDate) return { label: 'No due date', className: 'none' };
  const due = new Date(row.EndDate); if (Number.isNaN(due.getTime())) return { label: 'No due date', className: 'none' };
  const today = new Date(); today.setHours(0,0,0,0); const day = new Date(due); day.setHours(0,0,0,0); const difference = Math.round((day - today) / 86400000);
  if (difference < 0) return { label: `${Math.abs(difference)}d overdue`, className: 'overdue' };
  if (difference === 0) return { label: 'Due today', className: 'today' };
  if (difference === 1) return { label: 'Due tomorrow', className: 'soon' };
  return { label: `Due ${formatDisplayDate(row.EndDate)}`, className: difference <= 7 ? 'soon' : 'future' };
}

function generatedTaskKey(row) {
  if (row.TaskKey) return row.TaskKey;
  if (row.TaskType === 'Activity Review') return `activity:${row.OfficerID}:${new Date().toISOString().slice(0, 7)}`;
  if (row.TaskType === 'Training Review') return `training:${row.OfficerID}:${row.Subject || ''}:${row.EndDate || ''}`;
  return `${row.TaskType || 'task'}:${row.RequestID || row.ReviewID || row.TaskID || row.OfficerID || row.Subject || ''}`.toLowerCase().replace(/[^a-z0-9:_-]+/g, '-');
}

function openGeneratedTaskResolution(task) {
  const activity = task.TaskType === 'Activity Review';
  const outcomes = activity ? ['Officer contacted', 'No action required', 'Development support agreed', 'AIP considered', 'Referred to command', 'Other'] : ['Renewal arranged', 'Officer contacted', 'No action required', 'Training record corrected', 'Referred to training lead', 'Other'];
  openEditor(`${task.TaskType} / ${task.Officer}`, [
    hiddenField('TaskKey', task.TaskKey || generatedTaskKey(task)), hiddenField('TaskType', task.TaskType), hiddenField('OfficerID', task.OfficerID || ''),
    { html: `<section class="task-brief wide"><span>${escapeHtml(task.Status || 'Supervisor review')}</span><h3>${escapeHtml(task.Subject || task.TaskType)}</h3><p>${escapeHtml(task.Reason || 'Review the information and record what action was taken.')}</p>${task.LastShift ? `<small>Last shift: ${escapeHtml(formatDisplayDateTime(task.LastShift))}</small>` : ''}</section>` },
    selectField('Outcome', 'Review outcome / action taken', outcomes, outcomes[0]),
    field('Notes', 'Review notes', 'textarea', false),
    field('FollowUpDate', 'Follow-up date (optional)', 'date', false),
    selectField('SuppressDays', 'Clear this reminder for', ['7 days', '14 days', '30 days', 'Until follow-up date', 'Permanently'], activity ? '30 days' : '14 days'),
    { html: '<label class="wide"><input type="checkbox" name="NotifyOfficer" value="TRUE"> Notify the officer of this review outcome</label>' },
  ], (values) => api('resolveGeneratedTask', values), { successMessage: 'Task reviewed and cleared from the queue.', onSuccess: async () => { invalidateCache('tasks'); await loadTasks(); } });
}

function taskCard(row) {
  const priority = taskPriority(row); const due = taskDueLabel(row); const mine = row.IsMine || row.MySupervisee || row.AssignedToMe || row.CoveredByMe;
  const buttonLabel = String(row.TaskType).includes('Amendment') ? 'Complete amendments' : String(row.TaskType).includes('Review') ? 'Review' : String(row.TaskType).includes('Signature') ? 'Review and sign' : 'Open task';
  const guidance = taskCompletionGuidance(row);
  const coverNotice = row.CoveredByMe ? `<span class="task-cover-marker">Temporary cover for ${escapeHtml(row.CoveredSupervisorName || row.Supervisor || 'another officer')} due to LOA</span>` : '';
  return `<article class="task-card priority-${escapeHtml(priority.toLowerCase())}${mine ? ' is-mine' : ''}">
    <div class="task-card-priority"><span>${escapeHtml(priority)}</span><small>${row.CoveredByMe ? 'Cover task' : mine ? 'My task' : 'Available'}</small></div>
    <div class="task-card-main"><div class="task-card-meta"><span>${escapeHtml(row.TaskType || 'Task')}</span><span>${escapeHtml(row.Status || 'Open')}</span><span class="task-due ${escapeHtml(due.className)}">${escapeHtml(due.label)}</span></div><h3>${escapeHtml(row.Subject || row.TaskType || 'Assigned task')}</h3><p>${escapeHtml(row.Reason || 'No additional instructions recorded.')}</p><p class="task-card-guidance">${escapeHtml(guidance)}</p><div class="task-card-officer"><strong>${escapeHtml(row.Officer || 'General task')}</strong>${row.Rank ? `<span>${escapeHtml(row.Rank)}</span>` : ''}${row.Supervisor ? `<small>Supervisor: ${escapeHtml(row.Supervisor)}</small>` : ''}</div></div>
    ${coverNotice}<div class="task-card-action"><button ${taskOpenAttr(row)}>${escapeHtml(buttonLabel)}</button></div>
  </article>`;
}

function taskCompletionGuidance(row) {
  const type = row.TaskType || '';
  const guidance = {
    'LOA Approval': 'Open the request, review the dates/reason, then approve or deny it.',
    'Transfer Request': 'Open the request, check the transfer details, then approve, deny or request more information.',
    'Supervisor Request': 'Open the request, respond to the officer, then mark it completed or closed.',
    'Appeal / Review': 'Open the appeal, record the review decision and any outcome notes.',
    'Course Booking': 'Open course bookings, then approve, deny, waitlist or otherwise update the seat request.',
    'Account Request': 'Open the account request, verify membership details, then approve or deny it.',
    'Retrospective Shift': 'Open the retrospective shift request, check the times/reason, then approve or deny it.',
    'Probation Review': 'Open the probation record, update progress/status or complete the record.',
    'Performance Review': 'Open or create the performance review and save the next review position.',
    'Restriction Review': 'Open the restriction and update, remove, archive or confirm it remains active.',
    'Activity Review': 'Record the contact/action taken, optionally notify the officer, then clear the review.',
    'Training Review': 'Record the training action or renewal plan, then clear the review.',
    'AIP Signature': 'Review the AIP document and add the required signature.',
    'AIP Review': 'Open the AIP, review activity for the period and record the outcome.',
    'CAD Review': 'Open the CAD review, check the incident record, then sign off or return for amendments.',
    'After Action Review': 'Open the after-action review, record learning, decisions and follow-up actions.',
    'Operational Action Review': 'Open the officer action, check rationale/outcome, then approve or request amendments.',
    'CAD Amendment': 'Open the returned CAD, make the requested changes and send it back for review.',
    'Operational Action Amendment': 'Open the returned action, amend the record and resubmit it.',
    'Shift Review': 'Open the shift debrief, review activity/incomplete work, then approve, advise or request amendments.',
    'Shift Amendment': 'Open your shift debrief, make the requested amendments and resubmit if required.',
    'Casework Action': 'Open the linked case and complete or update the assigned case action.',
    'Recruitment Application': 'Open recruitment, review the application and record the application decision.',
    'Assigned Task': 'Open the assigned task, update status and mark it completed when the work is done.',
  };
  return guidance[type] || 'Open the task, complete the linked action, then save or clear the task.';
}

function taskOpenAttr(row) {
  if (row.TaskType === 'AIP Signature' || row.TaskType === 'AIP Review') return `data-open-aip="${escapeHtml(row.AipID)}"`;
  if (row.TaskType === 'Account Request') return `data-open-account-request="${escapeHtml(row.RequestID)}"`;
  if (row.TaskType === 'Retrospective Shift') return `data-open-retrospective-shift="${escapeHtml(row.RequestID)}"`;
  if (row.TaskType === 'Probation Review') return `data-edit-probation="${escapeHtml(row.ProbationID)}"`;
  if (row.TaskType === 'Performance Review') return `data-task-performance-review="${escapeHtml(row.OfficerID)}"${row.ReviewID ? ` data-review-id="${escapeHtml(row.ReviewID)}"` : ''}`;
  if (row.TaskType === 'Restriction Review') return `data-edit-restriction="${escapeHtml(row.RestrictionID)}"`;
  if (row.TaskType === 'Transfer Request') return `data-open-transfer-review="${escapeHtml(row.RequestID)}"`;
  if (row.TaskType === 'Supervisor Request') return `data-open-supervisor-review="${escapeHtml(row.RequestID)}"`;
  if (row.TaskType === 'Appeal / Review') return `data-open-appeal-review="${escapeHtml(row.AppealID)}"`;
  if (row.TaskType === 'Course Booking') return `data-task-course-bookings="${escapeHtml(row.CourseID)}"`;
  if (row.TaskType === 'Activity Review' || row.TaskType === 'Training Review') return `data-resolve-generated-task="${escapeHtml(row.TaskKey || generatedTaskKey(row))}"`;
  if (row.TaskType === 'CAD Review' || row.TaskType === 'After Action Review') return `data-open-cad-review-task="${escapeHtml(row.IncidentID)}"`;
  if (row.TaskType === 'Operational Action Review') return `data-open-action-review="${escapeHtml(row.ActionReviewID)}"`;
  if (row.TaskType === 'CAD Amendment' || row.TaskType === 'Operational Action Amendment') return `data-open-operational-amendment="${escapeHtml(row.AmendmentType)}:${escapeHtml(row.ReviewID)}:${escapeHtml(row.IncidentID)}"`;
  if (row.TaskType === 'Assigned Task') return `data-edit-mdt-task="${escapeHtml(row.TaskID)}"`;
  if (row.TaskType === 'Shift Review' || row.TaskType === 'Shift Amendment') return `data-open-shift-review-task="${escapeHtml(row.ShiftID || row.SourceID || row.TaskID || '')}"`;
  if (row.TaskType === 'Casework Action') return `data-open-ops-search="Case:${escapeHtml(row.OperationID)}"`;
  if (row.TaskType === 'Recruitment Application') return 'data-view-link="recruitment"';
  return `data-open-loa-review="${escapeHtml(row.RequestID)}"`;
}

async function openMdtTaskEditor(task = {}) {
  if (task.TaskID && !can('VIEW_TASKS')) {
    openEditor('Update my task', [hiddenField('TaskID', task.TaskID), selectField('Status', 'Status', ['Open', 'In Progress', 'Blocked', 'Completed'], task.Status || 'Open')], async (values) => api('saveMdtTask', values), { successMessage: 'Task updated.', onSuccess: async () => { invalidateCache('tasks'); await loadTasks(); } });
    elements.editorFields.insertAdjacentHTML('afterbegin', `<section class="task-brief"><span>${escapeHtml(task.Category || 'Assigned task')}</span><h3>${escapeHtml(task.Subject || task.Title || '')}</h3><p>${escapeHtml(task.Reason || task.Details || '')}</p>${task.EndDate ? `<small>Due ${escapeHtml(formatDisplayDateTime(task.EndDate))}</small>` : ''}</section>`);
    return;
  }
  await ensureOfficerRecords();
  const officers = (state.officers || []).filter((row) => row.Status !== 'Archived').map((row) => ({ UserID: row.OfficerID, RobloxUsername: row.RobloxUsername, Rank: row.Rank, Meta: row.Callsign || 'No callsign' }));
  openEditor(task.TaskID ? 'Update assigned task' : 'Assign task', [
    hiddenField('TaskID', task.TaskID || ''), field('Title', 'Task title', 'text', false, task.Subject || task.Title || ''), field('Details', 'Instructions', 'textarea', true, task.Reason || task.Details || ''),
    selectField('Category', 'Category', ['General', 'Operational', 'Development', 'Training', 'Casework', 'Administration'], task.Category || 'General'), selectField('Priority', 'Priority', ['Critical', 'High', 'Normal', 'Low'], task.Priority || 'Normal'), selectField('Status', 'Status', ['Open', 'In Progress', 'Blocked', 'Completed', 'Cancelled'], task.Status || 'Open'),
    searchableReferenceCheckboxGroupField('AssignedOfficerIDs', task.TaskID ? 'Assigned officer' : 'Assign to officers', officers, task.OfficerID || '', 'Search username, rank or callsign'),
    { html: `<p class="field-guidance wide">${task.TaskID ? 'An existing task can be reassigned to one officer.' : 'A separate linked task will be created for every selected officer.'}</p>` },
    field('DueAt', 'Due date', 'datetime-local', false, localDateTimeValue(task.EndDate || task.DueAt)),
  ], async (values) => api('saveMdtTask', values), { successMessage: task.TaskID ? 'Task saved.' : 'Tasks assigned.', onSuccess: async () => { invalidateCache('tasks'); await loadTasks(); } });
}

async function loadSupervisor() {
  await showViewOnly('supervisor');
  const response = await apiCached('supervisorDashboard', {});
  if (!response.ok) {
    document.querySelector('#supervisorSummary').innerHTML = '';
    return renderTable('#supervisorAssignedTable', [], ['Error'], { emptyMessage: response.error || 'Could not load supervisor dashboard.' });
  }

  state.supervisorDashboard = response;
  const counts = response.counts || {};
  document.querySelector('#supervisorSummary').innerHTML = [
    stat('Assigned Officers', counts.assigned || 0),
    stat('Unassigned Officers', counts.unassigned || 0),
    stat('Pending Requests', counts.pendingRequests || 0),
    stat('Open Goals', counts.openPlans || 0),
  ].join('');

  renderTable('#supervisorAssignedTable', response.assigned || [], ['RobloxUsername', 'Callsign', 'Rank', 'LoaStatus', 'LastShift', 'MonthlyActivity', 'OpenTasks', 'TrainingGaps', 'DisciplineFlags', 'OpenPlans'], {
    rowAction: (row) => `data-open-officer="${escapeHtml(row.OfficerID)}"`,
    actions: (row) => `<button class="mini ghost" data-supervisee-tasks="${escapeHtml(row.OfficerID)}">Tasks</button><button class="mini" data-add-checkin="${escapeHtml(row.OfficerID)}">Check-in</button><button class="mini" data-add-plan="${escapeHtml(row.OfficerID)}">Add goal</button>`,
  });
  renderTable('#supervisorRequestsTable', response.pendingRequests || [], ['Officer', 'Rank', 'Category', 'Subject', 'CreatedAt', 'Supervisor'], {
    actions: (row) => `<button class="mini" data-open-supervisor-review="${escapeHtml(row.RequestID)}">Review</button>`,
  });
  renderTable('#supervisorUnassignedTable', response.unassigned || [], ['RobloxUsername', 'Callsign', 'Rank', 'DutyStatus'], {
    rowAction: (row) => `data-open-officer="${escapeHtml(row.OfficerID)}"`,
    actions: (row) => `<button class="mini" data-assign-supervisor="${escapeHtml(row.OfficerID)}">Assign</button>`,
  });
  renderTable('#supervisorWorkloadTable', response.workload || [], ['Supervisor', 'Rank', 'AssignedOfficers', 'PendingRequests', 'Coverage']);
  renderTable('#supervisorPlansTable', response.developmentPlans || [], ['Officer', 'Goal', 'Category', 'Status', 'DueDate', 'Notes'], {
    actions: (row) => `<button class="mini" data-edit-plan="${escapeHtml(row.PlanID)}">Edit</button>`,
  });
  renderTable('#supervisorCheckinsTable', response.checkins || [], ['Officer', 'CheckinDate', 'Summary', 'Concerns', 'DevelopmentGoals', 'FollowUpDate']);
  applyPermissions();
}

function openSupervisorTaskPreview(officerId = '') {
  const dashboard = state.supervisorDashboard || {};
  const tasks = (dashboard.superviseeTasks || []).filter((task) => !officerId || task.OfficerID === officerId || task.SubjectOfficerID === officerId);
  const officer = officerId ? (dashboard.assigned || []).find((row) => row.OfficerID === officerId) : null;
  const title = officer ? `Tasks / ${officer.RobloxUsername}` : 'All supervisee tasks';
  const body = tasks.length ? `<div class="supervisee-task-preview">${tasks.map((task) => `<article class="supervisee-task-row priority-${escapeHtml(taskPriority(task).toLowerCase())}"><div><span>${escapeHtml(task.TaskType || 'Task')}</span><strong>${escapeHtml(task.Subject || task.TaskType || 'Task')}</strong><p>${escapeHtml(task.Reason || 'No details recorded.')}</p><small>${escapeHtml(taskCompletionGuidance(task))}</small></div><aside><b>${escapeHtml(task.Officer || 'Officer')}</b><em>${escapeHtml(task.Status || 'Open')}</em><button class="mini" ${taskOpenAttr(task)}>Open</button></aside></article>`).join('')}</div>` : '<p class="empty">No open tasks are recorded for this supervisee.</p>';
  showInfo(title, body);
}

async function loadShift() {
  await showViewOnly('shift');
  const query = shiftQuery();
  const [statusResponse, teamResponse] = await Promise.all([
    apiCached('shiftStatus', {}),
    apiCached('teamShifts', query),
  ]);
  state.shiftStatus = statusResponse.ok ? statusResponse : null;
  state.shifts = teamResponse.ok ? teamResponse.recent || [] : [];
  state.shiftDebriefs = teamResponse.ok ? teamResponse.debriefs || [] : [];
  state.shiftReviews = teamResponse.ok ? teamResponse.reviews || [] : [];
  state.voidedShifts = teamResponse.ok ? teamResponse.voided || [] : [];
  state.shiftAudit = teamResponse.ok ? teamResponse.audit || [] : [];

  const onDuty = Boolean(statusResponse.activeShift);
  renderDutyControl(statusResponse.activeShift);
  document.querySelector('#shiftSummary').innerHTML = [
    stat('Your Status', onDuty ? 'On Duty' : 'Off Duty'),
    stat('On Duty Now', teamResponse.active ? teamResponse.active.length : 0),
    stat('Your Shifts', teamResponse.myStats?.Shifts || 0),
    stat('Your Duration', teamResponse.myStats?.Duration || '0h 0m'),
  ].join('');
  renderShiftPersonalDashboard(teamResponse.myDashboard || {});

  renderTable('#activeShiftsTable', teamResponse.active || [], ['RobloxUsername', 'Callsign', 'Rank', 'LoaStatus', 'StartedAt']);
  renderTable('#recentShiftsTable', teamResponse.recent || [], ['RobloxUsername', 'Callsign', 'StartedAt', 'EndedAt', 'Duration', 'Summary'], {
    actions: (row) => can('VIEW_TASKS') ? `<button class="mini ghost" data-shift-history="${escapeHtml(row.ShiftID)}">History</button><button class="mini" data-edit-shift="${escapeHtml(row.ShiftID)}">Edit</button><button class="mini danger ghost" data-void-shift="${escapeHtml(row.ShiftID)}">Void</button>` : '',
  });
  renderTable('#shiftMetricsTable', teamResponse.metrics || [], ['RobloxUsername', 'Callsign', 'Rank', 'LoaStatus', 'Shifts', 'Duration', 'LastShift', 'ActivityFlag']);
  renderTable('#shiftDebriefsTable', state.shiftDebriefs, ['Officer', 'StartedAt', 'Duration', 'CADs', 'Actions', 'Incomplete', 'SupervisorAttention', 'SubmittedAt'], { actions: (row) => `<button class="mini ghost" data-open-shift-debrief="${escapeHtml(row.DebriefID)}">Review</button>` });
  renderTable('#shiftReviewsTable', state.shiftReviews, ['Officer', 'StartedAt', 'Quality', 'ReviewStatus', 'ReviewedBy', 'ReviewedAt'], { actions: (row) => can('VIEW_TASKS') ? `<button class="mini" data-review-shift="${escapeHtml(row.ShiftID)}">Review</button>` : '' });
  applyPermissions();
}

async function loadOperationsHub(force = false) {
  if (force) invalidateCache('operationsHub');
  const response = await apiCached('operationsHub', {});
  if (!response.ok) {
    document.querySelector('#opsSummary').innerHTML = `<article class="ops-stat"><strong>!</strong><span>${escapeHtml(response.error || 'Could not load operations.')}</span></article>`;
    return;
  }
  state.operationsHub = response;
  state.shiftStatus = response.shiftStatus || null;
  const onDuty = Boolean(response.shiftStatus?.onDuty);
  const controlNav = document.querySelector('[data-ops-workspace="control"]');
  if (controlNav) controlNav.hidden = !response.controllerEligible;
  const controllerButton = document.querySelector('#opsControllerButton');
  if (controllerButton) {
    controllerButton.hidden = !response.controllerEligible;
    controllerButton.textContent = response.controllerSession ? `Control: ${response.controllerSession.Status}` : 'Book on control';
    controllerButton.classList.toggle('active-control', response.controllerSession?.Status === 'Active');
  }
  const dutyButton = document.querySelector('#opsDutyButton');
  if (dutyButton) { dutyButton.textContent = onDuty ? 'End shift' : 'Start shift'; dutyButton.classList.toggle('on-duty', onDuty); }
  document.querySelector('#opsSummary').innerHTML = [
    opsStat('Units', response.stats?.ActiveUnits || 0),
    opsStat('Available', (response.units || []).filter((unit) => unit.OperationalStatus === 'Available').length),
    opsStat('Active CAD', (response.incidents || []).filter((row) => !['Resolved', 'Cancelled'].includes(row.Status)).length),
    opsStat('Urgent', (response.incidents || []).filter((row) => ['Emergency', 'Immediate'].includes(row.Priority)).length),
    opsStat('Status', onDuty ? response.shiftStatus.activeShift?.OperationalStatus || 'On Duty' : 'Off Duty'),
  ].join('');
  document.querySelector('#opsLiveCount').textContent = String(response.incidents?.length || 0);
  document.querySelector('#opsReviewCount').textContent = String((response.reviews || []).filter((row) => ['Pending', 'Amendments Required'].includes(row.ReviewStatus)).length + (response.actionReviews || []).length);
  document.querySelector('#opsActionCount').textContent = String((response.actionQueue || []).filter((row) => !['Completed', 'Cancelled'].includes(row.Status)).length);
  document.querySelector('#opsCommsCount').textContent = String((response.messages || []).filter((row) => ['Urgent', 'High'].includes(row.Priority)).length);
  document.querySelector('#opsUnits').innerHTML = (response.units || []).length ? response.units.map(opsUnitCard).join('') : emptyState('No officers are currently on duty.');
  document.querySelector('#opsUnitsFull').innerHTML = (response.units || []).length ? response.units.map(opsUnitCard).join('') : emptyState('No officers are currently on duty.');
  document.querySelector('#opsBolos').innerHTML = (response.bolos || []).length ? response.bolos.map(opsBoloCard).join('') : emptyState('No active BOLOs.');
  document.querySelector('#opsAssigned').innerHTML = (response.assigned || []).length ? response.assigned.map(opsIncidentCard).join('') : emptyState('No incidents assigned to you.');
  document.querySelector('#opsJoinRequests').innerHTML = (response.joinRequests || []).length ? response.joinRequests.map(opsJoinRequestCard).join('') : emptyState('No unit join requests.');
  document.querySelector('#opsBriefings').innerHTML = (response.briefings || []).length ? response.briefings.map(opsBriefingCard).join('') : emptyState('No active briefings.');
  document.querySelector('#opsBriefingsLive').innerHTML = (response.briefings || []).length ? response.briefings.map(opsBriefingCard).join('') : emptyState('No active briefings.');
  document.querySelector('#opsCoverage').innerHTML = opsCoverageRows(response);
  renderOpsCallQueue();
  renderOpsActivityFeed();
  renderOpsArchive();
  renderOpsAnalytics();
  renderOpsReviews();
  renderOpsTemplates();
  renderOpsIntelSearch();
  renderOpsOperations();
  renderOpsLocationIntel();
  renderOpsDataQuality();
  renderOpsCallsignBoard();
  renderOpsControlRoom();
  renderOpsComms();
  renderOpsActionQueue();
  renderOpsCasework();
  renderOpsDeployments();
  renderOpsReference();
  renderOpsContextTab();
  const selected = operationalIncidentById(state.selectedOperationalIncidentId);
  if (selected) renderOpsIncidentWorkspace(selected);
  else document.querySelector('#opsIncidentWorkspace').innerHTML = `<div class="cad-empty-workspace"><span>CAD</span><h2>Select an active incident</h2><p>The incident log, units, links and command information will appear here.</p></div>`;
  if (state.operationsWorkspace === 'intel' && state.selectedIntelEntity) renderOpsRelationshipView(state.selectedIntelEntity.type, state.selectedIntelEntity.id);
  applyPermissions();
}

function opsStat(label, value) {
  return `<article class="ops-stat"><span>${escapeHtml(label)}</span><strong>${escapeHtml(String(value))}</strong></article>`;
}

function operationalIncidentById(incidentId) {
  return [...(state.operationsHub.incidents || []), ...(state.operationsHub.archive || [])].find((row) => row.IncidentID === incidentId);
}

function opsCallQueueCard(row) {
  const selected = row.IncidentID === state.selectedOperationalIncidentId ? ' selected' : '';
  return `<article class="cad-call priority-${escapeHtml(String(row.Priority || 'routine').toLowerCase())}${selected}" data-open-cad="${escapeHtml(row.IncidentID)}">
    <i class="cad-call-priority"></i><div><small>${escapeHtml(row.IncidentNumber || row.IncidentID)} / ${escapeHtml(row.Status)}</small><strong>${escapeHtml(row.Title)}</strong><p>${escapeHtml(row.Location || 'Location not recorded')} / ${escapeHtml(row.AssignedUnits || 'Unassigned')}</p></div><time>${escapeHtml(opsRelativeTime(row.CreatedAt))}</time>
  </article>`;
}

function renderOpsCallQueue() {
  const query = String(document.querySelector('#opsLiveSearch')?.value || '').toLowerCase();
  const priority = document.querySelector('#opsLivePriority')?.value || '';
  const status = document.querySelector('#opsLiveStatus')?.value || '';
  const rows = (state.operationsHub.incidents || []).filter((row) => (!priority || row.Priority === priority) && (!status || (status === 'Unassigned' ? !(row.AssignedUnitIDs || []).length : row.Status === status)) && (!query || [row.IncidentNumber, row.Title, row.Location, row.AssignedUnits, row.Description].some((value) => String(value || '').toLowerCase().includes(query))));
  document.querySelector('#opsIncidents').innerHTML = rows.length ? rows.map(opsCallQueueCard).join('') : emptyState('No matching active incidents.');
}

function renderOpsIncidentWorkspace(row) {
  state.selectedOperationalIncidentId = row.IncidentID;
  updateOperationsPresence();
  renderOperationsPresence();
  const isClosed = ['Resolved', 'Cancelled'].includes(row.Status);
  const logs = [...(row.Logs || [])].sort((a, b) => new Date(b.CreatedAt) - new Date(a.CreatedAt));
  const command = row.CommandRoles || {};
  const myUnit = state.operationsHub.myUnit || null;
  const canAttach = !isClosed && myUnit?.UnitID && !(row.AssignedUnitIDs || []).includes(myUnit.UnitID);
  const activeDetailTab = state.cadDetailTab || 'overview';
  const workflow = cadWorkflowProgress(row);
  const workspace = document.querySelector('#opsIncidentWorkspace');
  workspace.innerHTML = `<header class="cad-detail-head">
    <div class="cad-priority-block ${escapeHtml(String(row.Priority || '').toLowerCase())}">${escapeHtml(String(opsPriorityWeight(row.Priority)))}</div>
    <div><small>${escapeHtml(row.IncidentNumber)} / ${escapeHtml(row.IncidentType)} / ${escapeHtml(row.Status)}</small><h2>${escapeHtml(row.Title)}</h2><p>${escapeHtml(row.Location || 'Location not recorded')}</p></div>
    <div class="cad-detail-actions">${canAttach ? `<button data-attach-my-unit="${escapeHtml(row.IncidentID)}">Attach ${escapeHtml(myUnit.Callsign)}</button>` : ''}<button class="incident-brief-action" data-incident-brief="${escapeHtml(row.IncidentID)}">Incident brief</button>${!isClosed ? `<button class="workflow-action" data-open-cad-workflow="${escapeHtml(row.IncidentID)}">Workflow ${workflow.completed}/${workflow.total}</button><button class="ghost" data-link-cad-person="${escapeHtml(row.IncidentID)}">Add person</button><button class="ghost" data-link-cad-vehicle="${escapeHtml(row.IncidentID)}">Add vehicle</button>` : ''}${!isClosed && (row.AssignedUnitIDs || []).length && can('VIEW_TASKS') ? `<button class="ghost" data-transfer-cad="${escapeHtml(row.IncidentID)}">Transfer</button>` : ''}<button class="ghost" data-link-cad-case="${escapeHtml(row.IncidentID)}">Add to case</button><button class="ghost" data-edit-ops-incident="${escapeHtml(row.IncidentID)}">Edit</button><button class="ghost" data-open-ops-log="${escapeHtml(row.IncidentID)}">Add log</button><button class="ghost" data-add-ops-attachment="${escapeHtml(row.IncidentID)}">Evidence</button><button class="cid-export-action" data-export-cid-referral="CAD:${escapeHtml(row.IncidentID)}">CID referral PDF</button><button class="warning-action" data-ops-assistance="${escapeHtml(row.IncidentID)}">Assistance</button>${isClosed && can('VIEW_TASKS') ? `<button data-reopen-cad="${escapeHtml(row.IncidentID)}">Reopen</button>` : !isClosed ? `<button data-close-cad="${escapeHtml(row.IncidentID)}">Close CAD</button>` : ''}</div>
  </header>
  <nav class="cad-record-tabs"><button class="${activeDetailTab === 'overview' ? 'active' : ''}" data-cad-detail-tab="overview">Overview</button><button class="${activeDetailTab === 'intelligence' ? 'active' : ''}" data-cad-detail-tab="intelligence">Intelligence <span>${escapeHtml(String((row.Entities || []).length))}</span></button><button class="${activeDetailTab === 'command' ? 'active' : ''}" data-cad-detail-tab="command">Command</button><button class="${activeDetailTab === 'timeline' ? 'active' : ''}" data-cad-detail-tab="timeline">Timeline <span>${escapeHtml(String(logs.length))}</span></button><button class="${activeDetailTab === 'evidence' ? 'active' : ''}" data-cad-detail-tab="evidence">Evidence <span>${escapeHtml(String((row.Attachments || []).length + (row.Links || []).length))}</span></button></nav>
  <section class="cad-detail-panel" data-cad-detail-panel="overview"${activeDetailTab === 'overview' ? '' : ' hidden'}><div class="cad-detail-grid">
    <section class="cad-detail-section"><h3>Incident record</h3><div class="cad-facts">
      ${opsFact('Description', row.Description || 'Not recorded')}${opsIncidentDataFacts(row)}${opsFact('Assigned units', row.AssignedUnits || 'Unassigned')}${opsFact('Required capability', row.RequiredCapabilities || 'None')}${opsFact('Radio / area', [row.RadioChannel, row.PatrolArea].filter(Boolean).join(' / ') || 'Not set')}${opsFact('Incident commander', command.IncidentCommander || 'Not assigned')}${opsFact('Command', [command.Bronze, command.Silver, command.Gold].filter(Boolean).join(' / ') || 'Not assigned')}${opsFact('Linked CADs', (row.LinkedIncidentIDs || []).join(', ') || 'None')}${opsFact('Linked intelligence', (row.LinkedBoloIDs || []).join(', ') || 'None')}${opsFact('Possible duplicate', row.DuplicateOfIncidentID || 'None')}${opsFact('Created', `${formatDisplayDateTime(row.CreatedAt)} by ${row.CreatedBy || 'Unknown'}`)}${opsFact('Outcome', row.Outcome || 'Open')}${opsFact('Closure code', row.ClosureCode || 'Open')}${opsFact('Review', row.ReviewStatus || 'Not Required')}
    </div></section>
    <section class="cad-detail-section"><h3>Unit attendance</h3>${opsAttendance(row.Attendance || [])}</section>
    ${(row.CorrelationAlerts || []).length ? `<section class="cad-detail-section cad-correlation-panel"><h3>Intelligence correlations</h3>${row.CorrelationAlerts.map((alert) => `<div class="cad-correlation-alert"><strong>${escapeHtml(alert.Title)}</strong><p>${escapeHtml(alert.Detail)}</p>${alert.Recommendation ? `<small>${escapeHtml(alert.Recommendation)}</small>` : ''}${alert.IncidentID ? `<button class="mini ghost" data-open-related-cad="${escapeHtml(alert.IncidentID)}">Open ${escapeHtml(alert.IncidentNumber || 'linked CAD')}</button>` : ''}</div>`).join('')}</section>` : ''}
  </div></section>
  <section class="cad-detail-panel" data-cad-detail-panel="intelligence"${activeDetailTab === 'intelligence' ? '' : ' hidden'}><div class="cad-detail-grid">
    <section class="cad-detail-section cad-intel-section"><div class="cad-panel-title"><h3>People and vehicles</h3><div><button class="ghost" data-link-cad-person="${escapeHtml(row.IncidentID)}">Add person</button><button class="ghost" data-link-cad-vehicle="${escapeHtml(row.IncidentID)}">Add vehicle</button></div></div>${opsIncidentEntities(row.Entities || [])}</section>
    <section class="cad-detail-section cad-intel-section"><div class="cad-panel-title"><div><h3>Actions and outcomes</h3><small>Officer activity records what an officer did. An enforcement result records what happened to the person or vehicle.</small></div><div><button class="ghost" data-record-cad-power="${escapeHtml(row.IncidentID)}" title="Record a statutory power used on a person or vehicle">Use of power</button><button class="ghost" data-add-cad-action="${escapeHtml(row.IncidentID)}" title="Credit an officer with an operational action such as a stop, pursuit, search or assistance">Record officer activity</button><button class="ghost" data-add-cad-disposal="${escapeHtml(row.IncidentID)}" title="Record an offence result such as an FPN, warning or arrest">Record enforcement result</button></div></div>${opsIncidentDisposals(row.Disposals || [])}${opsIncidentPowerUses(row.PowerUses || [])}</section>
  </div></section>
  <section class="cad-detail-panel" data-cad-detail-panel="command"${activeDetailTab === 'command' ? '' : ' hidden'}><div class="cad-detail-grid">
    <section class="cad-detail-section"><h3>Command structure</h3><div class="cad-facts">${opsFact('Incident commander', command.IncidentCommander || 'Not assigned')}${opsFact('Bronze', command.Bronze || 'Not assigned')}${opsFact('Silver', command.Silver || 'Not assigned')}${opsFact('Gold', command.Gold || 'Not assigned')}</div></section>
    <section class="cad-detail-section"><h3>Operational objectives</h3><p>${escapeHtml(row.Description || 'No operational objectives recorded.')}</p><div class="row-actions"><button class="ghost" data-edit-ops-incident="${escapeHtml(row.IncidentID)}">Update command record</button><button class="ghost" data-open-ops-log="${escapeHtml(row.IncidentID)}">Record decision</button></div></section>
    ${postIncidentLearningPanel(row)}
  </div></section>
  <section class="cad-detail-panel" data-cad-detail-panel="timeline"${activeDetailTab === 'timeline' ? '' : ' hidden'}><section class="cad-detail-section cad-detail-full"><div class="cad-panel-title"><h3>Incident timeline</h3><button class="ghost" data-open-ops-log="${escapeHtml(row.IncidentID)}">Add entry</button></div><div class="cad-timeline">${logs.length ? logs.map(opsLogEntry).join('') : '<p class="empty">No log entries yet.</p>'}</div></section></section>
  <section class="cad-detail-panel" data-cad-detail-panel="evidence"${activeDetailTab === 'evidence' ? '' : ' hidden'}><section class="cad-detail-section cad-detail-full"><div class="cad-panel-title"><h3>Evidence and links</h3><div><button class="ghost" data-add-ops-link="${escapeHtml(row.IncidentID)}">Add link</button><button class="ghost" data-add-ops-attachment="${escapeHtml(row.IncidentID)}">Upload file</button><button class="cid-export-action" data-export-cid-referral="CAD:${escapeHtml(row.IncidentID)}">Create CID pack</button></div></div><div class="cad-attachment-list">${(row.Attachments || []).map(opsAttachmentRow).join('') || '<p class="empty">No evidence attached.</p>'}</div><div class="cad-link-list">${(row.Links || []).map((link) => `<a class="cad-file-row" href="${escapeHtml(link.Url)}" target="_blank" rel="noopener"><span>${escapeHtml(link.Title)}</span><small>Open link</small></a>`).join('')}</div>${cidReferralHistoryHtml('CAD', row.IncidentID)}</section></section>`;
  renderOpsCallQueue();
}

function incidentBriefHtml(row) {
  const logs = [...(row.Logs || [])].sort((a, b) => new Date(b.CreatedAt) - new Date(a.CreatedAt));
  const risks = [...(row.CorrelationAlerts || []).map((item) => item.Title), ...(row.Entities || []).flatMap((entity) => (entity.Markers || []).map((marker) => marker.Type || marker.MarkerType)).filter(Boolean)];
  const outstanding = [];
  if (!(row.AssignedUnitIDs || []).length) outstanding.push('No unit assigned');
  if (!(row.Entities || []).length) outstanding.push('No people or vehicles linked');
  if (!row.Description) outstanding.push('Incident description incomplete');
  if (!['Resolved', 'Cancelled'].includes(row.Status) && !(row.Logs || []).length) outstanding.push('No incident log entries');
  return `<section class="incident-brief"><header><div><span>Automatically generated / ${escapeHtml(formatDisplayDateTime(new Date().toISOString()))}</span><h3>${escapeHtml(row.IncidentNumber)} / ${escapeHtml(row.Title)}</h3><p>${escapeHtml(row.Priority)} / ${escapeHtml(row.Status)} / ${escapeHtml(row.Location || 'Location not recorded')}</p></div><strong>${escapeHtml(String(opsPriorityWeight(row.Priority)))}</strong></header><div class="incident-brief-grid"><section><h4>Situation</h4><p>${escapeHtml(row.Description || 'No description recorded.')}</p></section><section><h4>Resources</h4><p>${escapeHtml(row.AssignedUnits || 'No units assigned')}</p><small>${escapeHtml(row.RequiredCapabilities ? `Required: ${row.RequiredCapabilities}` : 'No specialist capability requirement')}</small></section><section><h4>People and vehicles</h4>${(row.Entities || []).map((entity) => `<p><strong>${escapeHtml(entity.InvolvementRole)}</strong> ${escapeHtml(entity.Label)}</p>`).join('') || '<p>None linked.</p>'}</section><section class="${risks.length ? 'brief-risk' : ''}"><h4>Risks and intelligence</h4>${risks.map((risk) => `<p>${escapeHtml(risk)}</p>`).join('') || '<p>No explicit risks identified.</p>'}</section><section><h4>Recorded actions</h4><p>${escapeHtml(String((row.Disposals || []).length))} outcome(s) / ${escapeHtml(String((row.PowerUses || []).length))} power use(s) / ${escapeHtml(String((row.Attachments || []).length))} evidence item(s)</p></section><section class="${outstanding.length ? 'brief-outstanding' : ''}"><h4>Outstanding</h4>${outstanding.map((item) => `<p>${escapeHtml(item)}</p>`).join('') || '<p>No automatic gaps detected.</p>'}</section></div><section class="incident-brief-log"><h4>Latest updates</h4>${logs.slice(0, 5).map((log) => `<article><time>${escapeHtml(formatDisplayDateTime(log.CreatedAt))}</time><strong>${escapeHtml(log.EntryType)}</strong><p>${escapeHtml(log.Body)}</p></article>`).join('') || '<p>No updates recorded.</p>'}</section><footer>This brief is generated from the current MDT record and should be checked by the officer or controller before operational use.</footer></section>`;
}

function postIncidentLearningPanel(row) {
  const review = row.AfterAction || {};
  return `<section class="cad-detail-section cad-detail-full post-incident-learning"><div class="cad-panel-title"><div><small>${escapeHtml(review.Status || 'Not started')}</small><h3>Post-incident learning</h3></div>${can('VIEW_TASKS') ? `<button data-post-incident-learning="${escapeHtml(row.IncidentID)}">${review.AfterActionID ? 'Update review' : 'Start review'}</button>` : ''}</div>${review.AfterActionID ? `<div class="learning-grid">${opsFact('Decision summary', review.DecisionSummary || 'Not recorded')}${opsFact('Learning points', review.LearningPoints || 'Not recorded')}${opsFact('Follow-up actions', review.FollowUpActions || 'Not recorded')}${opsFact('Due', review.DueAt ? formatDisplayDateTime(review.DueAt) : 'Not set')}</div>` : '<p>No structured learning review has been recorded for this incident.</p>'}</section>`;
}

function openIncidentBrief(incidentId) {
  const row = operationalIncidentById(incidentId);
  if (row) showInfo(`Incident brief / ${row.IncidentNumber}`, incidentBriefHtml(row));
}

async function openAndVerifyEvidence(attachmentId) {
  const target = window.open('', '_blank');
  const response = await api('openOperationalEvidence', { AttachmentID: attachmentId });
  if (!response.ok) { target?.close(); showInfo('Evidence unavailable', `<p>${escapeHtml(response.error || 'The evidence could not be opened.')}</p>`); return; }
  if (target) target.location = response.Url;
  try {
    const fileResponse = await fetch(response.Url);
    const observedHash = await sha256Hex(await fileResponse.arrayBuffer());
    const verification = await api('recordEvidenceVerification', { AttachmentID: attachmentId, ObservedHash: observedHash });
    const attachment = [...(state.operationsHub.incidents || []), ...(state.operationsHub.archive || [])].flatMap((incident) => incident.Attachments || []).find((row) => row.AttachmentID === attachmentId);
    if (attachment && verification.ok) { attachment.IntegrityStatus = verification.Status; attachment.Sha256 = verification.ExpectedHash || response.ExpectedHash || observedHash; attachment.VerifiedAt = new Date().toISOString(); attachment.AccessCount = Number(attachment.AccessCount || 0) + 2; }
  } catch (error) {
    // Signed evidence can still be opened when browser CORS prevents the secondary integrity read.
  }
}

function showEvidenceHistory(attachmentId) {
  const attachment = [...(state.operationsHub.incidents || []), ...(state.operationsHub.archive || [])].flatMap((incident) => incident.Attachments || []).find((row) => row.AttachmentID === attachmentId);
  if (!attachment) return;
  showInfo(`Evidence integrity / ${attachment.Title || attachment.FileName}`, `<section class="evidence-history"><header><span>${escapeHtml(attachment.IntegrityStatus)}</span><h3>${escapeHtml(attachment.FileName)}</h3><p>SHA-256 ${escapeHtml(attachment.Sha256 || 'Not recorded')}</p></header>${(attachment.AccessLog || []).map((row) => `<article><time>${escapeHtml(formatDisplayDateTime(row.CreatedAt))}</time><div><strong>${escapeHtml(row.Action)}</strong><span>${escapeHtml(row.Actor)}${row.Result ? ` / ${escapeHtml(row.Result)}` : ''}</span></div></article>`).join('') || '<p class="empty">No access history recorded yet.</p>'}</section>`);
}

function openPostIncidentLearningEditor(incidentId) {
  const row = operationalIncidentById(incidentId);
  if (!row) return;
  const review = row.AfterAction || {};
  openEditor(`Post-incident learning / ${row.IncidentNumber}`, [hiddenField('IncidentID', incidentId), selectField('Status', 'Review status', ['In Progress', 'Completed'], review.Status === 'Completed' ? 'Completed' : 'In Progress'), field('DecisionSummary', 'What happened and why key decisions were made', 'textarea', false, review.DecisionSummary || ''), field('LearningPoints', 'Learning points', 'textarea', false, review.LearningPoints || ''), field('FollowUpActions', 'Follow-up actions and ownership', 'textarea', false, review.FollowUpActions || ''), field('DueAt', 'Follow-up due', 'datetime-local', true, localDateTimeValue(review.DueAt))], (values) => api('saveAfterActionLearning', values), { successMessage: 'Post-incident learning record saved.', onSuccess: refreshOperationsHub });
}

function opsFact(label, value) {
  return `<div class="cad-fact"><span>${escapeHtml(label)}</span><strong>${escapeHtml(String(value || ''))}</strong></div>`;
}

function opsIncidentDataFacts(row) {
  const data = row.IncidentData || {};
  const labels = { PrimaryRegistration: 'Registration', PrimaryPerson: 'Driver / person', StopReason: 'Stop reason', VehicleDescription: 'Vehicle', TargetRegistration: 'Target registration', PursuitGrounds: 'Pursuit grounds', RiskLevel: 'Risk level', Termination: 'Termination', VehiclesInvolved: 'Vehicles involved', Injuries: 'Injuries', RoadObstruction: 'Road obstruction' };
  return Object.entries(labels).filter(([key]) => data[key]).map(([key, label]) => opsFact(label, data[key])).join('');
}

function opsLogEntry(log) {
  return `<article class="cad-log-entry"><time>${escapeHtml(formatDisplayDateTime(log.CreatedAt))}</time><div><strong>${escapeHtml(log.EntryType)} / ${escapeHtml(log.Author || 'System')}</strong><p>${escapeHtml(log.Body)}</p></div></article>`;
}

function opsAttendance(rows) {
  return rows.length ? `<div class="cad-attachment-list">${rows.map((row) => `<div class="cad-file-row"><div><strong>${escapeHtml(row.Callsign || 'Unit')}</strong><small>Assigned ${escapeHtml(formatDisplayDateTime(row.AssignedAt))}${row.OnSceneAt ? ` / On scene ${escapeHtml(formatDisplayDateTime(row.OnSceneAt))}` : ''}${row.ClearedAt ? ` / Cleared ${escapeHtml(formatDisplayDateTime(row.ClearedAt))}` : ''}</small></div><span>${escapeHtml(row.Duration || 'Active')}</span></div>`).join('')}</div>` : '<p class="empty">No units have attended.</p>';
}

function opsIncidentEntities(rows) {
  return rows.length ? `<div class="intel-entity-list">${rows.map((row) => `<button class="intel-entity-chip" data-open-cad-entity="${escapeHtml(row.EntityType)}:${escapeHtml(row.EntityID)}"><span>${escapeHtml(row.InvolvementRole)}</span><strong>${escapeHtml(row.Label)}</strong><small>${escapeHtml(row.Detail || '')}</small></button>`).join('')}</div>` : '<p class="empty">No people or vehicles linked to this CAD.</p>';
}

function openCadEntityDrawer(entityType, entityId) {
  const incident = operationalIncidentById(state.selectedOperationalIncidentId);
  const detail = operationalEntityDetail(entityType, entityId);
  if (!incident || !detail) return;
  document.querySelector('.cad-entity-drawer')?.remove();
  const allIncidents = [...(state.operationsHub.incidents || []), ...(state.operationsHub.archive || [])];
  const linked = allIncidents.filter((row) => row.IncidentID !== incident.IncidentID && (row.Entities || []).some((entity) => entity.EntityType === entityType && entity.EntityID === entityId));
  const outcomes = allIncidents.flatMap((row) => (row.Disposals || []).filter((item) => entityType === 'Person' ? item.PersonID === entityId : item.VehicleID === entityId).map((item) => ({ ...item, IncidentNumber: row.IncidentNumber })));
  document.querySelector('#opsIncidentWorkspace')?.insertAdjacentHTML('beforeend', `<aside class="cad-entity-drawer" aria-label="Linked intelligence"><header><div><span>${escapeHtml(entityType)}</span><h3>${escapeHtml(detail.Title)}</h3><p>${escapeHtml(detail.Subtitle || '')}</p></div><button class="icon-button" data-close-cad-entity aria-label="Close intelligence drawer">×</button></header>${opsIntelMarkerPanel(entityType, entityId)}<section><h4>Previous CAD contacts</h4>${linked.length ? linked.map((row) => `<article class="cad-drawer-record"><div><strong>${escapeHtml(row.IncidentNumber)} / ${escapeHtml(row.Title)}</strong><small>${escapeHtml(formatDisplayDateTime(row.CreatedAt))} / ${escapeHtml(row.Status)}</small></div><button class="mini ghost" data-open-related-cad="${escapeHtml(row.IncidentID)}">Open</button></article>`).join('') : '<p class="empty">No other CAD contacts recorded.</p>'}</section><section><h4>Recorded outcomes</h4>${outcomes.length ? outcomes.map((row) => `<article class="cad-drawer-record"><div><strong>${escapeHtml(row.OutcomeType)} / ${escapeHtml(row.Offence || 'No offence')}</strong><small>${escapeHtml(row.IncidentNumber)}</small></div></article>`).join('') : '<p class="empty">No previous outcomes recorded.</p>'}</section></aside>`);
  document.querySelector('.cad-entity-drawer > header')?.insertAdjacentHTML('afterend', `<div class="row-actions cad-drawer-actions"><button data-record-entity-outcome="${escapeHtml(entityType)}:${escapeHtml(entityId)}">Add outcome</button><button class="ghost" data-record-power-use="${escapeHtml(entityType)}:${escapeHtml(entityId)}">Record power</button></div>`);
}

function opsIncidentDisposals(rows) {
  return rows.length ? `<div class="intel-disposal-list">${rows.map((row) => `<article><span>${escapeHtml(row.OutcomeType)}</span><strong>${escapeHtml(row.Subject || 'Unspecified subject')}</strong><p>${escapeHtml(row.Offence || 'No offence selected')}</p><small>${row.FineAmount ? `FPN £${escapeHtml(String(row.FineAmount))}` : ''}${row.PrisonMinutes ? ` / ${escapeHtml(String(row.PrisonMinutes))} minutes arrest time` : ''}${row.PenaltyPoints ? ` / ${escapeHtml(String(row.PenaltyPoints))} points` : ''}</small>${can('VIEW_TASKS') ? `<button class="mini danger" data-delete-operational-disposal="${escapeHtml(row.DisposalID)}">Remove</button>` : ''}</article>`).join('')}</div>` : '<p class="empty">No actions or outcomes recorded.</p>';
}

function opsIncidentPowerUses(rows) {
  return rows.length ? `<div class="intel-power-list"><h4>Police powers exercised</h4>${rows.map((row) => `<article><strong>${escapeHtml(row.PowerCode)} / ${escapeHtml(row.Power)}</strong><p>${escapeHtml(row.Grounds)}</p><small>${escapeHtml(row.Officer)} / ${escapeHtml(formatDisplayDateTime(row.OccurredAt))} / ${escapeHtml(row.Outcome)}</small></article>`).join('')}</div>` : '';
}

function opsAttachmentRow(row) {
  return `<article class="cad-file-row evidence-integrity-row"><div><span>${escapeHtml(row.Title || row.FileName)}</span><small>${escapeHtml(row.FileType || 'File')} / ${escapeHtml(formatFileSize(row.FileSize || 0))}</small><em class="integrity-${escapeHtml(String(row.IntegrityStatus || 'unverified').toLowerCase())}">${escapeHtml(row.IntegrityStatus || 'Unverified')} / SHA-256 ${escapeHtml(row.Sha256 ? `${row.Sha256.slice(0, 16)}...` : 'not recorded')}</em></div><div class="row-actions"><button class="mini" data-open-evidence="${escapeHtml(row.AttachmentID)}">Open and verify</button><button class="mini ghost" data-evidence-history="${escapeHtml(row.AttachmentID)}">History (${escapeHtml(String(row.AccessCount || 0))})</button></div></article>`;
}

function cidReferralHistoryHtml(sourceType, sourceId) {
  const rows = (state.operationsHub.cidReferrals || []).filter((row) => row.SourceType === sourceType && row.SourceID === sourceId);
  return `<section class="cid-export-history"><div class="cad-panel-title"><div><small>Prepared for external submission</small><h3>CID referral packs</h3></div></div>${rows.length ? rows.map((row) => `<article><div><span>${escapeHtml(row.ReferralReference)} / version ${escapeHtml(String(row.Version))} / ${escapeHtml(row.Status)}</span><strong>${escapeHtml(row.Classification)}</strong><small>Readiness ${escapeHtml(String(row.ReadinessScore || 0))}% / exported ${escapeHtml(formatDisplayDateTime(row.ExportedAt))} / SHA-256 ${escapeHtml(String(row.PdfHash || '').slice(0, 16))}...</small>${row.SentTo ? `<small>Recorded as sent to ${escapeHtml(row.SentTo)}${row.SentAt ? ` on ${escapeHtml(formatDisplayDateTime(row.SentAt))}` : ''}</small>` : ''}</div><button class="mini ghost" data-download-cid-referral="${escapeHtml(row.ReferralID)}">Download PDF</button></article>`).join('') : '<p class="empty">No referral packs have been exported from this record.</p>'}</section>`;
}

function openCidReferralExporter(sourceType, sourceId) {
  const source = sourceType === 'Case'
    ? (state.operationsHub.operations || []).find((row) => row.OperationID === sourceId)
    : operationalIncidentById(sourceId);
  if (!source) return;
  const allIncidents = [...(state.operationsHub.incidents || []), ...(state.operationsHub.archive || [])];
  const linkedIds = sourceType === 'Case'
    ? (source.Links || []).filter((row) => row.SubjectType === 'Incident').map((row) => row.SubjectID)
    : [source.IncidentID, ...(source.LinkedIncidentIDs || [])];
  const incidentRows = [...new Map(linkedIds.map((id) => [id, allIncidents.find((row) => row.IncidentID === id)]).filter((entry) => entry[1])).values()];
  if (sourceType === 'CAD' && !incidentRows.length) incidentRows.push(source);
  const attachments = incidentRows.flatMap((incident) => (incident.Attachments || []).map((row) => ({ ...row, IncidentID: incident.IncidentID, IncidentNumber: incident.IncidentNumber })));
  const offenceText = [...new Set(incidentRows.flatMap((row) => (row.Disposals || []).map((item) => item.Offence).filter(Boolean)))].join('\n');
  const existing = (state.operationsHub.cidReferrals || []).filter((row) => row.SourceType === sourceType && row.SourceID === sourceId);
  const previousExport = existing[0] || null;
  const version = Math.max(0, ...existing.map((row) => Number(row.Version) || 0)) + 1;
  const referralReference = createCidReferralReference();
  const sourceReference = sourceType === 'Case' ? source.Reference : source.IncidentNumber;
  const incidentChoices = incidentRows.map((row) => `<label><input type="checkbox" data-cid-incident value="${escapeHtml(row.IncidentID)}" checked${sourceType === 'CAD' && row.IncidentID === sourceId ? ' disabled' : ''}><span><strong>${escapeHtml(row.IncidentNumber)}</strong><small>${escapeHtml(row.Title)} / ${escapeHtml(row.Status)}</small></span></label>`).join('');
  state.cidExportRedactions = {};
  const evidenceChoices = attachments.map((row) => `<div class="cid-evidence-option" data-cid-evidence-row="${escapeHtml(row.AttachmentID)}"><label><input type="checkbox" data-cid-evidence value="${escapeHtml(row.AttachmentID)}" checked><span><strong>${escapeHtml(row.Title || row.FileName)}</strong><small>${escapeHtml(row.IncidentNumber)} / ${escapeHtml(row.FileType || 'File')} / ${escapeHtml(formatFileSize(row.FileSize))}</small><em data-cid-redaction-state="${escapeHtml(row.AttachmentID)}"></em></span></label>${String(row.FileType || '').startsWith('image/') ? `<button type="button" class="mini ghost" data-redact-cid-evidence="${escapeHtml(row.AttachmentID)}">Redact image</button>` : ''}</div>`).join('');
  const executive = deriveCidExecutiveSummary(incidentRows, source);
  const declaration = 'I confirm that this referral pack is an accurate export of the records available to me at the time shown and that the information has not knowingly been altered or omitted.';
  openEditor('Create CID referral pack', [
    { html: `<section class="cid-export-intro"><span>${escapeHtml(referralReference)} / version ${escapeHtml(String(version))}</span><h3>${escapeHtml(sourceReference)} / ${escapeHtml(sourceType === 'Case' ? source.Name : source.Title)}</h3><p>The generated PDF and frozen record snapshot will be retained in the MDT. It will not be sent automatically.</p></section>` },
    { html: '<section class="cid-readiness-panel wide" id="cidReadinessPanel"></section>' },
    ...(previousExport ? [{ html: `<section class="cid-version-notice wide"><strong>Version ${escapeHtml(String(previousExport.Version))} exists</strong><span>This export will become version ${escapeHtml(String(version))} and will include an automatic change schedule.</span></section>` }] : []),
    hiddenField('ReferralReference', referralReference),
    hiddenField('Version', version),
    selectField('Classification', 'Document classification', ['Official - Internal', 'Official - Sensitive', 'Restricted'], source.Sensitivity || 'Official - Internal'),
    { html: `<label class="wide">Referral summary<textarea name="ReferralSummary" required>${escapeHtml(source.Summary || source.Outcome || source.Description || '')}</textarea></label>` },
    { html: '<label class="wide">Requested CID consideration<textarea name="RequestedAction" required placeholder="Explain what CID is being asked to consider, review or progress."></textarea></label>' },
    field('SuspectedOffences', 'Suspected offences and charging considerations', 'textarea', true, offenceText),
    field('KeyEvidence', 'Executive summary: key evidence', 'textarea', true, executive.KeyEvidence),
    field('EvidentialWeaknesses', 'Executive summary: weaknesses and gaps', 'textarea', true, executive.EvidentialWeaknesses),
    field('RecommendedNextSteps', 'Executive summary: recommended next steps', 'textarea', true, executive.RecommendedNextSteps),
    field('SentTo', 'Intended CID recipient (optional)', 'text', false),
    field('SentAt', 'Date sent (optional)', 'datetime-local', false),
    { html: `<section class="cid-export-selector wide"><div><h3>Included CAD records</h3><small>Untick linked records that are not relevant to this referral.</small></div>${incidentChoices || '<p>No linked CAD records.</p>'}</section>` },
    { html: `<section class="cid-export-selector wide"><div><h3>Included evidence</h3><small>Images will be embedded. Attached PDFs will be appended. Videos and other files receive secure evidence links.</small></div>${evidenceChoices || '<p>No uploaded evidence is linked to the selected CAD records.</p>'}</section>` },
    { html: `<section class="cid-signature-field wide"><div><h3>Officer declaration and signature</h3><p>${escapeHtml(declaration)}</p></div><canvas id="cidSignatureCanvas" aria-label="Draw your signature"></canvas><div><button type="button" class="ghost" id="clearCidSignature">Clear signature</button><label><input type="checkbox" name="DeclarationAccepted" value="Accepted" required> I accept the declaration above.</label></div></section>` },
  ], async (values) => {
    const canvas = document.querySelector('#cidSignatureCanvas');
    if (!canvas?.dataset.signed) return { ok: false, error: 'Draw your signature before generating the referral pack.' };
    const selectedIncidentIds = [...elements.editorFields.querySelectorAll('[data-cid-incident]')].filter((input) => input.checked || input.disabled).map((input) => input.value);
    const selectedEvidenceIds = [...elements.editorFields.querySelectorAll('[data-cid-evidence]:checked')].map((input) => input.value);
    if (!selectedIncidentIds.length) return { ok: false, error: 'Include at least one CAD record.' };
    elements.editorStatus.textContent = 'Preparing records and secure evidence links...';
    const signatureDataUrl = canvas.toDataURL('image/png');
    const snapshot = await buildCidReferralSnapshot({ sourceType, sourceId, source, values, selectedIncidentIds, selectedEvidenceIds, declaration, previousExport });
    elements.editorStatus.textContent = 'Hashing evidence and building PDF...';
    const evidenceAssets = await prepareCidEvidenceAssets(snapshot.Evidence, state.cidExportRedactions);
    evidenceAssets.forEach((asset, id) => {
      const evidence = snapshot.Evidence.find((row) => row.AttachmentID === id);
      if (evidence) {
        evidence.FileHash = asset.hash || '';
        evidence.ExportedFileHash = asset.redactedHash || asset.hash || '';
        evidence.Redacted = Boolean(asset.redactedHash);
        evidence.RedactionReason = state.cidExportRedactions[id]?.reason || '';
      }
    });
    snapshot.RedactionManifest = snapshot.Evidence.filter((row) => row.Redacted).map((row) => ({ AttachmentID: row.AttachmentID, Title: row.Title || row.FileName, IncidentNumber: row.IncidentNumber, Reason: row.RedactionReason, OriginalHash: row.FileHash, ExportedHash: row.ExportedFileHash, RedactedBy: snapshot.SubmittingOfficer.RobloxUsername, RedactedAt: snapshot.ExportedAt }));
    const pdfBytes = await createCidReferralPdf(snapshot, signatureDataUrl, evidenceAssets);
    const pdfHash = await sha256Hex(pdfBytes);
    const pdfFile = new File([pdfBytes], `${values.ReferralReference}-V${values.Version}.pdf`, { type: 'application/pdf' });
    const signatureBlob = dataUrlToBlob(signatureDataUrl);
    const signatureFile = new File([signatureBlob], 'officer-signature.png', { type: 'image/png' });
    elements.editorStatus.textContent = 'Securing completed referral pack...';
    const response = await api('saveCidReferralExport', {
      SourceType: sourceType,
      SourceID: sourceId,
      SourceReference: sourceReference,
      ReferralReference: values.ReferralReference,
      Version: values.Version,
      Classification: values.Classification,
      ReferralSummary: values.ReferralSummary,
      RequestedAction: values.RequestedAction,
      SuspectedOffences: values.SuspectedOffences,
      SentTo: values.SentTo,
      SentAt: values.SentAt,
      Declaration: declaration,
      IncidentIDs: selectedIncidentIds,
      EvidenceIDs: selectedEvidenceIds,
      EvidenceLinkExpiresAt: snapshot.EvidenceLinkExpiresAt,
      ReadinessScore: snapshot.QualityAssessment.Score,
      QualityAssessment: snapshot.QualityAssessment,
      ExecutiveSummary: snapshot.ExecutiveSummary,
      RedactionManifest: snapshot.RedactionManifest,
      VersionComparison: snapshot.VersionComparison,
      SupersedesReferralID: previousExport?.ReferralID || '',
      Snapshot: snapshot,
      PdfHash: pdfHash,
      PdfFile: pdfFile,
      SignatureFile: signatureFile,
    });
    if (response.ok) downloadBlob(pdfFile, pdfFile.name);
    return response;
  }, { persistDraft: false, successMessage: 'CID referral pack generated, retained and downloaded.', onSuccess: refreshOperationsHub });
  initializeCidSignaturePad(document.querySelector('#cidSignatureCanvas'));
  const updateQuality = () => renderCidReadinessPanel(incidentRows, attachments);
  elements.editorFields.addEventListener('input', updateQuality);
  updateQuality();
}

function deriveCidExecutiveSummary(incidents, source) {
  const entities = [...new Map((incidents || []).flatMap((row) => row.Entities || []).map((row) => [`${row.EntityType}:${row.EntityID}`, row])).values()];
  const outcomes = (incidents || []).flatMap((row) => row.Disposals || []);
  const evidence = (incidents || []).flatMap((row) => row.Attachments || []);
  const powers = (incidents || []).flatMap((row) => row.PowerUses || []);
  const keyEvidence = [
    ...evidence.slice(0, 6).map((row) => `${row.Title || row.FileName} (${row.AttachmentID})`),
    ...outcomes.slice(0, 6).map((row) => `${row.OutcomeType}: ${row.Offence || 'unclassified outcome'} involving ${row.Subject || 'recorded subject'}`),
    ...powers.slice(0, 4).map((row) => `${row.Power}: ${row.Outcome || 'power exercised'}`),
  ];
  const weaknesses = [];
  if (!evidence.length) weaknesses.push('No uploaded exhibits are presently linked.');
  if (!entities.length) weaknesses.push('No people or vehicles are linked to the selected CAD records.');
  if (!outcomes.length) weaknesses.push('No enforcement outcomes or linked offences are recorded.');
  if ((incidents || []).some((row) => !row.Description)) weaknesses.push('One or more CAD records has no full incident narrative.');
  if ((incidents || []).some((row) => !['Approved', 'Not Required'].includes(row.ReviewStatus))) weaknesses.push('One or more supervisor reviews is incomplete or requires amendments.');
  const openActions = source?.Actions?.filter((row) => !['Completed', 'Cancelled'].includes(row.Status)) || [];
  return {
    KeyEvidence: keyEvidence.join('\n') || 'No key evidence identified automatically. Review the selected records and add the strongest available evidence.',
    EvidentialWeaknesses: weaknesses.join('\n') || 'No obvious data-quality gaps were detected automatically. Officer review remains required.',
    RecommendedNextSteps: openActions.length ? openActions.map((row) => `${row.Title}: ${row.Details || row.Status}`).join('\n') : 'CID to review the referral, linked offences and evidential material and determine whether further investigation or charging consideration is appropriate.',
  };
}

function assessCidReferralQuality(incidents, evidence, values = {}) {
  const checks = [];
  const add = (label, condition, detail, weight = 1, warning = false) => checks.push({ Label: label, Status: condition ? 'Complete' : warning ? 'Warning' : 'Missing', Detail: condition ? 'Requirement satisfied.' : detail, Weight: weight });
  add('Referral summary', String(values.ReferralSummary || '').trim().length >= 20, 'Add a meaningful referral summary.', 2);
  add('Requested CID consideration', String(values.RequestedAction || '').trim().length >= 15, 'Explain what CID is being asked to consider.', 2);
  add('Suspected offences', String(values.SuspectedOffences || '').trim().length > 0, 'Record suspected offences or explain why none is proposed.', 1, true);
  add('CAD records selected', incidents.length > 0, 'Include at least one CAD record.', 2);
  add('Incident narratives', incidents.length > 0 && incidents.every((row) => String(row.Description || '').trim().length >= 10), 'One or more CADs has no meaningful incident narrative.', 2);
  add('People or vehicles identified', incidents.some((row) => (row.Entities || []).length), 'No people or vehicles are linked to the selected records.', 1, true);
  add('Incident logs', incidents.every((row) => (row.Logs || []).length), 'One or more CADs has no incident-log entries.', 1, true);
  add('Outcomes and offences', incidents.some((row) => (row.Disposals || []).length || row.Outcome), 'No outcome or offence information is recorded.', 2, true);
  add('Evidence selected', evidence.length > 0, 'No uploaded exhibits are selected.', 2, true);
  add('Evidence descriptions', evidence.every((row) => String(row.Title || row.FileName || '').trim().length > 0), 'One or more exhibits has no useful description.', 1, true);
  const powerUses = incidents.flatMap((row) => row.PowerUses || []);
  add('Power-use grounds', powerUses.every((row) => String(row.Grounds || '').trim().length > 0), 'A recorded use of power is missing its grounds.', 2);
  const officerActions = incidents.flatMap((row) => row.OfficerActions || []);
  add('Officer action notes', officerActions.every((row) => String(row.notes || row.Notes || '').trim().length > 0), 'An officer action has no explanatory notes.', 1, true);
  add('Supervisor review position', incidents.every((row) => ['Approved', 'Completed', 'Not Required'].includes(row.ReviewStatus)), 'A selected CAD is awaiting review or requires amendments.', 2, true);
  add('Executive evidence summary', String(values.KeyEvidence || '').trim().length >= 15, 'Identify the key evidence for the receiving investigator.', 2);
  add('Weaknesses and gaps', String(values.EvidentialWeaknesses || '').trim().length >= 10, 'Record weaknesses, gaps or confirm that none were identified.', 1);
  const total = checks.reduce((sum, row) => sum + row.Weight, 0);
  const earned = checks.reduce((sum, row) => sum + (row.Status === 'Complete' ? row.Weight : row.Status === 'Warning' ? row.Weight * 0.5 : 0), 0);
  return { Score: Math.round((earned / total) * 100), Checks: checks, Missing: checks.filter((row) => row.Status === 'Missing').length, Warnings: checks.filter((row) => row.Status === 'Warning').length, AssessedAt: new Date().toISOString() };
}

function renderCidReadinessPanel(allIncidents, allEvidence) {
  const container = document.querySelector('#cidReadinessPanel');
  if (!container) return;
  const incidentIds = [...elements.editorFields.querySelectorAll('[data-cid-incident]')].filter((input) => input.checked || input.disabled).map((input) => input.value);
  const evidenceIds = [...elements.editorFields.querySelectorAll('[data-cid-evidence]:checked')].map((input) => input.value);
  const value = (name) => elements.editorFields.querySelector(`[name="${name}"]`)?.value || '';
  const assessment = assessCidReferralQuality(allIncidents.filter((row) => incidentIds.includes(row.IncidentID)), allEvidence.filter((row) => evidenceIds.includes(row.AttachmentID)), { ReferralSummary: value('ReferralSummary'), RequestedAction: value('RequestedAction'), SuspectedOffences: value('SuspectedOffences'), KeyEvidence: value('KeyEvidence'), EvidentialWeaknesses: value('EvidentialWeaknesses') });
  const scoreClass = assessment.Score >= 85 ? 'ready' : assessment.Score >= 65 ? 'caution' : 'not-ready';
  container.innerHTML = `<div class="cid-readiness-score ${scoreClass}"><strong>${escapeHtml(String(assessment.Score))}%</strong><span>Referral readiness</span><small>${escapeHtml(String(assessment.Missing))} missing / ${escapeHtml(String(assessment.Warnings))} warning</small></div><div class="cid-readiness-checks">${assessment.Checks.map((row) => `<article class="status-${escapeHtml(row.Status.toLowerCase())}"><i>${row.Status === 'Complete' ? '&#10003;' : row.Status === 'Warning' ? '!' : '&#215;'}</i><div><strong>${escapeHtml(row.Label)}</strong>${row.Status === 'Complete' ? '' : `<small>${escapeHtml(row.Detail)}</small>`}</div></article>`).join('')}</div>`;
}

function createCidReferralReference() {
  const random = crypto.getRandomValues(new Uint8Array(4));
  return `CID-${new Date().getFullYear()}-${[...random].map((value) => value.toString(16).padStart(2, '0')).join('').toUpperCase()}`;
}

function initializeCidSignaturePad(canvas) {
  if (!canvas) return;
  canvas.width = 900;
  canvas.height = 220;
  const context = canvas.getContext('2d');
  context.fillStyle = '#ffffff';
  context.fillRect(0, 0, canvas.width, canvas.height);
  context.strokeStyle = '#102b44';
  context.lineWidth = 4;
  context.lineCap = 'round';
  context.lineJoin = 'round';
  let drawing = false;
  const point = (event) => {
    const bounds = canvas.getBoundingClientRect();
    return { x: ((event.clientX - bounds.left) / bounds.width) * canvas.width, y: ((event.clientY - bounds.top) / bounds.height) * canvas.height };
  };
  canvas.addEventListener('pointerdown', (event) => {
    drawing = true;
    canvas.setPointerCapture(event.pointerId);
    const start = point(event);
    context.beginPath();
    context.moveTo(start.x, start.y);
  });
  canvas.addEventListener('pointermove', (event) => {
    if (!drawing) return;
    const next = point(event);
    context.lineTo(next.x, next.y);
    context.stroke();
    canvas.dataset.signed = 'true';
  });
  const finish = () => { drawing = false; context.closePath(); };
  canvas.addEventListener('pointerup', finish);
  canvas.addEventListener('pointercancel', finish);
  document.querySelector('#clearCidSignature')?.addEventListener('click', () => {
    context.clearRect(0, 0, canvas.width, canvas.height);
    context.fillStyle = '#ffffff';
    context.fillRect(0, 0, canvas.width, canvas.height);
    delete canvas.dataset.signed;
  });
}

async function openCidEvidenceRedactor(attachmentId) {
  const incidents = [...(state.operationsHub.incidents || []), ...(state.operationsHub.archive || [])];
  const attachment = incidents.flatMap((row) => row.Attachments || []).find((row) => row.AttachmentID === attachmentId);
  if (!attachment?.Url || !String(attachment.FileType || '').startsWith('image/')) return showInfo('Redaction unavailable', '<p>Only accessible image evidence can be redacted.</p>');
  const dialog = document.querySelector('#cidRedactionDialog');
  const canvas = document.querySelector('#cidRedactionCanvas');
  const status = document.querySelector('#cidRedactionStatus');
  const reason = document.querySelector('#cidRedactionReason');
  document.querySelector('#cidRedactionTitle').textContent = attachment.Title || attachment.FileName || 'Redact evidence';
  status.textContent = 'Loading original evidence...';
  reason.value = state.cidExportRedactions[attachmentId]?.reason || '';
  dialog.showModal();
  try {
    const image = new Image();
    image.crossOrigin = 'anonymous';
    await new Promise((resolve, reject) => { image.onload = resolve; image.onerror = () => reject(new Error('The evidence image could not be loaded.')); image.src = attachment.Url; });
    const scale = Math.min(1, 1200 / image.naturalWidth, 760 / image.naturalHeight);
    canvas.width = Math.max(1, Math.round(image.naturalWidth * scale));
    canvas.height = Math.max(1, Math.round(image.naturalHeight * scale));
    state.cidRedactionSession = { attachment, image, rectangles: [...(state.cidExportRedactions[attachmentId]?.rectangles || [])], start: null, current: null };
    configureCidRedactionCanvas(canvas);
    renderCidRedactionCanvas();
    status.textContent = 'Drag across the image to place solid redaction boxes.';
  } catch (error) {
    state.cidRedactionSession = null;
    status.textContent = error.message;
  }
}

function configureCidRedactionCanvas(canvas) {
  const pointer = (event) => {
    const bounds = canvas.getBoundingClientRect();
    return { x: Math.max(0, Math.min(1, (event.clientX - bounds.left) / bounds.width)), y: Math.max(0, Math.min(1, (event.clientY - bounds.top) / bounds.height)) };
  };
  canvas.onpointerdown = (event) => {
    if (!state.cidRedactionSession) return;
    canvas.setPointerCapture(event.pointerId);
    state.cidRedactionSession.start = pointer(event);
    state.cidRedactionSession.current = state.cidRedactionSession.start;
  };
  canvas.onpointermove = (event) => {
    if (!state.cidRedactionSession?.start) return;
    state.cidRedactionSession.current = pointer(event);
    renderCidRedactionCanvas(true);
  };
  canvas.onpointerup = (event) => {
    const session = state.cidRedactionSession;
    if (!session?.start) return;
    const end = pointer(event);
    const rectangle = { x: Math.min(session.start.x, end.x), y: Math.min(session.start.y, end.y), width: Math.abs(end.x - session.start.x), height: Math.abs(end.y - session.start.y) };
    if (rectangle.width > 0.005 && rectangle.height > 0.005) session.rectangles.push(rectangle);
    session.start = null;
    session.current = null;
    renderCidRedactionCanvas();
  };
  canvas.onpointercancel = () => { if (state.cidRedactionSession) { state.cidRedactionSession.start = null; state.cidRedactionSession.current = null; renderCidRedactionCanvas(); } };
}

function renderCidRedactionCanvas(preview = false) {
  const session = state.cidRedactionSession;
  const canvas = document.querySelector('#cidRedactionCanvas');
  if (!session || !canvas) return;
  const context = canvas.getContext('2d');
  context.clearRect(0, 0, canvas.width, canvas.height);
  context.drawImage(session.image, 0, 0, canvas.width, canvas.height);
  context.fillStyle = '#000000';
  session.rectangles.forEach((row) => context.fillRect(row.x * canvas.width, row.y * canvas.height, row.width * canvas.width, row.height * canvas.height));
  if (preview && session.start && session.current) {
    context.fillStyle = 'rgba(0,0,0,.72)';
    context.fillRect(Math.min(session.start.x, session.current.x) * canvas.width, Math.min(session.start.y, session.current.y) * canvas.height, Math.abs(session.current.x - session.start.x) * canvas.width, Math.abs(session.current.y - session.start.y) * canvas.height);
  }
}

document.querySelector('#cidRedactionUndo')?.addEventListener('click', () => {
  state.cidRedactionSession?.rectangles.pop();
  renderCidRedactionCanvas();
});
document.querySelector('#cidRedactionReset')?.addEventListener('click', () => {
  if (state.cidRedactionSession) state.cidRedactionSession.rectangles = [];
  renderCidRedactionCanvas();
});
document.querySelector('#cidRedactionForm')?.addEventListener('submit', (event) => {
  event.preventDefault();
  const dialog = document.querySelector('#cidRedactionDialog');
  if (event.submitter?.value === 'cancel') { dialog.close(); return; }
  const session = state.cidRedactionSession;
  const reason = document.querySelector('#cidRedactionReason').value.trim();
  const status = document.querySelector('#cidRedactionStatus');
  if (!session?.rectangles.length) { status.textContent = 'Add at least one redaction box or close without saving.'; return; }
  if (!reason) { status.textContent = 'Record a reason for the redaction.'; return; }
  renderCidRedactionCanvas();
  const canvas = document.querySelector('#cidRedactionCanvas');
  state.cidExportRedactions[session.attachment.AttachmentID] = { rectangles: [...session.rectangles], reason, dataUrl: canvas.toDataURL('image/jpeg', 0.92) };
  const label = elements.editorFields.querySelector(`[data-cid-redaction-state="${session.attachment.AttachmentID}"]`);
  if (label) { label.textContent = `${session.rectangles.length} redaction${session.rectangles.length === 1 ? '' : 's'} / ${reason}`; label.classList.add('active'); }
  dialog.close();
});

async function buildCidReferralSnapshot({ sourceType, sourceId, source, values, selectedIncidentIds, selectedEvidenceIds, declaration, previousExport = null }) {
  const allIncidents = [...(state.operationsHub.incidents || []), ...(state.operationsHub.archive || [])];
  const incidents = allIncidents.filter((row) => selectedIncidentIds.includes(row.IncidentID)).map((row) => JSON.parse(JSON.stringify(row)));
  const evidenceLinkExpiresAt = new Date(Date.now() + (30 * 24 * 60 * 60 * 1000)).toISOString();
  const evidence = incidents.flatMap((incident) => (incident.Attachments || []).filter((row) => selectedEvidenceIds.includes(row.AttachmentID)).map((row) => ({ ...row, IncidentID: incident.IncidentID, IncidentNumber: incident.IncidentNumber })));
  await Promise.all(evidence.map(async (row) => {
    if (!row.StoragePath) return;
    const { data } = await supabaseClient.storage.from('mo8-cad-evidence').createSignedUrl(row.StoragePath, 30 * 24 * 60 * 60);
    row.EvidenceAccessUrl = data?.signedUrl || row.Url || '';
    delete row.Url;
  }));
  incidents.forEach((incident) => {
    incident.Attachments = evidence.filter((row) => row.IncidentID === incident.IncidentID).map((row) => ({ ...row }));
  });
  const officer = (state.operationsHub.officerDirectory || []).find((row) => row.OfficerID === state.operationsHub.currentOfficerID) || {};
  const relevantEntityKeys = new Set(incidents.flatMap((row) => (row.Entities || []).map((entity) => `${entity.EntityType}:${entity.EntityID}`)));
  const relationships = (state.operationsHub.relationships || []).filter((row) => relevantEntityKeys.has(`${row.SourceType}:${row.SourceID}`) || relevantEntityKeys.has(`${row.TargetType}:${row.TargetID}`));
  const offenceIds = new Set(incidents.flatMap((row) => (row.Disposals || []).map((item) => item.OffenceID).filter(Boolean)));
  const offenceCatalogue = (state.operationsHub.offences || []).filter((row) => offenceIds.has(row.OffenceID)).map((row) => JSON.parse(JSON.stringify(row)));
  const snapshot = {
    FormatVersion: 1,
    ReferralReference: values.ReferralReference,
    Version: Number(values.Version) || 1,
    Classification: values.Classification,
    ExportedAt: new Date().toISOString(),
    EvidenceLinkExpiresAt: evidenceLinkExpiresAt,
    SourceType: sourceType,
    SourceID: sourceId,
    SourceReference: sourceType === 'Case' ? source.Reference : source.IncidentNumber,
    SourceTitle: sourceType === 'Case' ? source.Name : source.Title,
    ReferralSummary: values.ReferralSummary,
    RequestedAction: values.RequestedAction,
    SuspectedOffences: values.SuspectedOffences,
    SentTo: values.SentTo || '',
    SentAt: values.SentAt || '',
    Declaration: declaration,
    SubmittingOfficer: { OfficerID: officer.OfficerID || '', RobloxUsername: state.user.RobloxUsername, Callsign: officer.Callsign || '', Rank: officer.Rank || state.user.Rank || '', UserID: state.user.UserID },
    Case: sourceType === 'Case' ? JSON.parse(JSON.stringify(source)) : null,
    Incidents: incidents,
    Evidence: evidence,
    Relationships: relationships,
    OffenceCatalogue: offenceCatalogue,
    ExecutiveSummary: { KeyEvidence: values.KeyEvidence || '', EvidentialWeaknesses: values.EvidentialWeaknesses || '', RecommendedNextSteps: values.RecommendedNextSteps || '' },
    QualityAssessment: assessCidReferralQuality(incidents, evidence, values),
    RedactionManifest: [],
  };
  snapshot.Chronology = buildCidReferralChronology(snapshot);
  snapshot.VersionComparison = compareCidReferralVersions(snapshot, previousExport?.Snapshot || null, previousExport);
  return snapshot;
}

function buildCidReferralChronology(snapshot) {
  const events = [];
  const add = (at, type, reference, title, detail = '', id = '') => { if (at) events.push({ At: at, Type: type, Reference: reference || '', Title: title || type, Detail: detail || '', ID: id || '' }); };
  (snapshot.Case?.Updates || []).forEach((row) => add(row.CreatedAt, `Case ${row.UpdateType}`, snapshot.Case.Reference, row.Body, `Recorded by ${row.Author || 'System'}`, row.UpdateID));
  (snapshot.Incidents || []).forEach((incident) => {
    add(incident.CreatedAt, 'CAD Created', incident.IncidentNumber, incident.Title, `${incident.Location || 'No location'} / ${incident.Priority}`, incident.IncidentID);
    (incident.Logs || []).forEach((row) => add(row.CreatedAt, row.EntryType || 'CAD Log', incident.IncidentNumber, row.Body, `Recorded by ${row.Author || 'System'}`, row.LogID));
    (incident.Disposals || []).forEach((row) => add(row.IssuedAt, 'Enforcement Outcome', incident.IncidentNumber, `${row.OutcomeType} / ${row.Offence || 'No offence'}`, `${row.Subject || 'No subject'} / ${row.IssuingOfficer || 'Unknown officer'}`, row.DisposalID));
    (incident.PowerUses || []).forEach((row) => add(row.OccurredAt, 'Power Exercised', incident.IncidentNumber, `${row.PowerCode || ''} ${row.Power || row.PowerID}`.trim(), `${row.Officer || row.OfficerID} / ${row.Outcome || 'No outcome'}`, row.PowerUseID));
    (incident.OfficerActions || []).forEach((row) => add(row.occurred_at || row.OccurredAt, 'Officer Action', incident.IncidentNumber, row.action_type || row.ActionType || 'Officer action', row.notes || row.Notes || '', row.action_id || row.ActionID));
    (incident.Attachments || []).forEach((row) => add(row.CreatedAt, 'Evidence Added', incident.IncidentNumber, row.Title || row.FileName, `${row.FileType || 'File'} / ${row.AttachmentID}`, row.AttachmentID));
    (incident.Reviews || []).forEach((row) => add(row.CompletedAt || row.CreatedAt, 'Supervisor Review', incident.IncidentNumber, row.Status, `${row.Reviewer || 'Unknown reviewer'} / ${row.Feedback || 'No feedback'}`, row.ReviewID));
    if (incident.ClosedAt) add(incident.ClosedAt, 'CAD Closed', incident.IncidentNumber, incident.ClosureCode || 'Closed', incident.Outcome || '', incident.IncidentID);
  });
  return events.sort((left, right) => String(left.At).localeCompare(String(right.At)));
}

function compareCidReferralVersions(snapshot, previousSnapshot, previousExport = null) {
  if (!previousSnapshot || !Object.keys(previousSnapshot).length) return { IsFirstVersion: true, PreviousReferralID: '', PreviousReference: '', PreviousVersion: 0, Changes: ['Initial referral export.'], AddedIncidents: [], RemovedIncidents: [], AddedEvidence: [], RemovedEvidence: [], ComparedAt: snapshot.ExportedAt };
  const previousIncidentIds = new Set((previousSnapshot.Incidents || []).map((row) => row.IncidentID));
  const currentIncidentIds = new Set((snapshot.Incidents || []).map((row) => row.IncidentID));
  const previousEvidenceIds = new Set((previousSnapshot.Evidence || []).map((row) => row.AttachmentID));
  const currentEvidenceIds = new Set((snapshot.Evidence || []).map((row) => row.AttachmentID));
  const changes = [];
  [['Referral summary', 'ReferralSummary'], ['Requested action', 'RequestedAction'], ['Suspected offences', 'SuspectedOffences'], ['Classification', 'Classification']].forEach(([label, key]) => {
    if (String(previousSnapshot[key] || '') !== String(snapshot[key] || '')) changes.push(`${label} changed.`);
  });
  const addedIncidents = [...currentIncidentIds].filter((id) => !previousIncidentIds.has(id));
  const removedIncidents = [...previousIncidentIds].filter((id) => !currentIncidentIds.has(id));
  const addedEvidence = [...currentEvidenceIds].filter((id) => !previousEvidenceIds.has(id));
  const removedEvidence = [...previousEvidenceIds].filter((id) => !currentEvidenceIds.has(id));
  if (addedIncidents.length) changes.push(`${addedIncidents.length} CAD record(s) added.`);
  if (removedIncidents.length) changes.push(`${removedIncidents.length} CAD record(s) removed.`);
  if (addedEvidence.length) changes.push(`${addedEvidence.length} exhibit(s) added.`);
  if (removedEvidence.length) changes.push(`${removedEvidence.length} exhibit(s) removed.`);
  (snapshot.Incidents || []).filter((row) => previousIncidentIds.has(row.IncidentID)).forEach((row) => {
    const previous = (previousSnapshot.Incidents || []).find((item) => item.IncidentID === row.IncidentID) || {};
    if ((row.Logs || []).length !== (previous.Logs || []).length) changes.push(`${row.IncidentNumber}: incident-log count changed from ${(previous.Logs || []).length} to ${(row.Logs || []).length}.`);
    if ((row.Disposals || []).length !== (previous.Disposals || []).length) changes.push(`${row.IncidentNumber}: outcome count changed from ${(previous.Disposals || []).length} to ${(row.Disposals || []).length}.`);
    if (row.ReviewStatus !== previous.ReviewStatus) changes.push(`${row.IncidentNumber}: review status changed from ${previous.ReviewStatus || 'not recorded'} to ${row.ReviewStatus || 'not recorded'}.`);
  });
  return { IsFirstVersion: false, PreviousReferralID: previousExport?.ReferralID || '', PreviousReference: previousExport?.ReferralReference || previousSnapshot.ReferralReference || '', PreviousVersion: previousExport?.Version || previousSnapshot.Version || 0, Changes: [...new Set(changes)].length ? [...new Set(changes)] : ['No material record changes detected; a new signed export was produced.'], AddedIncidents: addedIncidents, RemovedIncidents: removedIncidents, AddedEvidence: addedEvidence, RemovedEvidence: removedEvidence, ComparedAt: snapshot.ExportedAt };
}

async function prepareCidEvidenceAssets(evidence, redactions = {}) {
  const assets = new Map();
  await Promise.all((evidence || []).map(async (row) => {
    if (!row.EvidenceAccessUrl) return;
    try {
      const response = await fetch(row.EvidenceAccessUrl);
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const blob = await response.blob();
      const bytes = new Uint8Array(await blob.arrayBuffer());
      const asset = { bytes, hash: await sha256Hex(bytes), mimeType: row.FileType || blob.type || '' };
      if (asset.mimeType.startsWith('image/')) {
        const redaction = redactions[row.AttachmentID];
        if (redaction?.dataUrl) {
          const redactedBlob = dataUrlToBlob(redaction.dataUrl);
          const redactedBytes = new Uint8Array(await redactedBlob.arrayBuffer());
          asset.redactedHash = await sha256Hex(redactedBytes);
          asset.imageBytes = await compressCidEvidenceImage(redactedBlob);
        } else asset.imageBytes = await compressCidEvidenceImage(blob);
      }
      assets.set(row.AttachmentID, asset);
    } catch (error) {
      assets.set(row.AttachmentID, { error: error.message, hash: '' });
    }
  }));
  return assets;
}

async function compressCidEvidenceImage(blob) {
  const image = await createImageBitmap(blob);
  const scale = Math.min(1, 1600 / Math.max(image.width, image.height));
  const canvas = document.createElement('canvas');
  canvas.width = Math.max(1, Math.round(image.width * scale));
  canvas.height = Math.max(1, Math.round(image.height * scale));
  const context = canvas.getContext('2d');
  context.fillStyle = '#ffffff';
  context.fillRect(0, 0, canvas.width, canvas.height);
  context.drawImage(image, 0, 0, canvas.width, canvas.height);
  image.close();
  const compressed = await new Promise((resolve) => canvas.toBlob(resolve, 'image/jpeg', 0.82));
  return new Uint8Array(await compressed.arrayBuffer());
}

async function sha256Hex(value) {
  const bytes = value instanceof Uint8Array ? value : new Uint8Array(value);
  const hash = await crypto.subtle.digest('SHA-256', bytes);
  return [...new Uint8Array(hash)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

function dataUrlToBlob(dataUrl) {
  const [header, encoded] = dataUrl.split(',');
  const mimeType = header.match(/data:([^;]+)/)?.[1] || 'application/octet-stream';
  const binary = atob(encoded);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  return new Blob([bytes], { type: mimeType });
}

function downloadBlob(blob, fileName) {
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = fileName;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

