function opsCoverageRows(response) {
  const rows = response.coverage || [];
  const stats = response.stats || {};
  return [
    `<article class="ops-incident"><div><span>Operational stats</span><strong>${escapeHtml(String(stats.OpenIncidents || 0))} open CAD / ${escapeHtml(String(stats.ActiveUnits || 0))} active units</strong><p>${escapeHtml(String(stats.AvailableUnits || 0))} available units, ${escapeHtml(String(stats.UnassignedIncidents || 0))} unassigned incidents.</p></div></article>`,
    ...rows.map((row) => `<article class="ops-incident"><div><span>Area coverage</span><strong>${escapeHtml(row.Area || 'Unassigned')}</strong><p>${escapeHtml(String(row.Units))} unit(s) covering this area.</p></div></article>`),
  ].join('');
}

function openOpsUnitEditor(record = {}) {
  const presets = (state.operationsHub.callsignPresets || []).filter((preset) => preset.Available || preset.PresetID === record.PresetID);
  openEditor(record.UnitID ? 'Edit unit / callsign' : 'Create unit / callsign', [
    hiddenField('UnitID', record.UnitID || ''),
    selectField('PresetID', 'Preset callsign', ['', ...presets.map((preset) => preset.PresetID)], record.PresetID || ''),
    field('Callsign', 'Custom callsign (only when authorised)', 'text', true, record.CallsignPrefix || ''),
    selectField('PatrolType', 'Patrol type', ['Roads Policing', 'Roads Crime Team', 'Traffic', 'Motorbike', 'Supervisor', 'Training', 'Other'], record.PatrolType || 'Roads Policing'),
    selectField('Status', 'Status', ['Available', 'Assigned', 'En Route', 'On Scene', 'Transporting', 'At Station', 'Out of Service'], record.OperationalStatus || 'Available'),
    field('PatrolArea', 'Patrol area', 'text', false, record.PatrolArea || ''),
    field('RadioChannel', 'Radio channel', 'text', false, record.RadioChannel || ''),
    field('AssignedVehicleRegistration', 'Patrol vehicle registration', 'text', false, record.AssignedVehicleRegistration || ''),
    field('Notes', 'Notes', 'textarea', true, record.Notes || ''),
  ], async (values) => api('saveOperationalUnit', values), {
    successMessage: 'Unit saved.',
    onSuccess: async () => { invalidateCache('operationsHub'); await loadOperationsHub(true); },
  });
  const presetSelect = elements.editorFields.querySelector('[name="PresetID"]');
  if (presetSelect) [...presetSelect.options].forEach((option) => { const preset = presets.find((row) => row.PresetID === option.value); if (preset) option.textContent = `${preset.Callsign} - ${preset.UnitRole}`; });
}

function openOpsControllerSessionEditor() {
  const active = state.operationsHub.controllerSession;
  const onSuccess = async () => { invalidateCache('operationsHub'); await loadOperationsHub(true); switchOpsWorkspace('control'); };
  if (active) {
    openEditor('Control-room booking', [hiddenField('ControllerSessionID', active.ControllerSessionID), selectField('Status', 'Status', ['Active', 'Break', 'Ended'], active.Status), field('Notes', 'Controller notes', 'textarea', true, active.Notes || '')], async (values) => api('saveOperationalControllerSession', values), { successMessage: 'Control-room status updated.', onSuccess });
    return;
  }
  openEditor('Book on as controller', [
    selectField('ControllerRole', 'Control role', ['Controller', 'Control Supervisor', 'Tactical Advisor', 'Force Incident Manager'], 'Controller'),
    checkboxGroupField('Capabilities', 'Control capabilities', ['Dispatch', 'Resource Management', 'Tactical Advisor', 'Incident Management', 'Intelligence Checks'], 'Dispatch, Resource Management'),
    field('Notes', 'Booking notes', 'textarea', true),
  ], async (values) => api('saveOperationalControllerSession', values), { successMessage: 'Booked on to the control room.', onSuccess });
}

function openPresetUnitBookingEditor(preset) {
  openEditor(`Book on as ${preset.Callsign}`, [
    hiddenField('PresetID', preset.PresetID),
    field('AssignedVehicleRegistration', 'Vehicle registration', 'text', false),
    field('PatrolArea', 'Patrol area', 'text', true),
    field('RadioChannel', 'Radio channel', 'text', true),
    field('Notes', 'Unit notes', 'textarea', true),
  ], async (values) => api('saveOperationalUnit', values), { successMessage: `Booked on as ${preset.Callsign}.`, onSuccess: refreshOperationsHub });
  elements.editorFields.insertAdjacentHTML('afterbegin', `<p class="form-guidance">${escapeHtml(preset.UnitRole)} / ${escapeHtml(preset.VehicleRequirement)}. This callsign is currently available and will be assigned to you as unit lead.</p>`);
}

function openControllerRosterEditor(unitId) {
  const unit = (state.operationsHub.units || []).find((row) => row.UnitID === unitId);
  if (!unit) return;
  const officers = (state.operationsHub.onDutyOfficers || []).map((row) => ({ UserID: row.OfficerID, RobloxUsername: row.RobloxUsername, Rank: row.Rank, Meta: row.Callsign || '' }));
  openEditor(`Manage ${unit.Callsign}`, [
    hiddenField('UnitID', unit.UnitID),
    selectField('Status', 'Operational status', ['Available', 'Assigned', 'En Route', 'On Scene', 'Transporting', 'At Station', 'Out of Service'], unit.OperationalStatus || 'Available'),
    field('AssignedVehicleRegistration', 'Vehicle registration', 'text', true, unit.AssignedVehicleRegistration || ''),
    field('PatrolArea', 'Patrol area', 'text', true, unit.PatrolArea || ''),
    field('RadioChannel', 'Radio channel', 'text', true, unit.RadioChannel || ''),
    searchableReferenceCheckboxGroupField('OfficerIDs', 'Assigned crew', officers, unit.MemberIDs || '', 'Search on-duty officer, rank or callsign'),
    field('Notes', 'Controller notes', 'textarea', true, unit.Notes || ''),
  ], async (values) => api('controlUpdateOperationalUnit', values), { successMessage: `${unit.Callsign} roster updated.`, onSuccess: refreshOperationsHub });
}

function renderOpsCallsignBoard() {
  const container = document.querySelector('#opsCallsignBoard');
  if (!container) return;
  const rows = state.operationsHub.callsignPresets || [];
  const activeController = state.operationsHub.controllerSession?.Status === 'Active';
  container.innerHTML = `<div class="callsign-row heading"><span>Status</span><span>Callsign</span><span>Role</span><span>Vehicle</span><span>Crew</span><span>Capabilities / notes</span><span>Action</span></div>${rows.map((row) => {
    const officerAction = row.Available ? `<button class="mini" data-book-preset-unit="${escapeHtml(row.PresetID)}">Book on</button>` : row.IsMember ? '<span>Booked on</span>' : `<button class="mini ghost" data-request-join-unit="${escapeHtml(row.UnitID)}">Request join</button>`;
    const controlAction = activeController && row.UnitID ? `<button class="mini ghost" data-control-manage-unit="${escapeHtml(row.UnitID)}">Manage</button>` : '';
    return `<article class="callsign-row ${row.Available ? 'available' : 'occupied'}"><span>${row.Available ? 'Available' : escapeHtml(row.UnitStatus || 'In use')}</span><strong>${escapeHtml(row.Callsign)}</strong><span>${escapeHtml(row.UnitRole)}</span><span>${escapeHtml(row.AssignedVehicleRegistration || row.VehicleRequirement)}</span><span>${escapeHtml(row.Crew || '-')}</span><span>${escapeHtml([row.Capabilities, row.UnitNotes || row.Notes].filter(Boolean).join(' / '))}</span><span class="row-actions">${officerAction}${controlAction}</span></article>`;
  }).join('') || emptyState('No preset callsigns configured.')}`;
}

function renderOpsControlRoom() {
  const session = state.operationsHub.controllerSession;
  const activeController = session?.Status === 'Active';
  const eligible = state.operationsHub.controllerEligible;
  const status = document.querySelector('#opsControllerStatus');
  if (!status) return;
  status.innerHTML = session ? `<article><strong>${escapeHtml(session.ControllerRole)}</strong><span>${escapeHtml(session.Status)} / ${escapeHtml(session.Capabilities || 'No capabilities selected')}</span><button class="ghost" data-edit-controller-session>Update booking</button></article>` : `<article><strong>${eligible ? 'Not booked on control' : 'Controller authority not assigned'}</strong><span>${eligible ? 'Book on to use dispatch controls.' : 'A Controller tag or CONTROL_OPERATIONS permission is required.'}</span>${eligible ? '<button data-edit-controller-session>Book on control</button>' : ''}</article>`;
  const incidents = state.operationsHub.incidents || [];
  const units = (state.operationsHub.units || []).filter((row) => row.UnitID);
  const availableUnits = units.filter((row) => row.OperationalStatus === 'Available').length;
  const unassignedIncidents = incidents.filter((row) => !(row.AssignedUnitIDs || []).length).length;
  const priorityIncidents = incidents.filter((row) => ['Emergency', 'Immediate'].includes(row.Priority)).length;
  document.querySelector('#opsControlBoardSummary').innerHTML = `<article><strong>${units.length}</strong><span>Active units</span></article><article><strong>${availableUnits}</strong><span>Available</span></article><article class="${unassignedIncidents ? 'attention' : ''}"><strong>${unassignedIncidents}</strong><span>Unassigned CADs</span></article><article class="${priorityIncidents ? 'critical' : ''}"><strong>${priorityIncidents}</strong><span>Priority incidents</span></article>`;
  const controlUnitOptions = (incident) => {
    const required = splitTags(incident.RequiredCapabilities || '');
    return (state.operationsHub.units || []).filter((row) => row.UnitID).map((unit) => {
      const held = splitTags(unit.Capabilities || '');
      const missing = required.filter((item) => !held.includes(item));
      return { unit, missing };
    }).sort((a, b) => a.missing.length - b.missing.length || String(a.unit.Callsign).localeCompare(String(b.unit.Callsign))).map(({ unit, missing }) => `<option value="${escapeHtml(unit.UnitID)}">${missing.length ? `GAP: ${escapeHtml(missing.join(', '))}` : 'MATCH'} / ${escapeHtml(unit.Callsign)} / ${escapeHtml(unit.OperationalStatus)}</option>`).join('');
  };
  document.querySelector('#opsControlUnits').innerHTML = `<div class="control-row heading"><span>Callsign</span><span>Crew / capability</span><span>Status</span><span>CAD / controls</span></div>${(state.operationsHub.units || []).filter((row) => row.UnitID).map((row) => `<article class="control-row"><strong>${escapeHtml(row.Callsign)}</strong><span>${escapeHtml(row.Members)}<small>${escapeHtml(row.Capabilities)}</small></span><select data-control-unit-status="${escapeHtml(row.UnitID)}"${activeController ? '' : ' disabled'}>${['Available', 'Assigned', 'En Route', 'On Scene', 'Transporting', 'At Station', 'Out of Service'].map((value) => `<option${value === row.OperationalStatus ? ' selected' : ''}>${value}</option>`).join('')}</select><span>${escapeHtml(row.CurrentIncident || 'Unassigned')}${activeController ? `<button class="mini ghost" data-control-manage-unit="${escapeHtml(row.UnitID)}">Manage roster</button>` : ''}</span></article>`).join('') || emptyState('No active callsigns.')}`;
  document.querySelector('#opsControlIncidents').innerHTML = `<div class="control-row incident heading"><span>CAD</span><span>Incident</span><span>Priority</span><span>Assign</span></div>${incidents.map((row) => `<article class="control-row incident priority-${escapeHtml(String(row.Priority || 'routine').toLowerCase())}"><strong><button class="control-cad-link" data-open-cad="${escapeHtml(row.IncidentID)}">${escapeHtml(row.IncidentNumber)}</button></strong><span>${escapeHtml(row.Title)}<small>${escapeHtml(row.Location || '')}${row.RequiredCapabilities ? ` / requires ${escapeHtml(row.RequiredCapabilities)}` : ''} / ${escapeHtml(opsRelativeTime(row.CreatedAt))}</small></span><span>${escapeHtml(row.Priority)}</span><div><select data-control-assignment-select="${escapeHtml(row.IncidentID)}"${activeController ? '' : ' disabled'}><option value="">Select callsign</option>${controlUnitOptions(row)}</select><button class="mini" data-control-assign="${escapeHtml(row.IncidentID)}"${activeController ? '' : ' disabled'}>Assign</button><button class="mini ghost" data-incident-brief="${escapeHtml(row.IncidentID)}">Brief</button></div></article>`).join('') || emptyState('No active incidents.')}`;
  document.querySelector('#opsControlEvents').innerHTML = (state.operationsHub.controlEvents || []).length ? state.operationsHub.controlEvents.slice(0, 80).map((row) => `<article><time>${escapeHtml(formatDisplayDateTime(row.CreatedAt))}</time><div><strong>${escapeHtml(row.EventType)}</strong><p>${escapeHtml(row.Summary)}</p><small>${escapeHtml([row.IncidentNumber, row.Callsign, row.Actor].filter(Boolean).join(' / '))}</small></div></article>`).join('') : emptyState('Control actions will be recorded here automatically.');
  renderOpsControlOfficerSearch();
}

function toggleControlBoardMode(force) {
  const enabled = typeof force === 'boolean' ? force : !document.body.classList.contains('control-board-mode');
  document.body.classList.toggle('control-board-mode', enabled);
  const button = document.querySelector('#opsControlBoardMode');
  if (button) { button.textContent = enabled ? 'Exit board mode' : 'Board mode'; button.setAttribute('aria-pressed', String(enabled)); button.title = enabled ? 'Exit full-screen board (Esc)' : 'Open full-screen control board'; }
}

function renderOpsComms() {
  const feed = document.querySelector('#opsCommsFeed');
  if (!feed) return;
  const query = String(document.querySelector('#opsCommsSearch')?.value || '').trim().toLowerCase();
  const priority = document.querySelector('#opsCommsPriority')?.value || '';
  const rows = (state.operationsHub.messages || []).filter((row) =>
    (!state.opsCommsChannel || row.Channel === state.opsCommsChannel)
    && (!priority || row.Priority === priority)
    && (!query || [row.Message, row.Sender, row.SenderCallsign, row.TargetUnit, row.IncidentNumber, row.Channel].some((value) => String(value || '').toLowerCase().includes(query)))
  );
  feed.innerHTML = rows.length ? rows.map((row) => `<article class="comms-message priority-${escapeHtml(row.Priority.toLowerCase())}">
    <time>${escapeHtml(opsClock(row.CreatedAt))}</time>
    <div><span>${escapeHtml(row.Channel)} / ${escapeHtml(row.Priority)}</span><strong>${escapeHtml([row.SenderCallsign, row.Sender].filter(Boolean).join(' / '))}</strong><p>${escapeHtml(row.Message)}</p><small>${escapeHtml([row.IncidentNumber, row.TargetUnit, row.MessageType].filter(Boolean).join(' / '))}</small></div>
    ${row.IncidentID ? `<button class="ghost" data-open-cad="${escapeHtml(row.IncidentID)}">Open CAD</button>` : ''}
  </article>`).join('') : emptyState('No radio or dispatch traffic matches this view.');
  const incident = operationalIncidentById(state.selectedOperationalIncidentId);
  const unit = state.operationsHub.myUnit;
  document.querySelector('#opsCommsContext').innerHTML = `${incident ? `<article><small>Selected CAD</small><strong>${escapeHtml(incident.IncidentNumber)}</strong><span>${escapeHtml(incident.Title)}</span></article>` : '<p>No CAD selected.</p>'}${unit ? `<article><small>Your unit</small><strong>${escapeHtml(unit.Callsign)}</strong><span>${escapeHtml(unit.OperationalStatus)}</span></article>` : '<p>No active unit.</p>'}`;
}

async function submitOpsCommsMessage(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const values = Object.fromEntries(new FormData(form));
  values.IncidentID = state.selectedOperationalIncidentId || '';
  values.TargetUnitID = state.operationsHub.myUnit?.UnitID || '';
  const button = form.querySelector('button[type="submit"]');
  button.disabled = true;
  const response = await api('sendOperationalMessage', values);
  button.disabled = false;
  if (!response.ok) {
    showInfo('Transmission failed', `<p>${escapeHtml(response.error || 'The message could not be sent.')}</p>`);
    return;
  }
  form.elements.Message.value = '';
  scheduleOperationsRealtimeRefresh();
}

function startOperationsRealtime() {
  if (!USE_SUPABASE || !state.user || state.opsRealtimeChannel) return;
  const channel = supabaseClient.channel('mo8-live-operations', { config: { presence: { key: state.user.UserID } } });
  ['operational_messages', 'operational_incidents', 'operational_incident_logs', 'operational_units', 'operational_unit_members', 'operational_entity_relationships'].forEach((table) => {
    channel.on('postgres_changes', { event: '*', schema: 'public', table }, scheduleOperationsRealtimeRefresh);
  });
  channel.on('presence', { event: 'sync' }, () => {
    const presence = channel.presenceState();
    state.opsPresenceUsers = Object.values(presence).flat().filter(Boolean);
    renderOperationsPresence();
  });
  channel.subscribe(async (status) => {
    const liveState = document.querySelector('#opsCommsLiveState');
    if (liveState) liveState.textContent = status === 'SUBSCRIBED' ? 'Live' : status === 'CHANNEL_ERROR' ? 'Connection issue' : 'Connecting';
    if (status === 'SUBSCRIBED') await updateOperationsPresence();
  });
  state.opsRealtimeChannel = channel;
}

async function updateOperationsPresence() {
  if (!state.opsRealtimeChannel || !state.user) return;
  await state.opsRealtimeChannel.track({
    userId: state.user.UserID,
    username: state.user.RobloxUsername,
    rank: state.user.Rank || state.user.Role,
    workspace: state.operationsWorkspace,
    incidentId: state.selectedOperationalIncidentId || '',
    onlineAt: new Date().toISOString(),
  });
}

function renderOperationsPresence() {
  const container = document.querySelector('#opsPresence');
  if (!container) return;
  const unique = [...new Map(state.opsPresenceUsers.map((row) => [row.userId, row])).values()];
  const sameIncident = state.selectedOperationalIncidentId ? unique.filter((row) => row.incidentId === state.selectedOperationalIncidentId) : [];
  container.innerHTML = `<span class="presence-dot"></span><strong>${unique.length}</strong><span>online${sameIncident.length ? ` / ${sameIncident.length} viewing CAD` : ''}</span><div class="presence-list">${unique.slice(0, 8).map((row) => `<i title="${escapeHtml(`${row.username} / ${row.rank} / ${row.workspace}`)}">${escapeHtml(String(row.username || '?').slice(0, 1).toUpperCase())}</i>`).join('')}</div>`;
}

function scheduleOperationsRealtimeRefresh() {
  window.clearTimeout(state.opsRealtimeRefreshTimer);
  state.opsRealtimeRefreshTimer = window.setTimeout(async () => {
    if (state.activeHub !== 'operations') return;
    invalidateCache('operationsHub');
    await loadOperationsHub(true);
  }, 260);
}

function stopOperationsRealtime() {
  window.clearTimeout(state.opsRealtimeRefreshTimer);
  state.opsRealtimeRefreshTimer = null;
  if (state.opsRealtimeChannel && supabaseClient) supabaseClient.removeChannel(state.opsRealtimeChannel);
  state.opsRealtimeChannel = null;
  state.opsPresenceUsers = [];
}

function startMessagingRealtime() {
  if (!USE_SUPABASE || !state.user || state.messagingRealtimeChannel) return;
  const channel = supabaseClient.channel('mo8-internal-messaging', { config: { presence: { key: state.user.UserID } } });
  ['chat_messages', 'chat_message_reactions', 'chat_message_acknowledgements', 'formal_message_recipients'].forEach((table) => {
    channel.on('postgres_changes', { event: '*', schema: 'public', table }, scheduleMessagingRefresh);
  });
  channel.on('presence', { event: 'sync' }, () => {
    state.messagingPresenceUsers = Object.values(channel.presenceState()).flat().map((row) => row.userId).filter(Boolean);
    if (state.activeView === 'messaging' && state.selectedConversationId) {
      const conversation = (state.messaging.conversations || []).find((row) => row.ConversationID === state.selectedConversationId);
      if (conversation) renderConversationDetails(conversation);
    }
  });
  channel.on('broadcast', { event: 'typing' }, ({ payload }) => {
    if (!payload?.userId) return;
    state.messagingTypingUsers[payload.userId] = { ...payload, at: Date.now() };
    updateTypingIndicator();
    window.setTimeout(updateTypingIndicator, 3600);
  });
  channel.subscribe(async (status) => {
    if (status === 'SUBSCRIBED') await channel.track({ userId: state.user.UserID, username: state.user.RobloxUsername, rank: state.user.Rank });
  });
  state.messagingRealtimeChannel = channel;
}

function scheduleMessagingRefresh() {
  window.clearTimeout(state.messagingRefreshTimer);
  state.messagingRefreshTimer = window.setTimeout(async () => {
    invalidateCache('messagingHub');
    const hub = await api('messagingHub', {});
    if (!hub.ok) return;
    state.messaging = { ...state.messaging, ...hub };
    state.unreadChatMessages = hub.unread || 0;
    updateChatBadge();
    if (state.activeView === 'messaging') {
      renderConversationList();
      if (state.messagingMode === 'chat' && state.selectedConversationId) await openChatConversation(state.selectedConversationId, false);
      else if (state.messagingMode === 'formal' && state.selectedFormalMessageId) renderFormalMessage(state.selectedFormalMessageId);
    }
    invalidateCache('personalInbox');
  }, 240);
}

function stopMessagingRealtime() {
  window.clearTimeout(state.messagingRefreshTimer);
  state.messagingRefreshTimer = null;
  if (state.messagingRealtimeChannel && supabaseClient) supabaseClient.removeChannel(state.messagingRealtimeChannel);
  state.messagingRealtimeChannel = null;
  state.messagingPresenceUsers = [];
  state.messagingTypingUsers = {};
}

