function renderDiscordAlertDefaultsPanel(config) {
  const container = document.querySelector('#discordAlertDefaultsPanel');
  if (!container) return;
  container.innerHTML = can('FULL_ACCESS')
    ? renderDiscordAlertPreferences(config, true)
    : emptyState('Full access is required to change Discord alert defaults.');
}

async function handleDiscordAlertSubmit(event) {
  const form = event.target.closest('[data-discord-alert-form]');
  if (!form) return;
  event.preventDefault();
  const mode = form.dataset.discordAlertForm;
  const rows = [...form.querySelectorAll('input[type="checkbox"][name]')].map((input) => {
    const [ScopeType, ...rest] = input.name.split(':');
    return { ScopeType, ScopeKey: rest.join(':'), Enabled: input.checked };
  });
  const button = form.querySelector('button[type="submit"]');
  const original = button?.textContent || 'Save';
  if (button) { button.disabled = true; button.textContent = 'Saving...'; }
  const response = await api(mode === 'defaults' ? 'saveDiscordAlertDefaults' : 'saveDiscordAlertPreferences', { Rows: rows });
  if (button) { button.disabled = false; button.textContent = original; }
  if (!response.ok) {
    showInfo('Discord alerts', `<p>${escapeHtml(response.error || 'Could not save Discord alert settings.')}</p>`);
    return;
  }
  invalidateCache('discordAlertConfig');
  showInfo('Discord alerts', '<p>Discord alert settings saved.</p>');
  if (mode === 'defaults') await loadSettings();
  else document.querySelector('#quickSettingsDialog')?.close();
}

function openBugReportEditor() {
  openEditor('Report a bug', [
    selectField('Area', 'Area', ['General', 'Dashboard', 'Tasks', 'Officer Profile', 'LOA', 'Users', 'Training', 'Documents', 'CAD', 'Recruitment', 'Other'], state.activeHub === 'operations' ? 'CAD' : state.activeView || 'General'),
    selectField('Severity', 'Severity', ['Low', 'Normal', 'High', 'Critical'], 'Normal'),
    field('Title', 'Short title', 'text', false),
    field('Description', 'What happened?', 'textarea', true),
    hiddenField('PageUrl', location.href),
  ], (values) => api('submitBugReport', values), { successMessage: 'Bug report submitted. Thank you, this has gone to the command review queue.' });
}

const PERSONNEL_DESIGNS = {
  default: { name: 'Current MDT', description: 'The established Personnel Hub appearance.' },
  civic: { name: 'Civic Precision', description: 'A crisp public-service workspace with compact geometry, strong hierarchy and minimal decoration.' },
  executive: { name: 'Executive Console', description: 'Dark, decisive navigation paired with bright operational work areas and restrained teal accents.' },
  glass: { name: 'Quiet Glass', description: 'A polished translucent workspace with soft depth, cooler surfaces and controlled contrast.' },
};

function switchSettingsPanel(panel = 'access') {
  document.querySelectorAll('[data-settings-panel]').forEach((button) => button.classList.toggle('active', button.dataset.settingsPanel === panel));
  document.querySelectorAll('[data-settings-workspace]').forEach((workspace) => { workspace.hidden = workspace.dataset.settingsWorkspace !== panel; });
}

function applyStoredPersonnelDesign() {
  const preset = localStorage.getItem(DESIGN_PRESET_STORAGE_KEY) || 'default';
  const density = localStorage.getItem(DESIGN_DENSITY_STORAGE_KEY) || 'comfortable';
  document.body.dataset.personnelTheme = PERSONNEL_DESIGNS[preset] ? preset : 'default';
  document.body.dataset.personnelDensity = density === 'compact' ? 'compact' : 'comfortable';
}

function applyPersonnelDesign(preset) {
  if (!PERSONNEL_DESIGNS[preset]) return;
  localStorage.setItem(DESIGN_PRESET_STORAGE_KEY, preset);
  document.body.dataset.personnelTheme = preset;
  renderDesignLabState();
}

function applyPersonnelDensity(density) {
  const value = density === 'compact' ? 'compact' : 'comfortable';
  localStorage.setItem(DESIGN_DENSITY_STORAGE_KEY, value);
  document.body.dataset.personnelDensity = value;
  renderDesignLabState();
}

function setDesignPreviewViewport(viewport) {
  document.querySelector('#designPreviewFrame')?.classList.toggle('mobile-preview', viewport === 'mobile');
  document.querySelectorAll('[data-design-viewport]').forEach((button) => button.classList.toggle('active', button.dataset.designViewport === viewport));
}

function renderDesignLabState() {
  const preset = document.body.dataset.personnelTheme || 'default';
  const density = document.body.dataset.personnelDensity || 'comfortable';
  const design = PERSONNEL_DESIGNS[preset] || PERSONNEL_DESIGNS.default;
  const name = document.querySelector('#designLabCurrent'); if (name) name.textContent = design.name;
  const description = document.querySelector('#designLabDescription'); if (description) description.textContent = design.description;
  document.querySelectorAll('[data-design-preset]').forEach((button) => button.classList.toggle('active', button.dataset.designPreset === preset));
  document.querySelectorAll('[data-design-density]').forEach((button) => button.classList.toggle('active', button.dataset.designDensity === density));
  if (!document.querySelector('[data-design-viewport].active')) setDesignPreviewViewport('desktop');
}

function resetPersonnelDesign() {
  localStorage.removeItem(DESIGN_PRESET_STORAGE_KEY);
  localStorage.removeItem(DESIGN_DENSITY_STORAGE_KEY);
  applyStoredPersonnelDesign();
  renderDesignLabState();
}

function personnelWorkspaceEnabled() {
  return localStorage.getItem(PERSONNEL_WORKSPACE_STORAGE_KEY) !== 'classic';
}

function syncPersonnelWorkspaceClass() {
  document.body.classList.toggle('personnel-workspace-v2', personnelWorkspaceEnabled() && state.activeHub === 'personnel');
}

function personnelOpenTabs() {
  try { return JSON.parse(sessionStorage.getItem(PERSONNEL_TABS_STORAGE_KEY) || '[]'); }
  catch (error) { return []; }
}

function savePersonnelOpenTabs(tabs) {
  sessionStorage.setItem(PERSONNEL_TABS_STORAGE_KEY, JSON.stringify(tabs.slice(-9)));
}

function setPersonnelWorkspaceMode(enabled) {
  localStorage.setItem(PERSONNEL_WORKSPACE_STORAGE_KEY, enabled ? 'desktop' : 'classic');
  syncPersonnelWorkspaceClass();
  const tabs = document.querySelector('#personnelWorkspaceTabs');
  if (tabs) tabs.hidden = !enabled;
  renderPersonnelWorkspaceTabs();
  const enable = document.querySelector('#enableDesktopWorkspaceButton');
  const disable = document.querySelector('#disableDesktopWorkspaceButton');
  if (enable) enable.disabled = enabled;
  if (disable) disable.disabled = !enabled;
}

function updatePersonnelWorkspaceTabs(view, label) {
  if (!personnelWorkspaceEnabled() || state.activeHub === 'operations') return;
  const officerId = view === 'officerProfile' ? state.selectedOfficerId || '' : '';
  const key = officerId ? `${view}:${officerId}` : view;
  let tabs = personnelOpenTabs().filter((tab) => tab && tab.key);
  const existing = tabs.find((tab) => tab.key === key);
  if (existing) existing.label = label;
  else tabs.push({ key, view, label, officerId });
  savePersonnelOpenTabs(tabs);
  renderPersonnelWorkspaceTabs(key);
}

function renderPersonnelWorkspaceTabs(activeKey = '') {
  const container = document.querySelector('#personnelWorkspaceTabs');
  if (!container) return;
  const enabled = personnelWorkspaceEnabled();
  container.hidden = !enabled;
  if (!enabled) return;
  const currentKey = activeKey || (state.activeView === 'officerProfile' && state.selectedOfficerId ? `officerProfile:${state.selectedOfficerId}` : state.activeView);
  const tabs = personnelOpenTabs();
  container.innerHTML = tabs.map((tab) => `<button type="button" class="personnel-workspace-tab${tab.key === currentKey ? ' active' : ''}" data-workspace-tab="${escapeHtml(tab.key)}"><span class="tab-symbol">${escapeHtml(String(tab.label || tab.view).slice(0, 2).toUpperCase())}</span><strong>${escapeHtml(tab.label || tab.view)}</strong><i data-close-workspace-tab="${escapeHtml(tab.key)}" aria-label="Close ${escapeHtml(tab.label || tab.view)}">&times;</i></button>`).join('') + '<button type="button" class="workspace-tab-home" data-workspace-home title="Open workstation desktop">+</button>';
}

async function handlePersonnelWorkspaceTabClick(event) {
  const close = event.target.closest('[data-close-workspace-tab]');
  if (close) {
    event.stopPropagation();
    const key = close.dataset.closeWorkspaceTab;
    const remaining = personnelOpenTabs().filter((tab) => tab.key !== key);
    savePersonnelOpenTabs(remaining);
    if (close.closest('.active')) {
      const next = remaining[remaining.length - 1];
      if (next) { if (next.officerId) state.selectedOfficerId = next.officerId; await showView(next.view); }
      else await showView(defaultView());
    } else renderPersonnelWorkspaceTabs();
    return;
  }
  if (event.target.closest('[data-workspace-home]')) { showHubSelector(); return; }
  const button = event.target.closest('[data-workspace-tab]');
  if (!button) return;
  const tab = personnelOpenTabs().find((item) => item.key === button.dataset.workspaceTab);
  if (!tab) return;
  if (tab.officerId) state.selectedOfficerId = tab.officerId;
  await showView(tab.view);
}

