function accessPreviewSelection() {
  const form = document.querySelector('#accessPreviewForm'); const data = new FormData(form);
  const rank = data.get('Rank') || 'Police Constable'; const roles = [...new Set([rankToRole(rank), ...data.getAll('PreviewRoles')])];
  const permissions = ALL_PERMISSIONS.filter((permission) => roles.some((role) => rolePermissionEnabled(role, permission)));
  return { rank, roles, tags: data.getAll('PreviewTags'), training: data.getAll('PreviewTraining'), permissions };
}

function updateAccessPreviewEstimate() {
  if (!state.permissionConfig?.permissions?.length) return;
  const selection = accessPreviewSelection(); const accessible = [...document.querySelectorAll('.nav-group .nav-item')].filter((button) => !button.dataset.permission || selection.permissions.includes('FULL_ACCESS') || selection.permissions.includes(button.dataset.permission)).map((button) => button.querySelector('span:nth-child(2)')?.textContent || button.innerText.trim());
  document.querySelector('#accessPreviewResult').innerHTML = `<div><span>Predicted access</span><strong>${escapeHtml(selection.rank)}</strong><small>${escapeHtml(selection.roles.join(', '))}</small></div><section><h4>${accessible.length} visible modules</h4><p>${escapeHtml(accessible.join(' / '))}</p></section><section><h4>${selection.permissions.length} effective permissions</h4><p>${escapeHtml(selection.permissions.join(' / ') || 'Profile-only access')}</p></section>${selection.tags.length || selection.training.length ? `<section><h4>Content context</h4><p>${escapeHtml([...selection.tags, ...selection.training].join(' / '))}</p></section>` : ''}`;
}

async function startAccessPreview(event) {
  event.preventDefault();
  if (!state.permissions.includes('FULL_ACCESS')) return showInfo('Preview unavailable', '<p>Command full access is required.</p>');
  state.accessPreview = accessPreviewSelection();
  document.body.classList.add('access-preview-mode');
  document.querySelector('#accessPreviewBanner').hidden = false;
  document.querySelector('#accessPreviewSummary').textContent = `${state.accessPreview.rank} / ${state.accessPreview.roles.join(', ')} / read-only`;
  applyPermissions();
  await showView(defaultView());
}

async function exitAccessPreview() {
  state.accessPreview = null; document.body.classList.remove('access-preview-mode'); document.querySelector('#accessPreviewBanner').hidden = true; applyPermissions(); await showView('settings');
}

function resetAccessPreviewForm() {
  document.querySelector('#accessPreviewForm').reset(); updateAccessPreviewEstimate();
}

function renderPermissionsMatrix() {
  const config = state.permissionConfig;
  const rows = config.permissions.map((permission) => {
    const cells = config.roles.map((role) => {
      const enabled = rolePermissionEnabled(role, permission) ? ' checked' : '';
      const disabled = permission === 'FULL_ACCESS' ? ' disabled' : '';
      return `<td data-label="${escapeHtml(role)}"><input type="checkbox" data-role-permission data-role="${escapeHtml(role)}" data-permission="${escapeHtml(permission)}"${enabled}${disabled}></td>`;
    }).join('');
    return `<tr><td data-label="Permission">${escapeHtml(permission)}</td>${cells}</tr>`;
  }).join('');
  document.querySelector('#permissionsMatrix').innerHTML = `
    <h3>Role permissions</h3>
    <div class="table-wrap compact">
      <table>
        <thead><tr><th>Permission</th>${config.roles.map((role) => `<th>${escapeHtml(role)}</th>`).join('')}</tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
  `;
}

function renderUserPermissionsMatrix() {
  const config = state.permissionConfig;
  const rows = config.users.map((user) => {
    const cells = config.permissions.map((permission) => {
      const mode = userPermissionMode(user.UserID, permission);
      const options = USER_PERMISSION_MODES.map((item) => `<option value="${escapeHtml(item)}"${item === mode ? ' selected' : ''}>${escapeHtml(item)}</option>`).join('');
      return `<td data-label="${escapeHtml(permission)}"><select data-user-permission data-user-id="${escapeHtml(user.UserID)}" data-permission="${escapeHtml(permission)}">${options}</select></td>`;
    }).join('');
    return `<tr><td data-label="User">${escapeHtml(user.RobloxUsername)}</td><td data-label="Role">${escapeHtml(user.Role)}</td>${cells}</tr>`;
  }).join('');
  document.querySelector('#userPermissionsMatrix').innerHTML = `
    <h3>User-specific overrides</h3>
    <div class="table-wrap compact">
      <table>
        <thead><tr><th>User</th><th>Role</th>${config.permissions.map((permission) => `<th>${escapeHtml(permission)}</th>`).join('')}</tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
  `;
}

function rolePermissionEnabled(role, permission) {
  const explicit = state.permissionConfig.rolePermissions.find((row) => row.Role === role && row.Permission === permission);
  if (explicit) return String(explicit.Allowed).toUpperCase() === 'TRUE';
  return Boolean((state.permissionConfig.defaultPermissions?.[role] || []).includes(permission));
}

function userPermissionMode(userId, permission) {
  const override = state.permissionConfig.userPermissions.find((row) => row.UserID === userId && row.Permission === permission);
  if (!override) return 'Inherit';
  return String(override.Allowed).toUpperCase() === 'TRUE' ? 'Allow' : 'Deny';
}

function permissionAuditRows() {
  const config = state.permissionConfig;
  if (!config) return [];
  const sensitive = ['FULL_ACCESS', 'MANAGE_PERMISSIONS', 'MANAGE_USERS', 'RESET_PASSWORDS', 'VIEW_AUDIT_LOG', 'CONTROL_OPERATIONS'];
  return config.users.map((user) => {
    const overrides = config.userPermissions.filter((row) => row.UserID === user.UserID);
    const effective = config.permissions.filter((permission) => {
      const override = overrides.find((row) => row.Permission === permission);
      if (override) return String(override.Allowed).toUpperCase() === 'TRUE';
      return rolePermissionEnabled(user.Role, permission);
    });
    const explicitAllows = overrides.filter((row) => String(row.Allowed).toUpperCase() === 'TRUE').map((row) => row.Permission);
    const sensitiveAccess = sensitive.filter((permission) => effective.includes(permission));
    const reasons = [];
    let Risk = 'Normal';
    if (effective.includes('FULL_ACCESS')) { Risk = 'Critical'; reasons.push('Full Access enabled'); }
    else if (sensitiveAccess.length >= 3 || explicitAllows.some((permission) => sensitive.includes(permission))) { Risk = 'High'; reasons.push('Multiple privileged capabilities'); }
    else if (overrides.length || user.Status !== 'Active') { Risk = 'Review'; reasons.push(overrides.length ? `${overrides.length} individual override(s)` : 'Account is not active'); }
    return { ...user, Effective: effective, Overrides: overrides, ExplicitAllows: explicitAllows, Sensitive: sensitiveAccess, Risk, Reasons: reasons };
  });
}

function renderPermissionAudit() {
  const container = document.querySelector('#permissionAuditResults');
  if (!container || !state.permissionConfig) return;
  const query = String(document.querySelector('#permissionAuditSearch')?.value || '').trim().toLowerCase();
  const risk = document.querySelector('#permissionAuditRisk')?.value || '';
  const allRows = permissionAuditRows();
  const rows = allRows.filter((row) => (!risk || row.Risk === risk) && (!query || [row.RobloxUsername, row.Role, row.Rank, row.Status, ...row.Effective, ...row.ExplicitAllows].some((value) => String(value || '').toLowerCase().includes(query))));
  document.querySelector('#permissionAuditSummary').innerHTML = [
    stat('Accounts reviewed', allRows.length), stat('Critical', allRows.filter((row) => row.Risk === 'Critical').length),
    stat('High risk', allRows.filter((row) => row.Risk === 'High').length), stat('With overrides', allRows.filter((row) => row.Overrides.length).length),
  ].join('');
  container.innerHTML = rows.length ? rows.map((row) => `<article class="permission-audit-row risk-${row.Risk.toLowerCase()}"><div class="permission-risk">${escapeHtml(row.Risk)}</div><div><span>${escapeHtml(row.Role)} / ${escapeHtml(row.Rank)} / ${escapeHtml(row.Status)}</span><strong>${escapeHtml(row.RobloxUsername)}</strong><p>${escapeHtml(row.Reasons.join(' / ') || 'No elevated-access concerns detected.')}</p><small>${escapeHtml(row.Sensitive.length ? `Privileged: ${row.Sensitive.join(', ')}` : `${row.Effective.length} effective permissions`)}</small></div><div class="permission-override-summary"><b>${row.Overrides.length}</b><span>Overrides</span><small>${escapeHtml(row.ExplicitAllows.join(', ') || 'None explicitly allowed')}</small></div></article>`).join('') : emptyState('No accounts match this audit view.');
}

