function supabaseEmailForLogin(username) {
  const raw = String(username || '').trim();
  if (raw.includes('@')) return raw;
  return `${raw.toLowerCase().replace(/[^a-z0-9._-]/g, '')}@mo8.local`;
}

async function supabaseCurrentProfile() {
  const { data: authData, error: authError } = await supabaseClient.auth.getUser();
  if (authError || !authData.user) return { ok: false, error: authError?.message || 'Not signed in.' };

  const { data: profile, error } = await supabaseClient
    .from('profiles')
    .select('*')
    .eq('auth_user_id', authData.user.id)
    .maybeSingle();
  if (error) return { ok: false, error: error.message };
  if (!profile) return { ok: false, error: 'This Supabase login is not linked to an MDT profile yet.' };

  const permissions = await supabasePermissions(profile);
  return { ok: true, user: supabaseUser(profile), permissions };
}

async function supabasePermissions(profile) {
  const checks = await Promise.all(ALL_PERMISSIONS.map(async (permission) => {
    const { data, error } = await supabaseClient.rpc('has_permission', { permission_name: permission });
    if (error) throw new Error(error.message);
    return data ? permission : '';
  }));
  return checks.filter(Boolean);
}

async function supabaseMyProfile() {
  const me = await supabaseCurrentProfile();
  if (!me.ok) return me;
  const profile = await supabaseProfileByUserId(me.user.UserID);
  const officer = await supabaseOfficerForMember(profile.member_id);
  const [training, matrix, discipline, loa, shifts, rankChanges, notifications, documents, announcements, profiles, officers, probation, performanceReviews, restrictions, officerNotes, aips, aipSignatures] = await Promise.all([
    officer ? supabaseRows('training_records', 'officer_id', officer.officer_id) : [],
    officer ? supabaseRows('training_matrix', 'officer_id', officer.officer_id) : [],
    officer ? supabaseRows('disciplinary_actions', 'officer_id', officer.officer_id) : [],
    officer ? supabaseRows('loa_requests', 'officer_id', officer.officer_id) : [],
    officer ? supabaseRows('shift_logs', 'officer_id', officer.officer_id, 'started_at') : [],
    supabaseRows('rank_changes', 'member_id', profile.member_id, 'changed_at'),
    supabaseNotificationRows(profile.member_id),
    supabaseVisibleDocuments(),
    supabaseVisibleAnnouncements(),
    supabaseAll('profiles'),
    supabaseAll('officers'),
    officer ? supabaseOptionalRows('probation_records', 'officer_id', officer.officer_id) : [],
    officer ? supabaseOptionalRows('performance_reviews', 'officer_id', officer.officer_id, 'review_date') : [],
    officer ? supabaseOptionalRows('officer_restrictions', 'officer_id', officer.officer_id) : [],
    officer ? supabaseOptionalRows('officer_notes', 'officer_id', officer.officer_id, 'created_at') : [],
    officer ? supabaseOptionalRows('activity_improvement_notices', 'officer_id', officer.officer_id, 'created_at') : [],
    supabaseOptionalAll('aip_signatures'),
  ]);
  return {
    ok: true,
    user: me.user,
    officer: officer ? decorateSupabaseOfficer(officer, { loa, shifts, profiles, officers }) : null,
    training: [...training.map(supabaseTrainingRecord), ...matrix.flatMap(supabaseTrainingMatrixRecords)],
    discipline: discipline.map(supabaseDiscipline),
    loa: loa.map((row) => supabaseLoa(row, officer || {}, profiles)),
    transfers: [],
    supervisorRequests: [],
    appeals: [],
    checkins: [],
    developmentPlans: [],
    probation: probation.map((row) => ({ ProbationID: row.probation_id, OfficerID: row.officer_id, Stage: row.stage, Status: row.status, Progress: row.progress, StartDate: row.start_date, TargetDate: row.target_date, Requirements: row.requirements, Notes: row.notes })),
    performanceReviews: performanceReviews.map((row) => ({ ReviewID: row.review_id, OfficerID: row.officer_id, ReviewDate: row.review_date, PeriodStart: row.period_start, PeriodEnd: row.period_end, Rating: row.rating, ActivitySummary: row.activity_summary, Strengths: row.strengths, Improvements: row.improvements, Objectives: row.objectives, NextReviewDate: row.next_review_date })),
    restrictions: restrictions.map((row) => ({ RestrictionID: row.restriction_id, OfficerID: row.officer_id, RestrictionType: row.restriction_type, Details: row.details, StartsOn: row.starts_on, EndsOn: row.ends_on, Status: row.status })),
    aips: aips.map((row) => mapAip(row, officers, profiles, aipSignatures)),
    officerNotes: officerNotes.map((row) => supabaseOfficerNote(row, profiles)),
    shifts: shifts.map(supabaseShift),
    shiftStatus: await supabaseShiftStatus(),
    rankChanges: rankChanges.map(supabaseRankChange),
    documents: documents.rows || [],
    announcements: announcements.rows || [],
    notifications,
  };
}

async function supabaseDashboard() {
  const [officers, loa, documents, announcements, actions, widgetPreferences, pinnedRows, profiles, shifts] = await Promise.all([
    supabaseClient.from('officers').select('*'),
    supabaseClient.from('loa_requests').select('*'),
    supabaseVisibleDocuments(),
    supabaseVisibleAnnouncements(),
    supabaseMyActions(),
    state.user?.UserID ? supabaseRows('dashboard_widgets', 'user_id', state.user.UserID) : [],
    supabasePinnedOfficerRows(),
    supabaseAll('profiles'),
    supabaseAll('shift_logs'),
  ]);
  if (officers.error) return { ok: false, error: officers.error.message };
  if (loa.error) return { ok: false, error: loa.error.message };
  const activeLoa = (loa.data || []).filter((row) => row.status === 'Approved' && isTodayInRange(row.start_date, row.end_date));
  const pendingLoa = (loa.data || []).filter((row) => row.status === 'Pending');
  return {
    ok: true,
    widgets: widgetPreferences.length ? widgetPreferences.filter((row) => row.enabled).map((row) => row.widget_key) : DASHBOARD_WIDGETS.map(([key]) => key),
    counts: {
      activeOfficers: (officers.data || []).filter((row) => row.status === 'Active').length,
      currentlyOnLoa: activeLoa.length,
      loaPending: pendingLoa.length,
      pendingAppeals: 0,
      trainingReviewsDue: 0,
      pendingAcknowledgements: 0,
      upcomingTraining: 0,
    },
    activeLoa: activeLoa.map((row) => supabaseLoa(row, (officers.data || []).find((officer) => officer.officer_id === row.officer_id) || {}, profiles || [])).slice(0, 5),
    pendingLoa: pendingLoa.map((row) => supabaseLoa(row, (officers.data || []).find((officer) => officer.officer_id === row.officer_id) || {}, profiles || [])).slice(0, 5),
    announcements: announcements.rows || [],
    recentDocuments: documents.rows || [],
    trainingReviewsDue: [],
    recentAudit: [],
    pendingAppeals: [],
    unassignedOfficers: (officers.data || []).filter((row) => row.status !== 'Archived' && !row.supervisor_user_id).map(supabaseOfficer).slice(0, 5),
    lowActivity: [],
    documentAcknowledgements: [],
    upcomingTraining: [],
    myActions: actions.rows || [],
    pinnedOfficers: pinnedRows.map((pin) => {
      const officer = (officers.data || []).find((row) => row.officer_id === pin.officer_id) || {};
      return { ...decorateSupabaseOfficer(officer, { loa: loa.data || [], shifts, profiles }), Reason: pin.reason || '' };
    }).filter((row) => row.OfficerID),
  };
}

async function supabaseSaveDashboardWidgets(data) {
  const me = await supabaseCurrentProfile();
  if (!me.ok) return me;
  const widgets = splitTags(data.Widgets || '');
  const rows = DASHBOARD_WIDGETS.map(([key]) => ({
    user_id: me.user.UserID,
    widget_key: key,
    enabled: widgets.includes(key),
    updated_at: new Date().toISOString(),
  }));
  const { error } = await supabaseClient.from('dashboard_widgets').upsert(rows, { onConflict: 'user_id,widget_key' });
  return error ? { ok: false, error: error.message } : { ok: true, widgets };
}

async function supabasePinnedOfficerRows() {
  if (!state.user?.UserID) return [];
  try {
    const { data, error } = await supabaseClient
      .from('pinned_officers')
      .select('*')
      .eq('user_id', state.user.UserID)
      .order('created_at', { ascending: false });
    if (error) throw new Error(error.message);
    return data || [];
  } catch (error) {
    if (/does not exist|schema cache/i.test(error.message || '')) return [];
    throw error;
  }
}

async function supabaseTogglePinnedOfficer(data) {
  const me = await supabaseCurrentProfile();
  if (!me.ok) return me;
  const officerId = data.OfficerID || '';
  if (!officerId) return { ok: false, error: 'Officer is required.' };
  let existing = null;
  try {
    const result = await supabaseClient
      .from('pinned_officers')
      .select('*')
      .eq('user_id', me.user.UserID)
      .eq('officer_id', officerId)
      .limit(1)
      .maybeSingle();
    if (result.error) throw new Error(result.error.message);
    existing = result.data;
  } catch (error) {
    if (/does not exist|schema cache/i.test(error.message || '')) return { ok: false, error: 'Run the pinned officers migration before using officer pins.' };
    throw error;
  }
  if (existing) {
    const { error } = await supabaseClient.from('pinned_officers').delete().eq('pin_id', existing.pin_id);
    return error ? { ok: false, error: error.message } : { ok: true, pinned: false };
  }
  const { error } = await supabaseClient.from('pinned_officers').upsert({
    user_id: me.user.UserID,
    officer_id: officerId,
    reason: data.Reason || '',
    created_at: new Date().toISOString(),
  }, { onConflict: 'user_id,officer_id' });
  return error ? { ok: false, error: error.message } : { ok: true, pinned: true };
}

async function supabaseMyActions() {
  const me = await supabaseCurrentProfile();
  if (!me.ok) return me;
  const profile = await supabaseProfileByUserId(me.user.UserID);
  const officer = await supabaseOfficerForMember(profile.member_id);
  const [documents, acknowledgements, courses, bookings, training, reviews, probation, restrictions, handovers, notifications, incidentReviews, actionReviews, incidents, caseActions, cases, briefings, briefingAcks, deployments] = await Promise.all([
    supabaseVisibleDocuments(), supabaseAll('document_acknowledgements'), supabaseAll('training_courses'), supabaseAll('course_bookings'),
    officer ? supabaseRows('training_records', 'officer_id', officer.officer_id) : [], officer ? supabaseOptionalRows('performance_reviews', 'officer_id', officer.officer_id) : [],
    officer ? supabaseOptionalRows('probation_records', 'officer_id', officer.officer_id) : [], officer ? supabaseOptionalRows('officer_restrictions', 'officer_id', officer.officer_id) : [],
    can('VIEW_TASKS') ? supabaseOptionalAll('handover_entries') : [], supabaseNotificationRows(profile.member_id),
    supabaseOptionalAll('operational_incident_reviews'),
    supabaseOptionalAll('operational_action_reviews'),
    supabaseOptionalAll('operational_incidents'),
    supabaseOptionalAll('operational_case_actions'),
    supabaseOptionalAll('operational_operations'),
    supabaseOptionalAll('operational_briefings'),
    supabaseOptionalAll('operational_briefing_acknowledgements'),
    supabaseOptionalAll('operational_deployments'),
  ]);
  const now = new Date();
  const inDays = (value) => Math.ceil((new Date(value) - now) / 86400000);
  const rows = [];
  (documents.rows || []).filter((doc) => truthy(doc.RequiresAcknowledgement) && !acknowledgements.some((ack) => ack.document_id === doc.DocumentID && ack.user_id === me.user.UserID)).forEach((doc) => rows.push({ Group: 'Urgent', Priority: 'High', Type: 'Document', Title: doc.Title, Detail: 'Acknowledgement required.', View: 'documents' }));
  const expiringTraining = training.filter((row) => row.expiry_date && inDays(row.expiry_date) <= 60);
  expiringTraining.forEach((row) => rows.push({ Group: inDays(row.expiry_date) < 0 ? 'Urgent' : 'Due Soon', Priority: inDays(row.expiry_date) < 0 ? 'Critical' : 'High', Type: 'Training', Title: `${row.standard} ${inDays(row.expiry_date) < 0 ? 'expired' : 'expires soon'}`, Detail: `Expiry: ${formatDisplayDate(row.expiry_date)}`, DueDate: row.expiry_date, View: 'myProfile' }));
  await Promise.all(expiringTraining.map((row) => {
    const marker = `${row.standard} / ${row.expiry_date}`;
    if (notifications.some((notice) => String(notice.Message || '').includes(marker))) return null;
    return supabaseNotify(profile.member_id, inDays(row.expiry_date) < 0 ? 'Training qualification expired' : 'Training qualification expiring', `${marker}. Please contact a trainer or your supervisor to arrange renewal.`, me.user.UserID);
  }));
  courses.filter((course) => new Date(course.course_date) >= now && bookings.some((booking) => booking.course_id === course.course_id && booking.officer_id === officer?.officer_id && ['Approved', 'Waitlist'].includes(booking.status))).forEach((course) => rows.push({ Group: 'Upcoming', Priority: 'Normal', Type: 'Course', Title: course.title, Detail: `${course.location || 'Location TBC'} / ${formatDisplayDateTime(course.course_date)}`, DueDate: course.course_date, View: 'courses' }));
  reviews.filter((row) => row.next_review_date && inDays(row.next_review_date) <= 30).forEach((row) => rows.push({ Group: 'Due Soon', Priority: 'High', Type: 'Review', Title: 'Performance review due', Detail: `Due ${formatDisplayDate(row.next_review_date)}`, DueDate: row.next_review_date, View: 'myProfile' }));
  probation.filter((row) => row.status === 'Active').forEach((row) => rows.push({ Group: 'Information', Priority: 'Normal', Type: 'Probation', Title: `${row.stage} probation`, Detail: `${row.progress}% complete`, DueDate: row.target_date, View: 'myProfile' }));
  restrictions.filter((row) => row.status === 'Active').forEach((row) => rows.push({ Group: 'Urgent', Priority: 'High', Type: 'Restriction', Title: row.restriction_type, Detail: row.details || 'Active restriction on your officer record.', DueDate: row.ends_on, View: 'myProfile' }));
  handovers.filter((row) => row.status !== 'Resolved' && (row.owner_user_id === me.user.UserID || (row.recipient_user_ids || []).includes(me.user.UserID) || !row.owner_user_id)).forEach((row) => rows.push({ Group: row.priority === 'Critical' ? 'Urgent' : 'Due Soon', Priority: row.priority, Type: 'Handover', Title: row.title, Detail: row.details, DueDate: row.due_at, View: 'handover' }));
  incidentReviews.filter((row) => row.status === 'Amendments Required' && row.amendment_assignee_user_id === me.user.UserID).forEach((row) => {
    const incident = incidents.find((item) => item.incident_id === row.incident_id) || {};
    rows.push({ Group: 'Urgent', Priority: 'Critical', Type: 'CAD Amendments', Title: `${incident.incident_number || row.incident_id} / ${incident.title || 'Incident review'}`, Detail: row.feedback || 'Your supervisor has requested changes to this CAD.', IncidentID: row.incident_id, ReviewID: row.review_id, AmendmentType: 'Incident', View: 'inbox' });
  });
  actionReviews.filter((row) => row.status === 'Amendments Required' && row.officer_id === officer?.officer_id).forEach((row) => {
    const incident = incidents.find((item) => item.incident_id === row.incident_id) || {};
    rows.push({ Group: 'Urgent', Priority: 'Critical', Type: 'Action Amendments', Title: `${row.action_type} / ${incident.incident_number || row.incident_id}`, Detail: row.supervisor_feedback || 'Your supervisor has requested changes to this operational action.', IncidentID: row.incident_id, ReviewID: row.action_review_id, AmendmentType: 'Action', View: 'inbox' });
  });
  caseActions.filter((row) => row.assigned_officer_id === officer?.officer_id && !['Completed', 'Cancelled'].includes(row.status)).forEach((row) => {
    const caseRecord = cases.find((item) => item.operation_id === row.operation_id) || {};
    rows.push({ Group: row.priority === 'Critical' ? 'Urgent' : 'Casework', Priority: row.priority || 'Normal', Type: 'Casework Action', Title: row.title, Detail: `${caseRecord.reference || 'Case'} / ${row.details || row.status}`, DueDate: row.due_at, OperationsTarget: `Case:${row.operation_id}`, View: 'inbox' });
  });
  briefings.filter((row) => row.status === 'Active' && !briefingAcks.some((ack) => ack.briefing_id === row.briefing_id && ack.officer_id === officer?.officer_id)).forEach((row) => rows.push({ Group: 'Urgent', Priority: 'High', Type: 'Briefing', Title: row.title, Detail: `${row.patrol_area || 'All areas'} / acknowledgement required`, DueDate: row.starts_at, OperationsTarget: 'Briefings', View: 'inbox' }));
  deployments.filter((row) => (row.assigned_officer_ids || []).includes(officer?.officer_id) && !['Completed', 'Cancelled'].includes(row.status)).forEach((row) => rows.push({ Group: 'Upcoming', Priority: 'Normal', Type: 'Deployment', Title: row.title, Detail: `${formatDisplayDateTime(row.starts_at)} / ${row.location || 'TBC'}`, DueDate: row.starts_at, OperationsTarget: 'Deployments', View: 'inbox' }));
  return { ok: true, rows };
}

async function supabasePersonalInbox() {
  const me = await supabaseCurrentProfile();
  if (!me.ok) return me;
  const profile = await supabaseProfileByUserId(me.user.UserID);
  const officer = await supabaseOfficerForMember(profile.member_id);
  const [actions, notifications, documents, acknowledgements, calendar, tasks, supervisorRequests, messaging] = await Promise.all([
    supabaseMyActions(),
    supabaseNotificationRows(profile.member_id),
    supabaseVisibleDocuments(),
    supabaseAll('document_acknowledgements'),
    supabaseOperationalCalendar(),
    supabaseTasks(),
    officer ? supabaseOptionalRows('supervisor_requests', 'officer_id', officer.officer_id, 'created_at') : [],
    supabaseMessagingHub(),
  ]);
  if (!actions.ok) return actions;
  if (!calendar.ok) return calendar;
  const pendingDocs = (documents.rows || []).filter((doc) => truthy(doc.RequiresAcknowledgement) && !acknowledgements.some((ack) => ack.document_id === doc.DocumentID && ack.user_id === me.user.UserID));
  const now = Date.now();
  const calendarRows = (calendar.rows || [])
    .filter((row) => row.Start && new Date(row.Start).getTime() >= now)
    .sort((a, b) => new Date(a.Start) - new Date(b.Start))
    .slice(0, 8)
    .map((row) => ({ Type: row.Type || 'Calendar', Priority: row.Priority || 'Normal', Title: row.Title, Detail: [formatDisplayDateTime(row.Start), row.Location, row.Detail].filter(Boolean).join(' / '), DueDate: row.Start, View: 'calendar' }));
  const notificationRows = (notifications || []).slice(0, 10).map((row) => ({ Type: row.ReadAt ? 'Notification' : 'Unread Notification', Priority: importantNotice(row) ? 'Critical' : positiveNotice(row) ? 'Low' : 'Normal', Title: row.Title, Detail: row.Message, CreatedAt: row.CreatedAt, View: 'myProfile' }));
  const taskRows = (tasks.myTasks || (can('VIEW_TASKS') ? [
    ...(tasks.pendingLoa || []),
    ...(tasks.pendingTransfers || []),
    ...(tasks.pendingSupervisorRequests || []),
    ...(tasks.pendingCourseBookings || []),
    ...(tasks.pendingAppeals || []),
    ...(tasks.probationReviews || []),
    ...(tasks.performanceReviews || []),
    ...(tasks.restrictionReviews || []),
    ...(tasks.retrospectiveShifts || []),
  ] : [])).map((row) => ({ Type: row.TaskType, Priority: row.Priority || (row.MySupervisee ? 'High' : 'Normal'), Title: row.Subject || row.Officer || row.Course || row.TaskType, Detail: row.Reason || row.Status || '', DueDate: row.EndDate || row.TargetDate || row.NextReviewDate || row.RequestedAt || '', Status: row.Status, View: 'tasks' }));
  const docRows = pendingDocs.map((doc) => ({ Type: 'Document', Priority: 'High', Title: doc.Title, Detail: `${doc.Category || 'Document'} acknowledgement required`, CreatedAt: doc.UpdatedAt, View: 'documents' }));
  const supervisorRows = (supervisorRequests || []).slice(0, 8).map((row) => ({ Type: 'Supervisor', Priority: row.status === 'Pending' ? 'High' : 'Normal', Title: row.subject || 'Supervisor request', Detail: `${row.category || 'General'} / ${row.status || 'Pending'}${row.review_reason ? ` / ${row.review_reason}` : ''}`, CreatedAt: row.created_at, Status: row.status, View: 'myProfile' }));
  const actionRows = (actions.rows || []).map((row) => ({ ...row, Type: row.Type || 'Action', View: row.View || 'dashboard' }));
  const messageRows = [
    ...(messaging.formalMessages || []).filter((row) => !row.ReadAt || (row.RequiresAcknowledgement && !row.AcknowledgedAt)).map((row) => ({ Type: 'Formal Message', Priority: row.Importance === 'Urgent' ? 'Critical' : row.Importance === 'Important' ? 'High' : 'Normal', Title: row.Subject, Detail: `${row.SenderName}${row.RequiresAcknowledgement && !row.AcknowledgedAt ? ' / acknowledgement required' : ' / unread'}`, CreatedAt: row.CreatedAt, View: 'messaging' })),
    ...(messaging.unread ? [{ Type: 'Chat', Priority: 'Normal', Title: `${messaging.unread} unread communication${messaging.unread === 1 ? '' : 's'}`, Detail: 'Open Chat to review recent messages.', View: 'messaging' }] : []),
  ];
  const important = [...actionRows, ...taskRows, ...docRows, ...notificationRows, ...calendarRows, ...supervisorRows, ...messageRows]
    .filter((row) => ['Critical', 'High'].includes(row.Priority) || String(row.Type || '').includes('Unread'))
    .sort((a, b) => priorityWeight(b.Priority) - priorityWeight(a.Priority));
  return {
    ok: true,
    actions: [...messageRows, ...actionRows],
    tasks: taskRows,
    notifications: notificationRows,
    calendar: calendarRows,
    documents: docRows,
    supervisor: supervisorRows,
    priority: important,
    counts: {
      urgent: important.length,
      unread: notifications.filter((row) => !row.ReadAt).length + (messaging.unread || 0),
      actions: actionRows.length + messageRows.length,
      tasks: taskRows.length,
      documents: docRows.length,
      calendar: calendarRows.length,
    },
  };
}

function priorityWeight(priority) {
  return { Critical: 4, High: 3, Normal: 2, Low: 1 }[priority] || 0;
}

async function supabaseMessagingDirectory() {
  const { data, error } = await supabaseClient.rpc('messaging_directory');
  if (error) throw new Error(error.message);
  return (data || []).map((row) => ({ UserID: row.user_id, MemberID: row.member_id, RobloxUsername: row.roblox_username, Rank: row.rank, Callsign: row.callsign, Meta: row.callsign || '' }));
}

async function supabaseMessagingHub() {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me;
  await ensureSupervisorConversation(me.user.UserID);
  const [conversations, memberships, messages, formalMessages, formalRecipients, directory] = await Promise.all([
    supabaseOptionalAll('chat_conversations'), supabaseOptionalAll('chat_members'), supabaseOptionalAll('chat_messages'),
    supabaseOptionalAll('formal_messages'), supabaseOptionalAll('formal_message_recipients'), supabaseMessagingDirectory(),
  ]);
  const person = (userId) => directory.find((row) => row.UserID === userId) || { RobloxUsername: userId, Rank: '' };
  const visibleConversations = conversations.map((conversation) => {
    const members = memberships.filter((row) => row.conversation_id === conversation.conversation_id);
    const lastRead = members.find((row) => row.user_id === me.user.UserID)?.last_read_at || '';
    const conversationMessages = messages.filter((row) => row.conversation_id === conversation.conversation_id).sort((a, b) => String(a.created_at).localeCompare(String(b.created_at)));
    const last = conversationMessages[conversationMessages.length - 1];
    const other = members.find((row) => row.user_id !== me.user.UserID);
    const title = conversation.conversation_type === 'Direct' && other ? person(other.user_id).RobloxUsername : conversation.title;
    return {
      ConversationID: conversation.conversation_id, Type: conversation.conversation_type, Title: title, Description: conversation.description,
      MinimumRank: conversation.minimum_rank || '', LinkedRecordType: conversation.linked_record_type || '', LinkedRecordID: conversation.linked_record_id || '',
      CreatedBy: conversation.created_by, IsOwner: conversation.created_by === me.user.UserID, UpdatedAt: conversation.updated_at,
      Members: members.map((row) => ({ ...person(row.user_id), MemberRole: row.member_role })),
      LastMessage: last?.deleted_at ? 'Message deleted' : last?.body || (last?.attachments?.length ? 'Shared an attachment' : ''), LastMessageAt: last?.created_at || conversation.updated_at,
      LastSender: last ? person(last.sender_user_id).RobloxUsername : '', Unread: conversationMessages.filter((row) => row.sender_user_id !== me.user.UserID && (!lastRead || row.created_at > lastRead)).length,
    };
  }).sort((a, b) => String(b.LastMessageAt).localeCompare(String(a.LastMessageAt)));
  const formal = formalMessages.map((row) => {
    const ownRecipient = formalRecipients.find((recipient) => recipient.formal_message_id === row.formal_message_id && recipient.recipient_user_id === me.user.UserID);
    return {
      FormalMessageID: row.formal_message_id, Subject: row.subject, Body: row.body, Importance: row.importance, RequiresAcknowledgement: row.requires_acknowledgement,
      DueAt: row.due_at || '', LinkedRecord: row.linked_record || {}, Attachments: row.attachments || [], SenderUserID: row.sender_user_id,
      SenderName: person(row.sender_user_id).RobloxUsername, SenderRank: person(row.sender_user_id).Rank, CreatedAt: row.created_at, ReadAt: ownRecipient?.read_at || (row.sender_user_id === me.user.UserID ? row.created_at : ''), AcknowledgedAt: ownRecipient?.acknowledged_at || '',
      Recipients: formalRecipients.filter((recipient) => recipient.formal_message_id === row.formal_message_id).map((recipient) => ({ ...person(recipient.recipient_user_id), ReadAt: recipient.read_at || '', AcknowledgedAt: recipient.acknowledged_at || '' })),
    };
  }).sort((a, b) => String(b.CreatedAt).localeCompare(String(a.CreatedAt)));
  return { ok: true, conversations: visibleConversations, formalMessages: formal, directory, unread: visibleConversations.reduce((sum, row) => sum + row.Unread, 0) + formal.filter((row) => !row.ReadAt).length };
}

async function ensureSupervisorConversation(userId) {
  const profile = await supabaseProfileByUserId(userId);
  const officer = profile ? await supabaseOfficerForMember(profile.member_id) : null;
  if (!officer?.supervisor_user_id) return;
  const [conversations, memberships] = await Promise.all([supabaseOptionalAll('chat_conversations'), supabaseOptionalAll('chat_members')]);
  const exists = conversations.some((conversation) => conversation.conversation_type === 'Supervisor' && !conversation.archived_at && (() => {
    const ids = memberships.filter((member) => member.conversation_id === conversation.conversation_id).map((member) => member.user_id);
    return ids.includes(userId) && ids.includes(officer.supervisor_user_id);
  })());
  if (exists) return;
  await supabaseClient.rpc('create_chat_conversation', {
    conversation_type_arg: 'Supervisor',
    title_arg: 'Supervisor chat',
    description_arg: 'Private communication between an officer and their assigned supervisor.',
    member_user_ids_arg: [officer.supervisor_user_id],
    linked_record_type_arg: null,
    linked_record_id_arg: null,
  });
}

async function supabaseChatConversation(data) {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me;
  const conversation = await supabaseById('chat_conversations', 'conversation_id', data.ConversationID);
  if (!conversation) return { ok: false, error: 'Conversation not found or you do not have access.' };
  const [messages, members, reactions, acknowledgements, directory] = await Promise.all([
    supabaseRows('chat_messages', 'conversation_id', data.ConversationID, 'created_at'), supabaseRows('chat_members', 'conversation_id', data.ConversationID),
    supabaseOptionalAll('chat_message_reactions'), supabaseOptionalAll('chat_message_acknowledgements'), supabaseMessagingDirectory(),
  ]);
  await supabaseClient.from('chat_members').upsert({ conversation_id: data.ConversationID, user_id: me.user.UserID, member_role: conversation.created_by === me.user.UserID ? 'Owner' : 'Member', last_read_at: new Date().toISOString() }, { onConflict: 'conversation_id,user_id' });
  const person = (userId) => directory.find((row) => row.UserID === userId) || { RobloxUsername: userId, Rank: '' };
  const otherMember = members.find((row) => row.user_id !== me.user.UserID);
  const displayTitle = conversation.conversation_type === 'Direct' && otherMember ? person(otherMember.user_id).RobloxUsername : conversation.title;
  return {
    ok: true,
    conversation: { ConversationID: conversation.conversation_id, Type: conversation.conversation_type, Title: displayTitle, Description: conversation.description, LinkedRecordType: conversation.linked_record_type || '', LinkedRecordID: conversation.linked_record_id || '', IsOwner: conversation.created_by === me.user.UserID },
    members: members.map((row) => ({ ...person(row.user_id), MemberRole: row.member_role, LastReadAt: row.user_id === me.user.UserID ? new Date().toISOString() : row.last_read_at || '' })),
    messages: messages.map((row) => ({ MessageID: row.message_id, ConversationID: row.conversation_id, SenderUserID: row.sender_user_id, SenderName: person(row.sender_user_id).RobloxUsername, SenderRank: person(row.sender_user_id).Rank, Body: row.body, ReplyToMessageID: row.reply_to_message_id || '', Importance: row.importance, RequiresAcknowledgement: row.requires_acknowledgement, Pinned: row.pinned, Attachments: row.attachments || [], LinkedRecord: row.linked_record || {}, CreatedAt: row.created_at, EditedAt: row.edited_at || '', DeletedAt: row.deleted_at || '' })),
    reactions: reactions.filter((row) => messages.some((message) => message.message_id === row.message_id)).map((row) => ({ MessageID: row.message_id, UserID: row.user_id, Reaction: row.reaction })),
    acknowledgements: acknowledgements.filter((row) => messages.some((message) => message.message_id === row.message_id)).map((row) => ({ MessageID: row.message_id, UserID: row.user_id, AcknowledgedAt: row.acknowledged_at })),
  };
}

async function supabaseCreateChatConversation(data) {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me;
  const type = data.ConversationType || 'Direct';
  const memberIds = [...new Set(splitTags(data.MemberUserIDs || '').filter((id) => id && id !== me.user.UserID))];
  if (!memberIds.length) return { ok: false, error: 'Select at least one other officer.' };
  if (type === 'Direct' && memberIds.length !== 1) return { ok: false, error: 'A direct message must contain exactly one other officer.' };
  if (type === 'Direct') {
    const [existingConversations, existingMembers] = await Promise.all([supabaseOptionalAll('chat_conversations'), supabaseOptionalAll('chat_members')]);
    const existing = existingConversations.find((conversation) => conversation.conversation_type === 'Direct' && !conversation.archived_at && (() => {
      const ids = existingMembers.filter((member) => member.conversation_id === conversation.conversation_id).map((member) => member.user_id);
      return ids.length === 2 && ids.includes(me.user.UserID) && ids.includes(memberIds[0]);
    })());
    if (existing) return { ok: true, ConversationID: existing.conversation_id, warning: 'Your existing direct conversation was opened.' };
  }
  const directory = await supabaseMessagingDirectory();
  const linkedTypes = ['CAD', 'Case', 'Callsign'];
  const title = String(data.Title || '').trim() || (type === 'Direct' ? directory.find((row) => row.UserID === memberIds[0])?.RobloxUsername : `${type} conversation`);
  const { data: conversationId, error } = await supabaseClient.rpc('create_chat_conversation', {
    conversation_type_arg: type,
    title_arg: title,
    description_arg: data.Description || '',
    member_user_ids_arg: memberIds,
    linked_record_type_arg: linkedTypes.includes(type) ? type : null,
    linked_record_id_arg: linkedTypes.includes(type) ? data.LinkedRecordID || null : null,
  });
  if (error || !conversationId) return { ok: false, error: error?.message || 'Conversation could not be created.' };
  await supabaseAudit(me.user.UserID, 'Create Chat', 'Conversation', conversationId, { Type: type, Members: memberIds });
  return { ok: true, ConversationID: conversationId };
}

async function supabaseUpdateChatConversation(data) {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me;
  const update = await supabaseClient.from('chat_conversations').update({ title: data.Title, description: data.Description || '', updated_at: new Date().toISOString() }).eq('conversation_id', data.ConversationID);
  if (update.error) return { ok: false, error: update.error.message };
  if (data.MemberUserIDs !== undefined) {
    const ids = [...new Set([me.user.UserID, ...splitTags(data.MemberUserIDs || '')])];
    await supabaseClient.from('chat_members').delete().eq('conversation_id', data.ConversationID).neq('user_id', me.user.UserID);
    const rows = ids.filter((id) => id !== me.user.UserID).map((userId) => ({ conversation_id: data.ConversationID, user_id: userId, member_role: 'Member' }));
    if (rows.length) { const inserted = await supabaseClient.from('chat_members').insert(rows); if (inserted.error) return { ok: false, error: inserted.error.message }; }
  }
  return { ok: true };
}

function safeChatFileName(name) {
  return String(name || 'attachment').replace(/[^A-Za-z0-9._-]/g, '_').slice(-120);
}

async function uploadChatAttachment(folderId, file) {
  if (!(file instanceof File) || !file.size) return [];
  if (file.size > 10 * 1024 * 1024) throw new Error('Chat attachments must be 10 MB or smaller.');
  const path = `${folderId}/${crypto.randomUUID()}-${safeChatFileName(file.name)}`;
  const upload = await supabaseClient.storage.from('mo8-chat-files').upload(path, file, { contentType: file.type || 'application/octet-stream' });
  if (upload.error) throw new Error(upload.error.message);
  return [{ path, name: file.name, size: file.size, type: file.type || 'application/octet-stream' }];
}

async function supabaseSendChatMessage(data) {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me;
  const attachments = await uploadChatAttachment(data.ConversationID, data.Attachment);
  const linkedRecord = data.LinkedRecordType && data.LinkedRecordID ? { type: data.LinkedRecordType, id: data.LinkedRecordID, label: data.LinkedRecordID } : {};
  const { error } = await supabaseClient.from('chat_messages').insert({ conversation_id: data.ConversationID, sender_user_id: me.user.UserID, body: String(data.Body || '').trim(), reply_to_message_id: data.ReplyToMessageID || null, importance: data.Importance || 'Normal', requires_acknowledgement: data.RequiresAcknowledgement === 'true', attachments, linked_record: linkedRecord });
  return error ? { ok: false, error: error.message } : { ok: true };
}

async function supabaseUpdateChatMessage(data) {
  const existing = await supabaseById('chat_messages', 'message_id', data.MessageID);
  const update = { body: String(data.Body || ''), edited_at: new Date().toISOString() };
  if (data.Pinned !== undefined) update.pinned = Boolean(data.Pinned);
  const { error } = await supabaseClient.from('chat_messages').update(update).eq('message_id', data.MessageID);
  if (error) return { ok: false, error: error.message };
  await supabaseAudit(state.user.UserID, data.Pinned !== undefined ? 'Pin Chat Message' : 'Edit Chat Message', 'ChatMessage', data.MessageID, { ConversationID: existing?.conversation_id || '', Pinned: update.pinned });
  return { ok: true };
}

async function supabaseDeleteChatMessage(data) {
  const existing = await supabaseById('chat_messages', 'message_id', data.MessageID);
  const { error } = await supabaseClient.from('chat_messages').update({ body: '', attachments: [], linked_record: {}, deleted_at: new Date().toISOString(), edited_at: new Date().toISOString() }).eq('message_id', data.MessageID);
  if (error) return { ok: false, error: error.message };
  await supabaseAudit(state.user.UserID, 'Delete Chat Message', 'ChatMessage', data.MessageID, { ConversationID: existing?.conversation_id || '' });
  return { ok: true };
}

async function supabaseToggleChatReaction(data) {
  const existing = await supabaseClient.from('chat_message_reactions').select('message_id').eq('message_id', data.MessageID).eq('user_id', state.user.UserID).eq('reaction', data.Reaction).maybeSingle();
  const response = existing.data ? await supabaseClient.from('chat_message_reactions').delete().eq('message_id', data.MessageID).eq('user_id', state.user.UserID).eq('reaction', data.Reaction) : await supabaseClient.from('chat_message_reactions').insert({ message_id: data.MessageID, user_id: state.user.UserID, reaction: data.Reaction });
  return response.error ? { ok: false, error: response.error.message } : { ok: true };
}

async function supabaseAcknowledgeChatMessage(data) {
  const { error } = await supabaseClient.from('chat_message_acknowledgements').upsert({ message_id: data.MessageID, user_id: state.user.UserID }, { onConflict: 'message_id,user_id' });
  return error ? { ok: false, error: error.message } : { ok: true };
}

async function supabaseSendFormalMessage(data) {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me;
  const recipients = [...new Set(splitTags(data.RecipientUserIDs || '').filter((id) => id && id !== me.user.UserID))];
  if (!recipients.length) return { ok: false, error: 'Select at least one recipient.' };
  if (!String(data.Subject || '').trim() || !String(data.Body || '').trim()) return { ok: false, error: 'A subject and message are required.' };
  const linkedRecord = data.LinkedRecordType && data.LinkedRecordID ? { type: data.LinkedRecordType, id: data.LinkedRecordID, label: data.LinkedRecordID } : {};
  const { data: saved, error } = await supabaseClient.from('formal_messages').insert({ subject: data.Subject, body: data.Body, importance: data.Importance || 'Normal', requires_acknowledgement: data.RequiresAcknowledgement === 'true', due_at: data.DueAt || null, linked_record: linkedRecord, sender_user_id: me.user.UserID }).select('*').maybeSingle();
  if (error || !saved) return { ok: false, error: error?.message || 'Formal message could not be created.' };
  const recipientInsert = await supabaseClient.from('formal_message_recipients').insert(recipients.map((userId) => ({ formal_message_id: saved.formal_message_id, recipient_user_id: userId })));
  if (recipientInsert.error) { await supabaseClient.from('formal_messages').delete().eq('formal_message_id', saved.formal_message_id); return { ok: false, error: recipientInsert.error.message }; }
  const attachments = await uploadChatAttachment(saved.formal_message_id, data.Attachment);
  if (attachments.length) await supabaseClient.from('formal_messages').update({ attachments }).eq('formal_message_id', saved.formal_message_id);
  const directory = await supabaseMessagingDirectory();
  await Promise.all(recipients.map((userId) => supabaseNotify(directory.find((row) => row.UserID === userId)?.MemberID, `Formal message: ${data.Subject}`, `From ${me.user.RobloxUsername}. Open the MDT Chat section to read${data.RequiresAcknowledgement === 'true' ? ' and acknowledge' : ''} this message.`, me.user.UserID)));
  await supabaseAudit(me.user.UserID, 'Send Formal Message', 'FormalMessage', saved.formal_message_id, { Subject: data.Subject, Recipients: recipients, Importance: data.Importance || 'Normal' });
  return { ok: true, FormalMessageID: saved.formal_message_id };
}

async function supabaseMarkFormalMessageRead(data) {
  const { error } = await supabaseClient.from('formal_message_recipients').update({ read_at: new Date().toISOString() }).eq('formal_message_id', data.FormalMessageID).eq('recipient_user_id', state.user.UserID).is('read_at', null);
  return error ? { ok: false, error: error.message } : { ok: true };
}

async function supabaseAcknowledgeFormalMessage(data) {
  const now = new Date().toISOString();
  const { error } = await supabaseClient.from('formal_message_recipients').update({ read_at: now, acknowledged_at: now }).eq('formal_message_id', data.FormalMessageID).eq('recipient_user_id', state.user.UserID);
  return error ? { ok: false, error: error.message } : { ok: true };
}

async function supabaseOpenChatAttachment(data) {
  const { data: signed, error } = await supabaseClient.storage.from('mo8-chat-files').createSignedUrl(data.Path, 60 * 15);
  return error || !signed?.signedUrl ? { ok: false, error: error?.message || 'Secure attachment link could not be created.' } : { ok: true, Url: signed.signedUrl };
}

async function supabaseGlobalSearch(data) {
  const query = String(data.Query || '').trim().toLowerCase();
  if (query.length < 2) return { ok: true, rows: [] };
  const [officers, documents, courses, announcements, incidents, people, vehicles, cases, deployments, tasks, offences, powers, loa, aips, shifts, evidence] = await Promise.all([
    supabaseAll('officers'), supabaseVisibleDocuments(), supabaseAll('training_courses'), supabaseVisibleAnnouncements(),
    supabaseOptionalAll('operational_incidents'), supabaseOptionalAll('operational_persons'), supabaseOptionalAll('operational_vehicles'),
    supabaseOptionalAll('operational_operations'), supabaseOptionalAll('operational_deployments'), supabaseOptionalAll('mdt_tasks'),
    supabaseOptionalAll('operational_offences'), supabaseOptionalAll('operational_powers'), supabaseOptionalAll('loa_requests'),
    supabaseOptionalAll('activity_improvement_notices'), supabaseOptionalAll('shift_logs'), supabaseOptionalAll('operational_incident_attachments'),
  ]);
  const matches = (values) => values.some((value) => String(value || '').toLowerCase().includes(query));
  const officerName = (id) => officers.find((row) => row.officer_id === id)?.roblox_username || id || 'Officer';
  const incidentReference = (id) => incidents.find((row) => row.incident_id === id)?.incident_number || id || 'CAD';
  return { ok: true, rows: [
    ...officers.filter((row) => matches([row.roblox_username, row.callsign, row.rank, row.tags?.join(' ')])).map((row) => ({ Type: 'Officers', Title: row.roblox_username, Detail: `${row.rank} / ${row.callsign || 'No callsign'}`, Meta: row.status, OfficerID: row.officer_id })),
    ...(documents.rows || []).filter((row) => matches([row.Title, row.Category, row.FileName])).map((row) => ({ Type: 'Documents', Title: row.Title, Detail: row.Category, Meta: row.FileName, View: 'documents' })),
    ...courses.filter((row) => matches([row.title, row.standard, row.location])).map((row) => ({ Type: 'Courses', Title: row.title, Detail: `${row.standard} / ${formatDisplayDateTime(row.course_date)}`, Meta: row.status, View: 'courses' })),
    ...(announcements.rows || []).filter((row) => matches([row.Title, row.Body, row.Audience])).map((row) => ({ Type: 'Notices', Title: row.Title, Detail: row.Body, Meta: row.Audience, View: 'announcements' })),
    ...incidents.filter((row) => matches([row.incident_number, row.title, row.location, row.description, row.outcome])).map((row) => ({ Type: 'CAD', Title: `${row.incident_number} / ${row.title}`, Detail: `${row.location || 'No location'} / ${row.priority}`, Meta: row.status, OperationsTarget: `Incident:${row.incident_id}` })),
    ...people.filter((row) => matches([row.display_name, row.roblox_username, ...(row.aliases || [])])).map((row) => ({ Type: 'People', Title: row.display_name, Detail: row.roblox_username || 'No username', Meta: 'Intelligence record', OperationsTarget: `Person:${row.person_id}` })),
    ...vehicles.filter((row) => matches([row.registration, row.make, row.model, row.colour])).map((row) => ({ Type: 'Vehicles', Title: row.registration, Detail: [row.colour, row.make, row.model].filter(Boolean).join(' '), Meta: row.status, OperationsTarget: `Vehicle:${row.vehicle_id}` })),
    ...cases.filter((row) => matches([row.reference, row.name, row.summary, row.objectives, row.case_type])).map((row) => ({ Type: 'Casework', Title: `${row.reference} / ${row.name}`, Detail: row.summary || row.objectives, Meta: row.status, OperationsTarget: `Case:${row.operation_id}` })),
    ...deployments.filter((row) => matches([row.title, row.deployment_type, row.location, row.briefing])).map((row) => ({ Type: 'Deployments', Title: row.title, Detail: `${formatDisplayDateTime(row.starts_at)} / ${row.location || 'TBC'}`, Meta: row.status, OperationsTarget: 'Deployments' })),
    ...tasks.filter((row) => matches([row.title, row.details, row.category, row.priority, row.status, officerName(row.assigned_officer_id)])).map((row) => ({ Type: 'Tasks', Title: row.title, Detail: `${officerName(row.assigned_officer_id)} / ${row.category}`, Meta: `${row.priority} / ${row.status}`, View: 'tasks' })),
    ...offences.filter((row) => matches([row.title, row.code, row.category, row.description])).map((row) => ({ Type: 'Offences', Title: row.title, Detail: `${row.code} / ${row.category}`, Meta: row.active === false ? 'Inactive' : 'Current', OperationsTarget: `Reference:${row.title}` })),
    ...powers.filter((row) => matches([row.title, row.code, row.category, row.definition, row.legal_test, row.legislation_source, row.section_reference])).map((row) => ({ Type: 'Police Powers', Title: row.title, Detail: `${row.code} / ${row.section_reference || row.category}`, Meta: row.legislation_source, OperationsTarget: `Reference:${row.title}` })),
    ...loa.filter((row) => matches([officerName(row.officer_id), row.reason, row.status, row.decision_reason])).map((row) => ({ Type: 'Leave', Title: `${officerName(row.officer_id)} / ${row.status}`, Detail: `${formatDisplayDate(row.start_date)} - ${formatDisplayDate(row.end_date)}`, Meta: row.reason, View: 'loa' })),
    ...aips.filter((row) => !row.archived_at && matches([row.reference, officerName(row.officer_id), row.reason, row.status, row.review_outcome])).map((row) => ({ Type: 'AIPs', Title: `${row.reference} / ${officerName(row.officer_id)}`, Detail: row.reason, Meta: row.status, View: 'development' })),
    ...shifts.filter((row) => matches([row.roblox_username, row.callsign, row.rank, row.summary, row.status, row.operational_status])).map((row) => ({ Type: 'Shifts', Title: `${row.roblox_username || officerName(row.officer_id)} / ${formatDisplayDateTime(row.started_at)}`, Detail: row.summary || row.operational_status || row.status, Meta: row.callsign, View: 'shift' })),
    ...evidence.filter((row) => matches([row.title, row.file_name, row.file_type, incidentReference(row.incident_id)])).map((row) => ({ Type: 'Evidence', Title: row.title || row.file_name, Detail: `${incidentReference(row.incident_id)} / ${row.file_name}`, Meta: row.file_type, OperationsTarget: `Incident:${row.incident_id}` })),
  ].slice(0, 250) };
}

async function supabaseTimelineSubjects(data) {
  const query = String(data.Query || '').trim();
  if (query.length < 2) return { ok: true, rows: [] };
  const [officers, incidents, people, vehicles, cases] = await Promise.all([
    supabaseSearchTable('officers', ['roblox_username', 'callsign', 'rank'], query),
    supabaseSearchTable('operational_incidents', ['incident_number', 'title', 'location'], query),
    supabaseSearchTable('operational_persons', ['display_name', 'roblox_username'], query),
    supabaseSearchTable('operational_vehicles', ['registration', 'make', 'model', 'colour'], query),
    supabaseSearchTable('operational_operations', ['reference', 'name', 'summary'], query),
  ]);
  return { ok: true, rows: [
    ...officers.map((row) => ({ Type: 'Officer', ID: row.officer_id, Title: row.roblox_username, Subtitle: `${row.rank} / ${row.callsign || 'No callsign'} / ${row.status}`, Destination: `Officer:${row.officer_id}` })),
    ...incidents.map((row) => ({ Type: 'CAD', ID: row.incident_id, Title: `${row.incident_number} / ${row.title}`, Subtitle: `${row.location || 'No location'} / ${row.status}`, Destination: `Incident:${row.incident_id}` })),
    ...people.map((row) => ({ Type: 'Person', ID: row.person_id, Title: row.display_name, Subtitle: row.roblox_username || 'Intelligence record', Destination: `Person:${row.person_id}` })),
    ...vehicles.map((row) => ({ Type: 'Vehicle', ID: row.vehicle_id, Title: row.registration, Subtitle: [row.colour, row.make, row.model, row.status].filter(Boolean).join(' / '), Destination: `Vehicle:${row.vehicle_id}` })),
    ...cases.map((row) => ({ Type: 'Case', ID: row.operation_id, Title: `${row.reference} / ${row.name}`, Subtitle: `${row.case_type || 'Casework'} / ${row.status}`, Destination: `Case:${row.operation_id}` })),
  ].slice(0, 50) };
}

async function supabaseEntityTimeline(data) {
  const type = String(data.SubjectType || '');
  const id = String(data.SubjectID || '');
  if (!id || !['Officer', 'CAD', 'Person', 'Vehicle', 'Case'].includes(type)) return { ok: false, error: 'Choose a valid timeline record.' };
  const profiles = await supabaseOptionalSelect('profiles', 'user_id,roblox_username');
  const actor = (userId) => profiles.find((row) => row.user_id === userId)?.roblox_username || '';
  const events = [];
  const add = (Date, Area, Type, Title, Detail = '', extra = {}) => { if (Date) events.push({ Date, Area, Type, Title, Detail, Severity: 'Information', ...extra }); };
  let subject = { Type: type, ID: id, Title: id, Subtitle: '', Destination: `${type}:${id}` };

  if (type === 'Officer') {
    const officer = await supabaseById('officers', 'officer_id', id);
    if (!officer) return { ok: false, error: 'Officer record not found.' };
    subject = { Type: 'Officer', ID: id, Title: officer.roblox_username, Subtitle: `${officer.rank} / ${officer.callsign || 'No callsign'} / ${officer.status}`, Destination: `Officer:${id}` };
    const [ranks, training, discipline, loa, shifts, tasks, aips, actions] = await Promise.all([
      supabaseOptionalRows('rank_changes', 'officer_id', id, 'changed_at'), supabaseOptionalRows('training_records', 'officer_id', id, 'updated_at'),
      supabaseOptionalRows('disciplinary_actions', 'officer_id', id, 'issued_at'), supabaseOptionalRows('loa_requests', 'officer_id', id, 'created_at'),
      supabaseOptionalRows('shift_logs', 'officer_id', id, 'started_at'), supabaseOptionalRows('mdt_tasks', 'assigned_officer_id', id, 'created_at'),
      supabaseOptionalRows('activity_improvement_notices', 'officer_id', id, 'created_at'), supabaseOptionalRows('operational_officer_actions', 'officer_id', id, 'occurred_at'),
    ]);
    add(officer.created_at, 'Personnel', 'Officer Record', 'Officer added to the MDT', `${officer.rank} / ${officer.callsign || 'No callsign'}`, { OfficerID: id, Reference: id });
    ranks.forEach((row) => add(row.changed_at, 'Personnel', 'Rank Change', `${row.previous_rank || 'Unrecorded'} to ${row.new_rank}`, row.reason || '', { OfficerID: id, Actor: actor(row.changed_by), Reference: row.change_id }));
    training.forEach((row) => add(row.updated_at || row.date_completed, 'Personnel', 'Training', row.standard, `${row.status}${row.notes ? ` / ${row.notes}` : ''}`, { OfficerID: id, Reference: row.training_id }));
    discipline.forEach((row) => add(row.issued_at, 'Personnel', 'Discipline', row.type, row.summary || row.details || '', { OfficerID: id, Actor: actor(row.issued_by), Reference: row.action_id, Severity: 'High' }));
    loa.forEach((row) => add(row.reviewed_at || row.created_at, 'Personnel', 'Leave', `${row.status} LOA`, `${formatDisplayDate(row.start_date)} - ${formatDisplayDate(row.end_date)} / ${row.reason || ''}`, { OfficerID: id, Actor: actor(row.reviewed_by), Reference: row.request_id }));
    shifts.forEach((row) => add(row.ended_at || row.started_at, 'Personnel', 'Shift', row.status || 'Shift', row.summary || `${row.callsign || ''} / ${row.operational_status || ''}`, { OfficerID: id, Reference: row.shift_id }));
    tasks.forEach((row) => add(row.updated_at || row.created_at, 'Personnel', 'Task', row.title, `${row.status} / ${row.details || ''}`, { OfficerID: id, View: 'tasks', Reference: row.task_id, Severity: row.priority === 'Critical' ? 'Critical' : row.priority === 'High' ? 'High' : 'Information' }));
    aips.filter((row) => !row.archived_at).forEach((row) => add(row.reviewed_at || row.updated_at || row.created_at, 'Personnel', 'AIP', row.reference, `${row.status} / ${row.reason}`, { OfficerID: id, View: 'development', Reference: row.aip_id, Severity: 'Warning' }));
    actions.forEach((row) => add(row.occurred_at || row.created_at, 'Operations', 'Officer Action', row.action_type, row.notes || row.outcome_report || '', { OfficerID: id, OperationsTarget: `Incident:${row.incident_id}`, Reference: row.action_id }));
  } else if (type === 'CAD') {
    const incident = await supabaseById('operational_incidents', 'incident_id', id);
    if (!incident) return { ok: false, error: 'CAD record not found.' };
    subject = { Type: 'CAD', ID: id, Title: `${incident.incident_number} / ${incident.title}`, Subtitle: `${incident.location || 'No location'} / ${incident.status}`, Destination: `Incident:${id}` };
    const [logs, evidence, disposals, powers, actions, reviews] = await Promise.all([
      supabaseOptionalRows('operational_incident_logs', 'incident_id', id, 'created_at'), supabaseOptionalRows('operational_incident_attachments', 'incident_id', id, 'created_at'),
      supabaseOptionalRows('operational_disposals', 'incident_id', id, 'issued_at'), supabaseOptionalRows('operational_power_uses', 'incident_id', id, 'occurred_at'),
      supabaseOptionalRows('operational_officer_actions', 'incident_id', id, 'occurred_at'), supabaseOptionalRows('operational_incident_reviews', 'incident_id', id, 'reviewed_at'),
    ]);
    add(incident.created_at, 'Operations', 'CAD Created', `${incident.incident_number} / ${incident.title}`, incident.description || incident.location || '', { OperationsTarget: `Incident:${id}`, Actor: actor(incident.created_by), Reference: incident.incident_number });
    if (incident.closed_at) add(incident.closed_at, 'Operations', 'CAD Closed', incident.closure_code || incident.outcome || 'Closed', incident.outcome || '', { OperationsTarget: `Incident:${id}`, Reference: incident.incident_number });
    logs.forEach((row) => add(row.created_at, 'Operations', 'CAD Log', row.entry_type, row.body || '', { OperationsTarget: `Incident:${id}`, Actor: actor(row.created_by), Reference: row.log_id }));
    evidence.forEach((row) => add(row.created_at, 'Operations', 'Evidence', row.title || row.file_name, row.file_type || '', { OperationsTarget: `Incident:${id}`, Actor: actor(row.uploaded_by), Reference: row.attachment_id }));
    disposals.forEach((row) => add(row.issued_at, 'Operations', 'Outcome', row.outcome_type, row.notes || '', { OperationsTarget: `Incident:${id}`, Actor: actor(row.issued_by), Reference: row.disposal_id }));
    powers.forEach((row) => add(row.occurred_at || row.created_at, 'Operations', 'Power Used', row.outcome || 'Power recorded', row.grounds || '', { OperationsTarget: `Incident:${id}`, Actor: actor(row.created_by), Reference: row.power_use_id }));
    actions.forEach((row) => add(row.occurred_at || row.created_at, 'Operations', 'Officer Action', row.action_type, row.notes || '', { OperationsTarget: `Incident:${id}`, Actor: actor(row.created_by), Reference: row.action_id }));
    reviews.forEach((row) => add(row.completed_at || row.created_at, 'Operations', 'Supervisor Review', row.status, row.feedback || '', { OperationsTarget: `Incident:${id}`, Actor: actor(row.reviewer_user_id), Reference: row.review_id }));
  } else if (type === 'Case') {
    const record = await supabaseById('operational_operations', 'operation_id', id);
    if (!record) return { ok: false, error: 'Case record not found.' };
    subject = { Type: 'Case', ID: id, Title: `${record.reference} / ${record.name}`, Subtitle: `${record.case_type || 'Casework'} / ${record.status}`, Destination: `Case:${id}` };
    const [updates, actions, links] = await Promise.all([supabaseOptionalRows('operational_case_updates', 'operation_id', id, 'created_at'), supabaseOptionalRows('operational_case_actions', 'operation_id', id, 'created_at'), supabaseOptionalRows('operational_operation_links', 'operation_id', id, 'created_at')]);
    add(record.created_at, 'Operations', 'Case Created', record.name, record.summary || record.objectives || '', { OperationsTarget: `Case:${id}`, Actor: actor(record.created_by), Reference: record.reference });
    updates.forEach((row) => add(row.created_at, 'Operations', 'Case Update', row.update_type, row.body || '', { OperationsTarget: `Case:${id}`, Actor: actor(row.created_by), Reference: row.update_id }));
    actions.forEach((row) => add(row.updated_at || row.created_at, 'Operations', 'Case Action', row.title, `${row.status} / ${row.details || ''}`, { OperationsTarget: `Case:${id}`, Actor: actor(row.created_by), Reference: row.action_id }));
    links.forEach((row) => add(row.created_at, 'Operations', 'Record Linked', `${row.subject_type} linked`, row.notes || row.relationship || '', { OperationsTarget: `Case:${id}`, Actor: actor(row.created_by), Reference: row.operation_link_id }));
  } else {
    const table = type === 'Person' ? 'operational_persons' : 'operational_vehicles';
    const key = type === 'Person' ? 'person_id' : 'vehicle_id';
    const record = await supabaseById(table, key, id);
    if (!record) return { ok: false, error: `${type} record not found.` };
    subject = type === 'Person'
      ? { Type: 'Person', ID: id, Title: record.display_name, Subtitle: record.roblox_username || 'Intelligence record', Destination: `Person:${id}` }
      : { Type: 'Vehicle', ID: id, Title: record.registration, Subtitle: [record.colour, record.make, record.model, record.status].filter(Boolean).join(' / '), Destination: `Vehicle:${id}` };
    const [links, disposals, powers, markers] = await Promise.all([
      supabaseOptionalRows('operational_incident_entities', key, id, 'created_at'), supabaseOptionalRows('operational_disposals', key, id, 'issued_at'),
      supabaseOptionalRows('operational_power_uses', key, id, 'occurred_at'), supabaseOptionalRows('operational_intel_markers', key, id, 'created_at'),
    ]);
    const incidentIds = [...new Set(links.map((row) => row.incident_id).filter(Boolean))];
    const incidents = await supabaseOptionalIn('operational_incidents', 'incident_id', incidentIds);
    add(record.created_at, 'Intelligence', `${type} Record`, `${subject.Title} added`, record.notes || subject.Subtitle, { OperationsTarget: `${type}:${id}`, Actor: actor(record.created_by), Reference: id });
    links.forEach((row) => { const cad = incidents.find((item) => item.incident_id === row.incident_id) || {}; add(row.created_at || cad.created_at, 'Operations', 'CAD Link', `${cad.incident_number || row.incident_id} / ${row.involvement_role}`, row.notes || cad.title || '', { OperationsTarget: `Incident:${row.incident_id}`, Actor: actor(row.created_by), Reference: cad.incident_number || row.incident_id }); });
    disposals.forEach((row) => add(row.issued_at, 'Operations', 'Outcome', row.outcome_type, row.notes || '', { OperationsTarget: `Incident:${row.incident_id}`, Actor: actor(row.issued_by), Reference: row.disposal_id }));
    powers.forEach((row) => add(row.occurred_at || row.created_at, 'Operations', 'Power Used', row.outcome, row.grounds || '', { OperationsTarget: `Incident:${row.incident_id}`, Actor: actor(row.created_by), Reference: row.power_use_id }));
    markers.forEach((row) => add(row.created_at, 'Intelligence', 'Warning Marker', row.marker_type, row.details || '', { OperationsTarget: `${type}:${id}`, Actor: actor(row.created_by), Reference: row.marker_id, Severity: row.severity === 'Critical' ? 'Critical' : 'High' }));
  }
  return { ok: true, subject, rows: events.sort((a, b) => String(b.Date).localeCompare(String(a.Date))).slice(0, 500) };
}

async function supabaseSystemTimeline() {
  const [officers, profiles, ranks, training, discipline, loa, shifts, tasks, aips, incidents, logs, caseUpdates, evidence] = await Promise.all([
    supabaseAll('officers'), supabaseAll('profiles'), supabaseOptionalAll('rank_changes'), supabaseOptionalAll('training_records'),
    supabaseOptionalAll('disciplinary_actions'), supabaseOptionalAll('loa_requests'), supabaseOptionalAll('shift_logs'),
    supabaseOptionalAll('mdt_tasks'), supabaseOptionalAll('activity_improvement_notices'), supabaseOptionalAll('operational_incidents'),
    supabaseOptionalAll('operational_incident_logs'), supabaseOptionalAll('operational_case_updates'), supabaseOptionalAll('operational_incident_attachments'),
  ]);
  const officer = (id) => officers.find((row) => row.officer_id === id) || {};
  const profile = (id) => profiles.find((row) => row.user_id === id) || {};
  const incident = (id) => incidents.find((row) => row.incident_id === id) || {};
  const rows = [];
  const add = (Date, Area, Type, Title, Detail = '', extra = {}) => { if (Date) rows.push({ Date, Area, Type, Title, Detail, Severity: 'Information', ...extra }); };
  ranks.forEach((row) => add(row.changed_at, 'Personnel', 'Rank Change', `${officer(row.officer_id).roblox_username || 'Officer'}: ${row.previous_rank || 'Unrecorded'} to ${row.new_rank}`, row.reason || '', { OfficerID: row.officer_id, Actor: profile(row.changed_by).roblox_username || '', Reference: row.change_id }));
  training.forEach((row) => add(row.updated_at || row.date_completed, 'Personnel', 'Training', `${officer(row.officer_id).roblox_username || 'Officer'} / ${row.standard}`, `${row.status}${row.notes ? ` / ${row.notes}` : ''}`, { OfficerID: row.officer_id, Reference: row.training_id }));
  discipline.forEach((row) => add(row.issued_at, 'Personnel', 'Discipline', `${officer(row.officer_id).roblox_username || 'Officer'} / ${row.type}`, row.summary, { OfficerID: row.officer_id, Actor: profile(row.issued_by).roblox_username || '', Reference: row.action_id, Severity: 'High' }));
  loa.forEach((row) => add(row.reviewed_at || row.created_at || row.start_date, 'Personnel', 'Leave', `${officer(row.officer_id).roblox_username || 'Officer'} / ${row.status}`, `${formatDisplayDate(row.start_date)} - ${formatDisplayDate(row.end_date)}${row.reason ? ` / ${row.reason}` : ''}`, { OfficerID: row.officer_id, View: 'loa', Reference: row.request_id, Actor: profile(row.reviewed_by).roblox_username || '' }));
  shifts.forEach((row) => add(row.ended_at || row.started_at, 'Personnel', 'Shift', `${row.roblox_username || officer(row.officer_id).roblox_username || 'Officer'} / ${row.status}`, row.summary || `${row.callsign || 'No callsign'} / ${row.operational_status || ''}`, { OfficerID: row.officer_id, View: 'shift', Reference: row.shift_id }));
  tasks.forEach((row) => add(row.updated_at || row.created_at, 'Personnel', 'Task', row.title, `${officer(row.assigned_officer_id).roblox_username || 'Unassigned'} / ${row.status} / ${row.details || ''}`, { View: 'tasks', OfficerID: row.assigned_officer_id, Reference: row.task_id, Severity: row.priority === 'Critical' ? 'Critical' : row.priority === 'High' ? 'High' : 'Information' }));
  aips.filter((row) => !row.archived_at).forEach((row) => add(row.reviewed_at || row.updated_at || row.created_at, 'Personnel', 'AIP', `${row.reference} / ${officer(row.officer_id).roblox_username || 'Officer'}`, `${row.status} / ${row.reason}`, { OfficerID: row.officer_id, View: 'development', Reference: row.aip_id, Severity: ['No Improvement', 'Partial Improvement'].includes(row.review_outcome) ? 'High' : 'Warning' }));
  incidents.forEach((row) => add(row.closed_at || row.updated_at || row.created_at, 'Operations', 'CAD', `${row.incident_number} / ${row.title}`, `${row.status} / ${row.location || 'No location'} / ${row.outcome || row.closure_code || ''}`, { OperationsTarget: `Incident:${row.incident_id}`, Reference: row.incident_number, Actor: profile(row.created_by).roblox_username || '', Severity: row.priority === 'Immediate' ? 'Critical' : row.priority === 'Priority' ? 'High' : 'Information' }));
  logs.forEach((row) => { const cad = incident(row.incident_id); add(row.created_at, 'Operations', 'CAD Log', `${cad.incident_number || row.incident_id} / ${row.entry_type}`, row.body || '', { OperationsTarget: `Incident:${row.incident_id}`, Reference: cad.incident_number || row.incident_id, Actor: profile(row.created_by).roblox_username || '' }); });
  caseUpdates.forEach((row) => add(row.created_at, 'Operations', 'Case Update', row.update_type || 'Case update', row.body || '', { OperationsTarget: `Case:${row.operation_id}`, Reference: row.operation_id, Actor: profile(row.created_by).roblox_username || '' }));
  evidence.forEach((row) => { const cad = incident(row.incident_id); add(row.created_at, 'Operations', 'Evidence', row.title || row.file_name, `${cad.incident_number || row.incident_id} / ${row.file_type || 'File'}`, { OperationsTarget: `Incident:${row.incident_id}`, Reference: row.attachment_id, Actor: profile(row.uploaded_by).roblox_username || '' }); });
  return { ok: true, rows: rows.sort((a, b) => String(b.Date).localeCompare(String(a.Date))).slice(0, 750) };
}

async function supabaseDataQualityCentre() {
  if (!can('VIEW_AUDIT_LOG') && !can('FULL_ACCESS')) return { ok: false, error: 'You do not have permission to review system data quality.' };
  const [officers, profiles, tasks, loa, aips, incidents, entities, people, vehicles, evidence, documents, cases] = await Promise.all([
    supabaseOptionalSelect('officers', 'officer_id,member_id,roblox_username,callsign,status,supervisor_user_id'),
    supabaseOptionalSelect('profiles', 'user_id,member_id,roblox_username,status'),
    supabaseOptionalSelect('mdt_tasks', 'task_id,title,status,priority,due_at,assigned_officer_id', (query) => query.in('status', ['Open', 'In Progress', 'Blocked'])),
    supabaseOptionalSelect('loa_requests', 'request_id,officer_id,start_date,end_date,status'),
    supabaseOptionalSelect('activity_improvement_notices', 'aip_id,reference,officer_id,status,review_end_date,archived_at', (query) => query.is('archived_at', null)),
    supabaseOptionalSelect('operational_incidents', 'incident_id,incident_number,title,status,outcome,closure_code,updated_at,created_at'),
    supabaseOptionalSelect('operational_incident_entities', 'incident_id,person_id,vehicle_id'),
    supabaseOptionalSelect('operational_persons', 'person_id,display_name'),
    supabaseOptionalSelect('operational_vehicles', 'vehicle_id,registration,make,model,colour'),
    supabaseOptionalSelect('operational_incident_attachments', 'attachment_id,incident_id,title,file_name,storage_path,sha256,integrity_status'),
    supabaseOptionalSelect('documents', 'document_id,title,storage_path,drive_url'),
    supabaseOptionalSelect('operational_operations', 'operation_id,reference,name,summary,objectives,archived_at'),
  ]);
  const rows = [];
  const issue = (Severity, Area, Check, Title, Detail, extra = {}) => rows.push({ Severity, Area, Check, Title, Detail, ...extra });
  const now = Date.now();
  const activeOfficers = officers.filter((row) => row.status !== 'Archived');
  activeOfficers.filter((row) => !row.supervisor_user_id).forEach((row) => issue('High', 'Personnel', 'Supervisor assignment', row.roblox_username, 'Active officer has no supervisor assigned.', { OfficerID: row.officer_id, Reference: row.callsign }));
  const duplicateValues = (values) => values.filter(Boolean).filter((value, index, all) => all.indexOf(value) !== index);
  const duplicateCallsigns = new Set(duplicateValues(activeOfficers.map((row) => String(row.callsign || '').trim().toLowerCase())));
  activeOfficers.filter((row) => duplicateCallsigns.has(String(row.callsign || '').trim().toLowerCase())).forEach((row) => issue('High', 'Personnel', 'Duplicate callsign', row.roblox_username, `Callsign ${row.callsign} is assigned to more than one active officer.`, { OfficerID: row.officer_id, Reference: row.callsign }));
  profiles.filter((row) => row.status !== 'Archived' && !officers.some((officerRow) => officerRow.member_id === row.member_id)).forEach((row) => issue('Warning', 'Accounts', 'Unlinked account', row.roblox_username, 'Active user account has no linked officer record.', { View: 'users', Reference: row.user_id }));
  tasks.filter((row) => row.due_at && new Date(row.due_at).getTime() < now && !['Completed', 'Cancelled'].includes(row.status)).forEach((row) => issue(row.priority === 'Critical' ? 'Critical' : 'High', 'Tasks', 'Overdue task', row.title, `${row.status} / due ${formatDisplayDateTime(row.due_at)}`, { View: 'tasks', OfficerID: row.assigned_officer_id, Reference: row.task_id }));
  loa.filter((row) => !row.start_date || !row.end_date || new Date(row.end_date) < new Date(row.start_date)).forEach((row) => issue('Critical', 'Personnel', 'Invalid leave dates', officers.find((item) => item.officer_id === row.officer_id)?.roblox_username || row.request_id, 'Leave record has missing or invalid dates.', { View: 'loa', OfficerID: row.officer_id, Reference: row.request_id }));
  aips.filter((row) => !row.archived_at && row.review_end_date && new Date(`${row.review_end_date}T23:59:59`).getTime() < now && !['Closed', 'Withdrawn'].includes(row.status)).forEach((row) => issue('Critical', 'Personnel', 'Overdue AIP review', row.reference, `${officers.find((item) => item.officer_id === row.officer_id)?.roblox_username || 'Officer'} / review due ${formatDisplayDate(row.review_end_date)}`, { View: 'development', OfficerID: row.officer_id, Reference: row.aip_id }));
  incidents.filter((row) => ['Resolved', 'Cancelled'].includes(row.status) && !row.outcome && !row.closure_code).forEach((row) => issue('High', 'Operations', 'Missing CAD outcome', `${row.incident_number} / ${row.title}`, 'Closed CAD has no outcome or closure code recorded.', { OperationsTarget: `Incident:${row.incident_id}`, Reference: row.incident_number }));
  incidents.filter((row) => !['Resolved', 'Cancelled'].includes(row.status) && now - new Date(row.updated_at || row.created_at).getTime() > 24 * 60 * 60 * 1000).forEach((row) => issue('Warning', 'Operations', 'Stale open CAD', `${row.incident_number} / ${row.title}`, 'Open CAD has not been updated for more than 24 hours.', { OperationsTarget: `Incident:${row.incident_id}`, Reference: row.incident_number }));
  incidents.filter((row) => !entities.some((item) => item.incident_id === row.incident_id)).forEach((row) => issue('Warning', 'Operations', 'No linked intelligence', `${row.incident_number} / ${row.title}`, 'CAD has no person or vehicle linked.', { OperationsTarget: `Incident:${row.incident_id}`, Reference: row.incident_number }));
  vehicles.filter((row) => !row.make || !row.model || !row.colour).forEach((row) => issue('Warning', 'Intelligence', 'Incomplete vehicle', row.registration, 'Vehicle is missing make, model or colour.', { OperationsTarget: `Vehicle:${row.vehicle_id}`, Reference: row.vehicle_id }));
  people.filter((row) => !entities.some((item) => item.person_id === row.person_id)).forEach((row) => issue('Warning', 'Intelligence', 'Unlinked person', row.display_name, 'Person record is not linked to any CAD.', { OperationsTarget: `Person:${row.person_id}`, Reference: row.person_id }));
  evidence.filter((row) => !row.title || !row.file_name || !row.storage_path).forEach((row) => issue('Critical', 'Evidence', 'Incomplete evidence metadata', row.title || row.file_name || row.attachment_id, 'Evidence is missing a title, filename or storage reference.', { OperationsTarget: `Incident:${row.incident_id}`, Reference: row.attachment_id }));
  evidence.filter((row) => row.integrity_status === 'Mismatch').forEach((row) => issue('Critical', 'Evidence', 'Integrity mismatch', row.title || row.file_name, 'The latest SHA-256 verification did not match the stored evidence hash.', { OperationsTarget: `Incident:${row.incident_id}`, Reference: row.attachment_id }));
  evidence.filter((row) => !row.sha256 || row.integrity_status === 'Unverified').forEach((row) => issue('High', 'Evidence', 'Evidence not verified', row.title || row.file_name, 'Open and verify this evidence to establish or confirm its integrity baseline.', { OperationsTarget: `Incident:${row.incident_id}`, Reference: row.attachment_id }));
  documents.filter((row) => !row.storage_path && !row.drive_url).forEach((row) => issue('High', 'Documents', 'Unavailable document', row.title || row.document_id, 'Document has no uploaded file or external link.', { View: 'documents', Reference: row.document_id }));
  cases.filter((row) => !row.archived_at && !row.summary && !row.objectives).forEach((row) => issue('Warning', 'Casework', 'Incomplete case', `${row.reference} / ${row.name}`, 'Active case has no summary or objectives.', { OperationsTarget: `Case:${row.operation_id}`, Reference: row.reference }));
  const checked = activeOfficers.length + profiles.length + tasks.length + loa.length + aips.length + incidents.length + people.length + vehicles.length + evidence.length + documents.length + cases.length;
  const critical = rows.filter((row) => row.Severity === 'Critical').length;
  const weighted = rows.reduce((sum, row) => sum + ({ Critical: 4, High: 3, Warning: 1, Information: 0 }[row.Severity] || 0), 0);
  const score = checked ? Math.max(0, Math.round(100 - (weighted / checked) * 15)) : 100;
  const order = { Critical: 0, High: 1, Warning: 2, Information: 3 };
  return { ok: true, rows: rows.sort((a, b) => order[a.Severity] - order[b.Severity] || a.Area.localeCompare(b.Area)).slice(0, 500), score, critical, actionable: rows.length, checked };
}

async function supabaseSavedViews() {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me;
  const rows = await supabaseOptionalRows('saved_views', 'user_id', me.user.UserID, 'created_at');
  return { ok: true, rows: rows.map((row) => ({ ViewID: row.view_id, Name: row.name, Module: row.module, Query: row.query || '', Filters: row.filters })) };
}

async function supabaseSaveSavedView(data) {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me;
  const { error } = await supabaseClient.from('saved_views').upsert({ user_id: me.user.UserID, name: data.Name, module: 'Search', query: data.Query || '', filters: {} }, { onConflict: 'user_id,name' });
  return error ? { ok: false, error: error.message } : { ok: true };
}

async function supabaseOperationalCalendar() {
  const [events, rsvps, courses, bookings, loa, reviews, checkins, officers, profile, profiles, deployments] = await Promise.all([supabaseOptionalAll('calendar_events'), supabaseOptionalAll('calendar_rsvps'), supabaseAll('training_courses'), supabaseAll('course_bookings'), supabaseAll('loa_requests'), supabaseOptionalAll('performance_reviews'), supabaseAll('supervisor_checkins'), supabaseAll('officers'), supabaseProfileByUserId(state.user.UserID), supabaseAll('profiles'), supabaseOptionalAll('operational_deployments')]);
  const officerName = (id) => officers.find((row) => row.officer_id === id)?.roblox_username || 'Officer';
  const myOfficer = officers.find((row) => row.member_id === profile?.member_id);
  const visibleCourses = courses.filter((course) => {
    if (course.trainer_user_id === state.user.UserID || (course.co_trainer_user_ids || []).includes(state.user.UserID)) return true;
    return bookings.some((booking) => booking.course_id === course.course_id && booking.officer_id === myOfficer?.officer_id && ['Approved', 'Waitlist', 'Completed'].includes(booking.status));
  });
  return { ok: true, rows: [
    ...events.map((row) => {
      const eventRsvps = (rsvps || []).filter((item) => item.event_id === row.event_id);
      const myRsvp = eventRsvps.find((item) => item.officer_id === myOfficer?.officer_id);
      return { ID: row.event_id, Type: row.event_type, Title: row.title, Start: row.starts_at, End: row.ends_at, Detail: row.details, Location: row.location, Priority: row.priority || 'Normal', AudienceType: row.audience_type || 'Everyone', AudienceValues: row.audience_values || [], AssignedOfficerIDs: row.assigned_officer_ids || [], Audience: calendarAudienceSummary(row, officers), CreatedBy: profiles.find((item) => item.user_id === row.created_by)?.roblox_username || '', Editable: row.created_by === state.user.UserID || can('FULL_ACCESS'), RequiresRsvp: row.requires_rsvp ? 'TRUE' : 'FALSE', ReminderMinutes: (row.reminder_minutes || []).join(','), MyRsvp: myRsvp?.response || 'Pending', RsvpSummary: calendarRsvpSummary(row, eventRsvps, officers, profiles), Rsvps: eventRsvps.map((item) => calendarRsvpRow(item, officers)) };
    }),
    ...visibleCourses.filter((row) => row.status !== 'Cancelled').map((row) => ({ ID: `course-${row.course_id}`, Type: 'Training', Title: row.title, Start: row.course_date, End: addMinutesIso(row.course_date, row.duration_minutes || 60), Detail: `${row.standard} / ${row.duration_minutes || 60} minutes`, Location: row.location })),
    ...loa.filter((row) => row.status === 'Approved').map((row) => ({ ID: row.request_id, Type: 'LOA', Title: `${officerName(row.officer_id)} on LOA`, Start: row.start_date, End: row.end_date, Detail: row.reason })),
    ...reviews.filter((row) => row.next_review_date).map((row) => ({ ID: row.review_id, Type: 'Review', Title: `${officerName(row.officer_id)} review`, Start: row.next_review_date, Detail: row.rating })),
    ...checkins.filter((row) => row.follow_up_date).map((row) => ({ ID: row.checkin_id, Type: 'Follow-up', Title: `${officerName(row.officer_id)} check-in`, Start: row.follow_up_date, Detail: row.development_goals })),
    ...deployments.filter((row) => !['Cancelled'].includes(row.status) && ((row.assigned_officer_ids || []).includes(myOfficer?.officer_id) || can('VIEW_TASKS'))).map((row) => ({ ID: `deployment-${row.deployment_id}`, Type: 'Deployment', Title: row.title, Start: row.starts_at, End: row.ends_at, Detail: `${row.deployment_type} / ${row.briefing || 'No briefing'}`, Location: row.location, Priority: 'Normal' })),
  ].filter((row) => row.Start) };
}

function calendarRsvpSummary(event, rsvps, officers, profiles) {
  const recipients = calendarEventRecipients(event, officers, profiles);
  const counts = { Attending: 0, Maybe: 0, 'Not Attending': 0, Pending: 0 };
  const byOfficer = new Map((rsvps || []).map((row) => [row.officer_id, row.response || 'Pending']));
  recipients.forEach((profile) => {
    const officer = officers.find((row) => row.member_id === profile.member_id);
    counts[byOfficer.get(officer?.officer_id) || 'Pending'] += 1;
  });
  return `Attending ${counts.Attending} / Maybe ${counts.Maybe} / Not attending ${counts['Not Attending']} / Pending ${counts.Pending}`;
}

function calendarRsvpRow(row, officers) {
  const officer = officers.find((item) => item.officer_id === row.officer_id) || {};
  return { OfficerID: row.officer_id, Officer: officer.roblox_username || row.officer_id, Rank: officer.rank || '', Response: row.response || 'Pending', Note: row.note || '', RespondedAt: row.responded_at || '' };
}

async function supabaseSaveCalendarEvent(data) {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me;
  const audienceType = data.AudienceType || 'Everyone';
  const audienceValues = audienceType === 'Role' ? splitTags(data.AudienceRoles || '') : audienceType === 'Ranks' ? splitTags(data.AudienceRanks || '') : audienceType === 'Minimum Rank' ? [data.AudienceRank || 'Police Constable'] : audienceType === 'Tag' ? splitTags(data.AudienceTags || '') : [];
  const assignedOfficerIds = ['Specific Officers', 'My Supervisees'].includes(audienceType) ? splitTags(data.AssignedOfficerIDs || '') : [];
  if (audienceType === 'Specific Officers' && !can('FULL_ACCESS')) return { ok: false, error: 'Only Inspector+ can assign specific officers.' };
  if (['Role', 'Ranks', 'Tag'].includes(audienceType) && !audienceValues.length) return { ok: false, error: `Select at least one ${audienceType.toLowerCase()}.` };
  if (['Specific Officers', 'My Supervisees'].includes(audienceType) && !assignedOfficerIds.length) return { ok: false, error: 'Select at least one officer.' };
  const existing = data.EventID ? await supabaseById('calendar_events', 'event_id', data.EventID) : null;
  const record = { title: data.Title, event_type: data.EventType, priority: data.Priority || 'Normal', starts_at: data.StartsAt, ends_at: data.EndsAt || null, location: data.Location || '', details: data.Details || '', audience_type: audienceType, audience_values: audienceValues, assigned_officer_ids: assignedOfficerIds, requires_rsvp: data.RequiresRsvp !== 'No', reminder_minutes: splitTags(data.ReminderMinutes || '').map(Number).filter((value) => Number.isFinite(value) && value > 0), created_by: existing?.created_by || me.user.UserID, updated_at: new Date().toISOString() };
  const [officers, profiles] = await Promise.all([supabaseAll('officers'), supabaseAll('profiles')]);
  const previousRecipients = existing ? calendarEventRecipients(existing, officers, profiles) : [];
  const query = data.EventID
    ? supabaseClient.from('calendar_events').update(record).eq('event_id', data.EventID).select('*').limit(1).maybeSingle()
    : supabaseClient.from('calendar_events').insert(record).select('*').limit(1).maybeSingle();
  const { data: savedEvent, error } = await query;
  if (error) return { ok: false, error: error.message };
  const savedRecord = savedEvent || { ...record, event_id: data.EventID };
  await syncCalendarRsvps(savedRecord, calendarEventRecipients(savedRecord, officers, profiles), officers);
  await notifyCalendarEventChange(existing, savedRecord, previousRecipients, calendarEventRecipients(savedRecord, officers, profiles), me.user);
  return { ok: true };
}

async function syncCalendarRsvps(event, recipients, officers) {
  if (!event?.event_id || !event.requires_rsvp) return;
  const recipientMemberIds = new Set((recipients || []).map((profile) => profile.member_id));
  const rows = officers
    .filter((officer) => recipientMemberIds.has(officer.member_id))
    .map((officer) => ({ event_id: event.event_id, officer_id: officer.officer_id, response: 'Pending' }));
  if (!rows.length) return;
  await supabaseClient.from('calendar_rsvps').upsert(rows, { onConflict: 'event_id,officer_id', ignoreDuplicates: true });
}

async function supabaseDeleteCalendarEvent(data) {
  const event = await supabaseById('calendar_events', 'event_id', data.EventID);
  if (!event) return { ok: false, error: 'Calendar assignment not found.' };
  const [officers, profiles] = await Promise.all([supabaseAll('officers'), supabaseAll('profiles')]);
  const recipients = calendarEventRecipients(event, officers, profiles);
  const { error } = await supabaseClient.from('calendar_events').delete().eq('event_id', data.EventID);
  if (error) return { ok: false, error: error.message };
  await Promise.all(recipients.filter((profile) => profile.user_id !== state.user.UserID).map((recipient) => supabaseNotify(recipient.member_id, 'Calendar assignment cancelled', `${event.title} on ${formatDisplayDateTime(event.starts_at)} has been removed from the calendar.`, state.user.UserID)));
  return { ok: true };
}

async function supabaseSetCalendarRsvp(data) {
  const profile = await supabaseProfileByUserId(state.user.UserID);
  const officer = await supabaseOfficerForMember(profile.member_id);
  if (!officer) return { ok: false, error: 'No linked officer profile.' };
  if (!['Attending', 'Maybe', 'Not Attending'].includes(data.Response)) return { ok: false, error: 'Choose a valid RSVP response.' };
  const event = await supabaseById('calendar_events', 'event_id', data.EventID);
  if (!event) return { ok: false, error: 'Calendar event not found.' };
  const { error } = await supabaseClient.from('calendar_rsvps').upsert({
    event_id: data.EventID,
    officer_id: officer.officer_id,
    response: data.Response,
    note: data.Note || '',
    responded_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  }, { onConflict: 'event_id,officer_id' });
  if (error) return { ok: false, error: error.message };
  await supabaseNotify(profile.member_id, 'Calendar RSVP updated', notificationDetails([
    detailLine('Event', event.title),
    detailLine('Response', data.Response),
    detailLine('Starts', formatDisplayDateTime(event.starts_at)),
  ]), state.user?.UserID);
  return { ok: true };
}

async function supabaseProcessCalendarReminders() {
  if (!can('VIEW_TASKS')) return { ok: true, skipped: true };
  try {
    const now = Date.now();
    const [events, logs, officers, profiles] = await Promise.all([
      supabaseOptionalAll('calendar_events'),
      supabaseOptionalAll('calendar_reminder_log'),
      supabaseAll('officers'),
      supabaseAll('profiles'),
    ]);
    const logKeys = new Set((logs || []).map((row) => `${row.event_id}:${row.officer_id}:${row.minutes_before}`));
    let sent = 0;
    for (const event of events || []) {
      const start = new Date(event.starts_at).getTime();
      if (!start || start <= now) continue;
      const reminderMinutes = (event.reminder_minutes || [1440, 60]).filter((value) => Number(value) > 0);
      for (const minutesBefore of reminderMinutes) {
        const msUntil = start - now;
        const reminderWindowMs = Number(minutesBefore) * 60000;
        if (msUntil > reminderWindowMs || msUntil < reminderWindowMs - 15 * 60000) continue;
        const recipients = calendarEventRecipients(event, officers, profiles);
        for (const recipient of recipients) {
          const officer = officers.find((row) => row.member_id === recipient.member_id);
          if (!officer) continue;
          const key = `${event.event_id}:${officer.officer_id}:${minutesBefore}`;
          if (logKeys.has(key)) continue;
          await supabaseNotify(recipient.member_id, 'Calendar event reminder', notificationDetails([
            detailLine('Event', event.title),
            detailLine('Starts', formatDisplayDateTime(event.starts_at)),
            detailLine('Location', event.location),
            detailLine('Reminder', reminderLabel(minutesBefore)),
          ]), state.user?.UserID);
          const { error } = await supabaseClient.from('calendar_reminder_log').insert({ event_id: event.event_id, officer_id: officer.officer_id, minutes_before: minutesBefore });
          if (error) throw new Error(error.message);
          logKeys.add(key);
          sent += 1;
        }
      }
    }
    return { ok: true, sent };
  } catch (error) {
    if (/does not exist|schema cache/i.test(error.message || '')) return { ok: true, skipped: true };
    return { ok: false, error: error.message };
  }
}

function reminderLabel(minutes) {
  const value = Number(minutes);
  if (value >= 1440) return `${Math.round(value / 1440)} day(s) before`;
  if (value >= 60) return `${Math.round(value / 60)} hour(s) before`;
  return `${value} minute(s) before`;
}

async function notifyCalendarEventChange(existing, record, previousRecipients, currentRecipients, actor) {
  const actorUserId = actor?.UserID;
  const actorName = actor?.RobloxUsername || 'MO8 MDT';
  const previousByMember = new Map(previousRecipients.map((profile) => [profile.member_id, profile]));
  const currentByMember = new Map(currentRecipients.map((profile) => [profile.member_id, profile]));
  const allMemberIds = new Set([...previousByMember.keys(), ...currentByMember.keys()]);
  const changedTiming = Boolean(existing && (existing.starts_at !== record.starts_at || (existing.ends_at || '') !== (record.ends_at || '')));
  const changedDetails = Boolean(existing && [
    existing.title !== record.title,
    existing.event_type !== record.event_type,
    (existing.location || '') !== (record.location || ''),
    (existing.details || '') !== (record.details || ''),
    (existing.priority || 'Normal') !== (record.priority || 'Normal'),
  ].some(Boolean));

  await Promise.all([...allMemberIds].map((memberId) => {
    const wasAssigned = previousByMember.has(memberId);
    const isAssigned = currentByMember.has(memberId);
    const recipient = currentByMember.get(memberId) || previousByMember.get(memberId);
    if (!recipient || recipient.user_id === actorUserId) return Promise.resolve();
    if (wasAssigned && !isAssigned) {
      return supabaseNotify(memberId, 'Calendar assignment removed', notificationDetails([
        detailLine('Event', existing.title),
        detailLine('Previous start', formatDisplayDateTime(existing.starts_at)),
        detailLine('Previous end', formatDisplayDateTime(existing.ends_at)),
        detailLine('Updated by', actorName),
      ]), actorUserId);
    }
    const title = !wasAssigned ? 'New calendar assignment' : changedTiming ? 'Calendar assignment rescheduled' : changedDetails ? 'Calendar assignment details updated' : 'Calendar assignment updated';
    return supabaseNotify(memberId, title, notificationDetails([
      detailLine('Event', record.title),
      detailLine('Type', record.event_type),
      detailLine('Starts', formatDisplayDateTime(record.starts_at)),
      detailLine('Ends', formatDisplayDateTime(record.ends_at)),
      detailLine('Location', record.location),
      detailLine('Priority', record.priority),
      detailLine('Assigned by', actorName),
      existing && changedTiming ? detailLine('Previous start', formatDisplayDateTime(existing.starts_at)) : '',
      existing && changedTiming ? detailLine('Previous end', formatDisplayDateTime(existing.ends_at)) : '',
    ]), actorUserId);
  }));
}

function calendarEventRecipients(event, officers, profiles) {
  const values = event.audience_values || [];
  const audienceType = event.audience_type || 'Everyone';
  let selected = [];
  if (audienceType === 'Everyone') selected = officers;
  if (audienceType === 'Role') selected = officers.filter((officer) => values.includes(profiles.find((profile) => profile.member_id === officer.member_id)?.role));
  if (audienceType === 'Ranks') selected = officers.filter((officer) => values.includes(officer.rank));
  if (audienceType === 'Minimum Rank') selected = officers.filter((officer) => OFFICER_RANKS.indexOf(officer.rank) >= OFFICER_RANKS.indexOf(values[0] || 'Police Constable'));
  if (audienceType === 'Tag') selected = officers.filter((officer) => (officer.tags || []).some((tag) => values.includes(tag)));
  if (audienceType === 'My Supervisees') selected = officers.filter((officer) => officer.supervisor_user_id === event.created_by && (!(event.assigned_officer_ids || []).length || event.assigned_officer_ids.includes(officer.officer_id)));
  if (audienceType === 'Specific Officers') selected = officers.filter((officer) => (event.assigned_officer_ids || []).includes(officer.officer_id));
  const memberIds = new Set(selected.map((officer) => officer.member_id));
  return profiles.filter((profile) => memberIds.has(profile.member_id));
}

function calendarAudienceSummary(event, officers) {
  const type = event.audience_type || 'Everyone';
  if (type === 'Role') return `Roles: ${(event.audience_values || []).join(', ')}`;
  if (type === 'Ranks') return `Ranks: ${(event.audience_values || []).join(', ')}`;
  if (type === 'Minimum Rank') return `${event.audience_values?.[0] || 'Police Constable'}+`;
  if (type === 'Tag') return `Tags: ${(event.audience_values || []).join(', ')}`;
  if (type === 'My Supervisees') return `Supervisees: ${(event.assigned_officer_ids || []).map((id) => officers.find((officer) => officer.officer_id === id)?.roblox_username).filter(Boolean).join(', ') || 'All'}`;
  if (type === 'Specific Officers') return `Officers: ${(event.assigned_officer_ids || []).map((id) => officers.find((officer) => officer.officer_id === id)?.roblox_username).filter(Boolean).join(', ')}`;
  return 'All officers';
}

async function supabaseDevelopmentRecords() {
  const [officers, profiles, probation, reviews, restrictions, aips, signatures] = await Promise.all([supabaseAll('officers'), supabaseAll('profiles'), supabaseOptionalAll('probation_records'), supabaseOptionalAll('performance_reviews'), supabaseOptionalAll('officer_restrictions'), supabaseOptionalAll('activity_improvement_notices'), supabaseOptionalAll('aip_signatures')]);
  const officer = (id) => officers.find((row) => row.officer_id === id) || {};
  const profile = (id) => profiles.find((row) => row.user_id === id) || {};
  return { ok: true, officers: officers.map(supabaseOfficer),
    probation: probation.map((row) => ({ ProbationID: row.probation_id, OfficerID: row.officer_id, Officer: officer(row.officer_id).roblox_username, Rank: officer(row.officer_id).rank, Stage: row.stage, Status: row.status, StartDate: row.start_date, TargetDate: row.target_date, Progress: row.progress, Requirements: row.requirements, Notes: row.notes, Reviewer: profile(row.reviewer_user_id).roblox_username || '', ReviewerUserID: row.reviewer_user_id })),
    reviews: reviews.map((row) => ({ ReviewID: row.review_id, OfficerID: row.officer_id, Officer: officer(row.officer_id).roblox_username, ReviewDate: row.review_date, PeriodStart: row.period_start, PeriodEnd: row.period_end, Rating: row.rating, ActivitySummary: row.activity_summary, Strengths: row.strengths, Improvements: row.improvements, Objectives: row.objectives, NextReviewDate: row.next_review_date, Reviewer: profile(row.reviewer_user_id).roblox_username || '' })),
    restrictions: restrictions.map((row) => ({ RestrictionID: row.restriction_id, OfficerID: row.officer_id, Officer: officer(row.officer_id).roblox_username, RestrictionType: row.restriction_type, Details: row.details, StartsOn: row.starts_on, EndsOn: row.ends_on, Status: row.status })),
    aips: aips.map((row) => mapAip(row, officers, profiles, signatures)),
  };
}

function mapAip(row, officers, profiles, signatures = []) {
  const officer = officers.find((item) => item.officer_id === row.officer_id) || {};
  const lineManager = profiles.find((item) => item.user_id === row.line_manager_user_id) || {};
  const authoriser = profiles.find((item) => item.user_id === row.authorising_manager_user_id) || {};
  const signed = signatures.filter((item) => item.aip_id === row.aip_id && Number(item.version) === Number(row.version));
  return {
    AipID: row.aip_id, Reference: row.reference, OfficerID: row.officer_id,
    Officer: officer.roblox_username || row.officer_id, Rank: officer.rank || '', OfficerMemberID: officer.member_id || '',
    CreatedBy: row.created_by, LineManagerUserID: row.line_manager_user_id,
    LineManager: `${lineManager.rank || ''} ${lineManager.roblox_username || ''}`.trim(),
    AuthorisingManagerUserID: row.authorising_manager_user_id,
    AuthorisingManager: `${authoriser.rank || ''} ${authoriser.roblox_username || ''}`.trim(),
    Status: row.status, IssueDate: row.issue_date, ReviewEndDate: row.review_end_date, Reason: row.reason,
    RequiredHours: row.required_hours, AdjustedRequiredHours: row.adjusted_required_hours,
    ExpectedStandards: row.expected_standards, SupportGuidance: row.support_guidance, Consequences: row.consequences,
    ActivitySnapshot: row.activity_snapshot || {}, LoaSnapshot: row.loa_snapshot || [],
    OfficerResponse: row.officer_response || '', OfficerAcknowledgedAt: row.officer_acknowledged_at,
    ReviewOutcome: row.review_outcome || '', ReviewComments: row.review_comments || '', ReviewedAt: row.reviewed_at,
    ArchivedAt: row.archived_at || '', ArchiveReason: row.archive_reason || '',
    Version: row.version,
    Signatures: signed.map((item) => ({ Role: item.signature_role, UserID: item.signer_user_id, Name: item.signer_name, Rank: item.signer_rank, SignatureData: item.signature_data, SignedAt: item.signed_at, SignedVia: item.signed_via })),
    SignatureCount: signed.length, SignaturesLabel: `${signed.length}/2`,
  };
}

async function supabaseSaveAip(data) {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me;
  if (!can('VIEW_TASKS')) return { ok: false, error: 'Supervisor access is required to issue an AIP.' };
  const officer = await supabaseById('officers', 'officer_id', data.OfficerID);
  if (!officer) return { ok: false, error: 'Select a valid officer.' };
  const [shifts, loa] = await Promise.all([supabaseRows('shift_logs', 'officer_id', officer.officer_id, 'started_at'), supabaseRows('loa_requests', 'officer_id', officer.officer_id)]);
  const issue = new Date(`${data.IssueDate}T23:59:59`); const since = new Date(issue); since.setDate(since.getDate() - 30);
  const recentShifts = shifts.filter((row) => new Date(row.started_at) >= since && new Date(row.started_at) <= issue);
  const activityMs = recentShifts.reduce((sum, row) => sum + Math.max(0, new Date(row.ended_at || issue) - new Date(row.started_at)), 0);
  const loaSnapshot = loa.filter((row) => row.status === 'Approved' && new Date(row.end_date) >= since && new Date(row.start_date) <= new Date(`${data.ReviewEndDate}T23:59:59`));
  const record = { officer_id: officer.officer_id, line_manager_user_id: data.LineManagerUserID, authorising_manager_user_id: data.AuthorisingManagerUserID, issue_date: data.IssueDate, review_end_date: data.ReviewEndDate, reason: data.Reason, required_hours: Number(data.RequiredHours || 6), adjusted_required_hours: data.AdjustedRequiredHours === '' ? null : Number(data.AdjustedRequiredHours), expected_standards: data.ExpectedStandards || '', support_guidance: data.SupportGuidance || '', consequences: data.Consequences || '', activity_snapshot: { periodStart: since.toISOString(), periodEnd: issue.toISOString(), shifts: recentShifts.length, hours: Number((activityMs / 3600000).toFixed(2)) }, loa_snapshot: loaSnapshot, updated_at: new Date().toISOString() };
  let saved;
  if (data.AipID) {
    const existing = await supabaseById('activity_improvement_notices', 'aip_id', data.AipID);
    if (existing?.status !== 'Draft' && existing?.status !== 'Awaiting Signatures') return { ok: false, error: 'Issued AIPs cannot be edited. Withdraw or complete the existing notice.' };
    const existingSignatures = await supabaseOptionalRows('aip_signatures', 'aip_id', data.AipID);
    if (existingSignatures.some((item) => Number(item.version) === Number(existing.version))) {
      record.version = Number(existing.version) + 1;
      record.status = 'Awaiting Signatures';
      await supabaseClient.from('aip_signing_links').update({ revoked_at: new Date().toISOString() }).eq('aip_id', data.AipID).is('used_at', null);
    }
    const { data: updated, error } = await supabaseClient.from('activity_improvement_notices').update(record).eq('aip_id', data.AipID).select().maybeSingle(); if (error) return { ok: false, error: error.message }; saved = updated;
  } else {
    const { data: inserted, error } = await supabaseClient.from('activity_improvement_notices').insert({ ...record, created_by: me.user.UserID, status: 'Awaiting Signatures' }).select().maybeSingle(); if (error) return { ok: false, error: error.message }; saved = inserted;
  }
  const managers = await Promise.all([supabaseById('profiles', 'user_id', data.LineManagerUserID), supabaseById('profiles', 'user_id', data.AuthorisingManagerUserID)]);
  for (const manager of managers.filter(Boolean)) await supabaseNotify(manager.member_id, 'AIP awaiting your signature', `${saved.reference}: ${officer.rank} ${officer.roblox_username}. Review date: ${formatDisplayDate(data.ReviewEndDate)}.`, me.user.UserID);
  await supabaseNotify(officer.member_id, 'Activity Improvement Notice being prepared', `${saved.reference} has been created and is awaiting management signatures. Review date: ${formatDisplayDate(data.ReviewEndDate)}.`, me.user.UserID);
  await supabaseAudit(me.user.UserID, data.AipID ? 'UPDATE_AIP' : 'CREATE_AIP', 'Activity Improvement Notice', saved.aip_id, { reference: saved.reference, officer: officer.roblox_username });
  return { ok: true, AipID: saved.aip_id, warning: loaSnapshot.length ? 'The officer has approved LOA during or shortly before this review period. Confirm the adjusted activity requirement.' : '' };
}

async function supabaseGetAip(data) {
  const [row, officers, profiles, signatures] = await Promise.all([supabaseById('activity_improvement_notices', 'aip_id', data.AipID), supabaseAll('officers'), supabaseAll('profiles'), supabaseOptionalRows('aip_signatures', 'aip_id', data.AipID)]);
  if (!row) return { ok: false, error: 'AIP not found or you do not have access.' };
  const aip = mapAip(row, officers, profiles, signatures);
  const signedRoles = new Set(aip.Signatures.map((item) => item.Role));
  const pendingSignatureRole = row.line_manager_user_id === state.user?.UserID && !signedRoles.has('Line Manager') ? 'Line Manager' : row.authorising_manager_user_id === state.user?.UserID && !signedRoles.has('Manager Authorisation') ? 'Manager Authorisation' : '';
  const currentOfficer = officers.find((item) => item.member_id === state.user?.MemberID);
  const pendingSigningRoles = ['Line Manager', 'Manager Authorisation'].filter((role) => !signedRoles.has(role));
  return { ok: true, aip, pendingSignatureRole, pendingSigningRoles, canCreateLinks: can('VIEW_TASKS') && row.status === 'Awaiting Signatures', canAcknowledge: currentOfficer?.officer_id === row.officer_id && !row.officer_acknowledged_at && ['Issued', 'Under Review', 'Extended', 'Closed'].includes(row.status), canReview: (row.line_manager_user_id === state.user?.UserID || can('VIEW_TASKS')) && ['Issued', 'Under Review', 'Extended'].includes(row.status), canWithdraw: can('VIEW_TASKS') && !['Closed', 'Withdrawn'].includes(row.status) };
}

async function supabaseSignAip(data) {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me;
  const row = await supabaseById('activity_improvement_notices', 'aip_id', data.AipID); if (!row) return { ok: false, error: 'AIP not found.' };
  const expected = data.SignatureRole === 'Line Manager' ? row.line_manager_user_id : row.authorising_manager_user_id;
  if (expected !== me.user.UserID) return { ok: false, error: 'This signature is assigned to another officer.' };
  const { error } = await supabaseClient.from('aip_signatures').insert({ aip_id: row.aip_id, signature_role: data.SignatureRole, signer_user_id: me.user.UserID, signer_name: me.user.RobloxUsername, signer_rank: me.user.Rank, signature_data: data.SignatureData, signed_via: 'MDT', version: row.version });
  if (error) return { ok: false, error: error.message };
  await supabaseClient.rpc('refresh_aip_status', { target_aip_id: row.aip_id });
  const officer = await supabaseById('officers', 'officer_id', row.officer_id); const signatures = await supabaseOptionalRows('aip_signatures', 'aip_id', row.aip_id);
  if (signatures.filter((item) => Number(item.version) === Number(row.version)).length >= 2) await supabaseNotify(officer?.member_id, 'Activity Improvement Notice issued', `${row.reference} is now issued. Your activity will be reviewed on ${formatDisplayDate(row.review_end_date)}.`, me.user.UserID);
  return { ok: true };
}

async function supabaseAcknowledgeAip(data) {
  const { data: result, error } = await supabaseClient.rpc('acknowledge_aip', { target_aip_id: data.AipID, officer_response_text: data.Response || '' });
  return error ? { ok: false, error: error.message } : result;
}

async function supabaseCreateAipSigningLink(data) {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me;
  const row = await supabaseById('activity_improvement_notices', 'aip_id', data.AipID); if (!row) return { ok: false, error: 'AIP not found.' };
  const signatures = await supabaseOptionalRows('aip_signatures', 'aip_id', row.aip_id); const signed = new Set(signatures.filter((item) => Number(item.version) === Number(row.version)).map((item) => item.signature_role));
  const role = data.SignatureRole;
  if (!['Line Manager', 'Manager Authorisation'].includes(role)) return { ok: false, error: 'Choose the signature role for this link.' };
  if (signed.has(role)) return { ok: false, error: `${role} has already signed this AIP.` };
  if (!role) return { ok: false, error: 'Both required signatures have already been completed.' };
  const signerUserId = role === 'Line Manager' ? row.line_manager_user_id : row.authorising_manager_user_id;
  await supabaseClient.from('aip_signing_links').update({ revoked_at: new Date().toISOString() }).eq('aip_id', row.aip_id).eq('signature_role', role).is('used_at', null);
  const { data: link, error } = await supabaseClient.from('aip_signing_links').insert({ aip_id: row.aip_id, signature_role: role, signer_user_id: signerUserId, created_by: me.user.UserID }).select().maybeSingle();
  if (error) return { ok: false, error: error.message };
  return { ok: true, url: `${location.origin}${location.pathname}?aip-sign=${encodeURIComponent(link.token)}` };
}

async function supabaseReviewAip(data) {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me; const row = await supabaseById('activity_improvement_notices', 'aip_id', data.AipID);
  if (!row || (row.line_manager_user_id !== me.user.UserID && !can('VIEW_TASKS'))) return { ok: false, error: 'You are not authorised to review this AIP.' };
  if (data.Outcome === 'Extended' && !data.NewReviewEndDate) return { ok: false, error: 'Choose a new review date when extending an AIP.' };
  const status = data.Outcome === 'Extended' ? 'Extended' : data.Outcome === 'Withdrawn' ? 'Withdrawn' : 'Closed';
  const reviewComments = truthy(data.EarlyReview) ? `[EARLY REVIEW - scheduled for ${formatDisplayDate(row.review_end_date)}]\n${data.Comments}` : data.Comments;
  const update = { review_outcome: data.Outcome, review_comments: reviewComments, reviewed_at: new Date().toISOString(), reviewed_by: me.user.UserID, status, updated_at: new Date().toISOString() }; if (data.Outcome === 'Extended') update.review_end_date = data.NewReviewEndDate;
  const { error } = await supabaseClient.from('activity_improvement_notices').update(update).eq('aip_id', row.aip_id); if (error) return { ok: false, error: error.message };
  const officer = await supabaseById('officers', 'officer_id', row.officer_id); await supabaseNotify(officer?.member_id, `AIP review: ${data.Outcome}`, `${row.reference}: ${reviewComments}`, me.user.UserID); await supabaseAudit(me.user.UserID, 'REVIEW_AIP', 'Activity Improvement Notice', row.aip_id, { outcome: data.Outcome, earlyReview: truthy(data.EarlyReview), scheduledReviewDate: row.review_end_date }); return { ok: true };
}

async function supabaseWithdrawAip(data) {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me;
  const row = await supabaseById('activity_improvement_notices', 'aip_id', data.AipID); if (!row) return { ok: false, error: 'AIP not found.' };
  const now = new Date().toISOString();
  const { error } = await supabaseClient.from('activity_improvement_notices').update({ status: 'Withdrawn', withdrawn_reason: data.Reason, withdrawn_at: now, archived_at: now, archived_by: me.user.UserID, archive_reason: data.Reason, updated_at: now }).eq('aip_id', row.aip_id); if (error) return { ok: false, error: error.message };
  const officer = await supabaseById('officers', 'officer_id', row.officer_id); await supabaseNotify(officer?.member_id, 'Activity Improvement Notice withdrawn', `${row.reference}: ${data.Reason}`, me.user.UserID); return { ok: true };
}

async function supabaseArchiveAip(data) {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me;
  if (!can('VIEW_TASKS')) return { ok: false, error: 'Supervisor access is required to manage the AIP archive.' };
  const restoring = data.Mode === 'restore';
  const update = restoring ? { archived_at: null, archived_by: null, archive_reason: `Restored: ${data.Reason}`, updated_at: new Date().toISOString() } : { archived_at: new Date().toISOString(), archived_by: me.user.UserID, archive_reason: data.Reason, updated_at: new Date().toISOString() };
  const { error } = await supabaseClient.from('activity_improvement_notices').update(update).eq('aip_id', data.AipID); if (error) return { ok: false, error: error.message };
  await supabaseAudit(me.user.UserID, restoring ? 'RESTORE_AIP' : 'ARCHIVE_AIP', 'Activity Improvement Notice', data.AipID, { reason: data.Reason });
  return { ok: true };
}

async function supabaseDeleteAip(data) {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me;
  if (!can('FULL_ACCESS')) return { ok: false, error: 'Full Access permission is required to permanently delete an AIP.' };
  if (data.Confirmation !== 'Permanently delete archived AIP') return { ok: false, error: 'Confirm that the archived AIP should be permanently deleted.' };
  if (!String(data.Reason || '').trim()) return { ok: false, error: 'A deletion reason is required.' };
  const row = await supabaseById('activity_improvement_notices', 'aip_id', data.AipID);
  if (!row) return { ok: false, error: 'AIP not found.' };
  if (!row.archived_at) return { ok: false, error: 'Only archived AIPs can be permanently deleted.' };
  const { error } = await supabaseClient.rpc('permanently_delete_archived_aip', { target_aip_id: row.aip_id, deletion_reason: String(data.Reason).trim() });
  if (error) return { ok: false, error: error.message };
  return { ok: true };
}

