async function supabaseSaveMdtTask(data) {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me;
  const existing = data.TaskID ? await supabaseById('mdt_tasks', 'task_id', data.TaskID) : null;
  if (!existing && !can('VIEW_TASKS')) return { ok: false, error: 'Supervisor access is required to assign tasks.' };
  const assignedOfficerIds = splitTags(data.AssignedOfficerIDs || '');
  if (!existing && (!data.Title || !assignedOfficerIds.length)) return { ok: false, error: 'Task title and at least one selected officer are required.' };
  if (existing && assignedOfficerIds.length > 1) return { ok: false, error: 'An existing task can only be assigned to one officer. Create a new task to assign multiple officers.' };
  const status = data.Status || existing?.status || 'Open';
  const record = can('VIEW_TASKS') ? {
    title: data.Title || existing?.title,
    details: data.Details ?? existing?.details ?? '',
    category: data.Category || existing?.category || 'General',
    priority: data.Priority || existing?.priority || 'Normal',
    status,
    assigned_officer_id: assignedOfficerIds[0] || existing?.assigned_officer_id,
    source_type: existing?.source_type || '',
    source_id: existing?.source_id || '',
    due_at: data.DueAt || existing?.due_at || null,
    completed_at: status === 'Completed' ? existing?.completed_at || new Date().toISOString() : null,
    created_by: existing?.created_by || me.user.UserID,
    updated_at: new Date().toISOString(),
  } : { status, completed_at: status === 'Completed' ? new Date().toISOString() : null, updated_at: new Date().toISOString() };
  const records = existing ? null : assignedOfficerIds.map((officerId) => ({ ...record, assigned_officer_id: officerId }));
  const query = existing ? supabaseClient.from('mdt_tasks').update(record).eq('task_id', data.TaskID) : supabaseClient.from('mdt_tasks').insert(records);
  const { error } = await query;
  if (error) return { ok: false, error: error.message };
  const notifyIds = existing ? (record.assigned_officer_id !== existing.assigned_officer_id ? [record.assigned_officer_id] : []) : assignedOfficerIds;
  for (const officerId of notifyIds) {
    const officer = await supabaseById('officers', 'officer_id', officerId);
    if (officer) await supabaseNotify(officer.member_id, 'New task assigned', notificationDetails([detailLine('Task', record.title), detailLine('Category', record.category), detailLine('Priority', record.priority), detailLine('Due', record.due_at ? formatDisplayDateTime(record.due_at) : 'No deadline'), detailLine('Assigned by', me.user.RobloxUsername)]), me.user.UserID, { category: 'task', taskType: 'Assigned Task', critical: record.priority === 'Critical' });
  }
  return { ok: true, createdCount: existing ? 0 : records.length };
}

async function supabaseResolveGeneratedTask(data) {
  const me = await supabaseCurrentProfile(); if (!me.ok) return me;
  if (!data.TaskKey || !data.Outcome || !String(data.Notes || '').trim()) return { ok: false, error: 'Select an outcome and record brief review notes.' };
  let suppressUntil = null;
  if (data.SuppressDays === 'Until follow-up date') {
    if (!data.FollowUpDate) return { ok: false, error: 'Choose a follow-up date or a fixed reminder period.' };
    suppressUntil = new Date(`${data.FollowUpDate}T23:59:59`).toISOString();
  } else if (data.SuppressDays !== 'Permanently') {
    const days = Number.parseInt(data.SuppressDays, 10) || 30; const date = new Date(); date.setDate(date.getDate() + days); suppressUntil = date.toISOString();
  }
  const record = { task_key: data.TaskKey, task_type: data.TaskType, source_id: data.TaskKey, officer_id: data.OfficerID || null, resolved_by: me.user.UserID, outcome: data.Outcome, notes: String(data.Notes).trim(), follow_up_date: data.FollowUpDate || null, suppress_until: suppressUntil };
  const { error } = await supabaseClient.from('task_resolutions').upsert(record, { onConflict: 'task_key,resolved_by' });
  if (error) return { ok: false, error: error.message };
  await supabaseAudit(me.user.UserID, 'RESOLVE_TASK', data.TaskType, data.TaskKey, { outcome: data.Outcome, notes: data.Notes, followUpDate: data.FollowUpDate || '', suppressUntil });
  if (truthy(data.NotifyOfficer) && data.OfficerID) { const officer = await supabaseById('officers', 'officer_id', data.OfficerID); await supabaseNotify(officer?.member_id, `${data.TaskType} completed`, `${data.Outcome}: ${data.Notes}`, me.user.UserID); }
  return { ok: true };
}

function prioritizeTasks(rows) {
  return rows.map((row) => {
    const score = taskPriorityScore(row);
    return { ...row, Priority: score >= 85 ? 'Critical' : score >= 60 ? 'High' : score >= 30 ? 'Normal' : 'Low', PriorityScore: score };
  }).sort((a, b) => b.PriorityScore - a.PriorityScore);
}

function taskPriorityScore(row) {
  let score = row.MySupervisee ? 15 : 0;
  if (row.IsMine || row.AssignedToMe || row.RelevantSupervisor) score += 20;
  if (String(row.TaskType || '').includes('Amendment')) score += 75;
  if (row.Priority === 'Critical') score += 65;
  else if (row.Priority === 'High') score += 40;
  if (['Discipline Review', 'Restriction Review', 'Appeal / Review', 'CAD Review', 'After Action Review', 'Operational Action Review'].includes(row.TaskType)) score += 55;
  if (['LOA Approval', 'Transfer Request', 'Retrospective Shift'].includes(row.TaskType)) score += 45;
  if (['Training Review', 'Probation Review', 'Performance Review', 'Activity Review'].includes(row.TaskType)) score += 35;
  if (row.TaskType === 'Account Request') score += 30;
  if (row.TaskType === 'Course Booking') score += 25;
  const due = row.EndDate || row.TargetDate || row.NextReviewDate || row.StartDate || row.CreatedAt || row.RequestedAt;
  if (due) {
    const days = Math.ceil((new Date(due).getTime() - Date.now()) / 86400000);
    if (days < 0) score += 35;
    else if (days <= 2) score += 25;
    else if (days <= 7) score += 15;
  }
  if (['Expired', 'Denied', 'Suspended', 'Needs Review'].includes(row.Status)) score += 20;
  return Math.min(100, Math.max(0, score));
}

async function supabaseSupervisorDashboard() {
  const [officers, shifts, loa, discipline, plans, checkins, supervisorRequests, profiles] = await Promise.all([
    supabaseAll('officers'),
    supabaseAll('shift_logs'),
    supabaseAll('loa_requests'),
    supabaseAll('disciplinary_actions'),
    supabaseAll('development_plans'),
    supabaseAll('supervisor_checkins'),
    supabaseAll('supervisor_requests'),
    supabaseAll('profiles'),
  ]);
  const taskResponse = await supabaseTasks();
  const superviseeIds = new Set((officers || []).filter((row) => row.supervisor_user_id === state.user?.UserID && row.status !== 'Archived').map((row) => row.officer_id));
  const superviseeTasks = (taskResponse.ok ? taskResponse.allTasks || [] : []).filter((task) => superviseeIds.has(task.OfficerID) || superviseeIds.has(task.SubjectOfficerID));
  const openTaskCount = (officerId) => superviseeTasks.filter((task) => task.OfficerID === officerId || task.SubjectOfficerID === officerId).length;
  const assigned = (officers || []).filter((row) => row.supervisor_user_id === state.user?.UserID).map((officer) => {
    const officerShifts = (shifts || []).filter((row) => row.officer_id === officer.officer_id);
    return Object.assign(decorateSupabaseOfficer(officer, { loa, shifts: officerShifts, profiles }), {
      LastShift: officerShifts.sort((a, b) => String(b.started_at).localeCompare(String(a.started_at)))[0]?.started_at || '',
      MonthlyActivity: durationText(officerShifts.reduce((sum, shift) => sum + shiftMs(shift), 0)),
      TrainingGaps: '',
      DisciplineFlags: (discipline || []).filter((row) => row.officer_id === officer.officer_id && row.status === 'Active').length,
      OpenPlans: (plans || []).filter((row) => row.officer_id === officer.officer_id && row.status !== 'Completed').length,
      OpenTasks: openTaskCount(officer.officer_id),
    });
  });
  const unassigned = (officers || []).filter((row) => row.status !== 'Archived' && !row.supervisor_user_id).map((row) => decorateSupabaseOfficer(row, { loa, shifts, profiles }));
  const pendingRequests = (supervisorRequests || []).filter((row) => row.status === 'Pending').map((row) => supabaseSupervisorRequest(row, (officers || []).find((officer) => officer.officer_id === row.officer_id), profiles || []));
  const workload = (profiles || []).filter((profile) => profile.role !== 'Constable').map((profile) => ({
    Supervisor: profile.roblox_username,
    Rank: profile.rank,
    AssignedOfficers: (officers || []).filter((officer) => officer.supervisor_user_id === profile.user_id).length,
    PendingRequests: pendingRequests.filter((request) => request.SupervisorUserID === profile.user_id).length,
    Coverage: (officers || []).filter((officer) => officer.supervisor_user_id === profile.user_id).length > 8 ? 'High workload' : 'Balanced',
  }));
  return {
    ok: true,
    assigned,
    superviseeTasks,
    unassigned,
    pendingRequests,
    workload,
    plans: (plans || []).map((row) => supabaseDevelopmentPlan(row, (officers || []).find((officer) => officer.officer_id === row.officer_id), profiles || [])),
    checkins: (checkins || []).map((row) => supabaseCheckin(row, (officers || []).find((officer) => officer.officer_id === row.officer_id), profiles || [])),
    counts: {
      assigned: assigned.length,
      unassigned: unassigned.length,
      pendingRequests: pendingRequests.length,
      openPlans: (plans || []).filter((row) => row.status !== 'Completed').length,
      superviseeTasks: superviseeTasks.length,
    },
  };
}

async function supabaseRequestSupervisorSupport(data) {
  const profile = await supabaseProfileByUserId(state.user.UserID);
  const officer = await supabaseOfficerForMember(profile.member_id);
  if (!officer) return { ok: false, error: 'No linked officer profile.' };
  const result = await supabaseClient.from('supervisor_requests').insert({
    officer_id: officer.officer_id,
    supervisor_user_id: officer.supervisor_user_id || null,
    category: data.Category || 'General',
    subject: data.Subject || '',
    details: data.Details || '',
    status: 'Pending',
  }).select().single();
  if (result.error) return { ok: false, error: result.error.message };
  await supabaseNotify(officer.member_id, 'Supervisor request submitted', notificationDetails([
    detailLine('Subject', data.Subject || 'Request'),
    detailLine('Category', data.Category || 'General'),
    detailLine('Status', 'Pending'),
    detailLine('Details', data.Details),
  ]), state.user?.UserID);
  if (officer.supervisor_user_id) {
    const supervisor = await supabaseById('profiles', 'user_id', officer.supervisor_user_id);
    if (supervisor) await supabaseNotify(supervisor.member_id, 'Supervisee request submitted', notificationDetails([
      detailLine('Officer', officer.roblox_username),
      detailLine('Rank', officer.rank),
      detailLine('Subject', data.Subject || 'Request'),
      detailLine('Category', data.Category || 'General'),
      detailLine('Status', 'Pending'),
    ]), state.user?.UserID);
  }
  return { ok: true, RequestID: result.data.request_id };
}

