  if (!error && incidentId?.startsWith('CAD_')) await supabaseAddOperationalIncidentLog({ IncidentID: incidentId, EntryType: 'BOLO Sighting', Body: `BOLO sighting recorded at ${data.Location}${data.Details ? `: ${data.Details}` : ''}.` });
