function supabaseOperationalDeployment(row, officers, trainingMatrix, profiles, responses = [], currentOfficer = null) {
  const assigned = officers.filter((item) => (row.assigned_officer_ids || []).includes(item.officer_id));
  const capabilities = new Set(assigned.flatMap((officer) => unitCapabilities([officer], trainingMatrix || [])));
  const deploymentResponses = responses.filter((item) => item.deployment_id === row.deployment_id);
  return { DeploymentID: row.deployment_id, Title: row.title, DeploymentType: row.deployment_type, Status: row.status, StartsAt: row.starts_at, EndsAt: row.ends_at || '', Location: row.location || '', Briefing: row.briefing || '', RequiredCapabilities: (row.required_capabilities || []).join(', '), AssignedOfficerIDs: row.assigned_officer_ids || [], AssignedOfficers: assigned.map((item) => item.roblox_username).join(', '), MissingCapabilities: (row.required_capabilities || []).filter((item) => !capabilities.has(item)), Capacity: row.capacity || 0, Lead: profiles.find((item) => item.user_id === row.lead_user_id)?.roblox_username || '', MyResponse: deploymentResponses.find((item) => item.officer_id === currentOfficer?.officer_id)?.response || '', ResponseCounts: { Available: deploymentResponses.filter((item) => item.response === 'Available').length, Maybe: deploymentResponses.filter((item) => item.response === 'Maybe').length, Unavailable: deploymentResponses.filter((item) => item.response === 'Unavailable').length } };
}

function operationalActionQueue(active, archive, cases, actionReviews, incidentReviews, people, vehicles) {
  const rows = [];
  active.filter((row) => !(row.AssignedUnitIDs || []).length).forEach((row) => rows.push({ Group: 'Critical', Priority: ['Emergency', 'Immediate'].includes(row.Priority) ? 'Critical' : 'High', Title: 'Unassigned active CAD', Detail: `${row.Title} / ${row.Location || 'No location'}`, Reference: row.IncidentNumber, IncidentID: row.IncidentID }));
  active.filter((row) => !(row.Entities || []).length && ['On Scene', 'En Route'].includes(row.Status)).forEach((row) => rows.push({ Group: 'Data Quality', Priority: 'Normal', Title: 'No people or vehicles linked', Detail: row.Title, Reference: row.IncidentNumber, IncidentID: row.IncidentID }));
  archive.filter((row) => !row.Outcome && !(row.Disposals || []).length).forEach((row) => rows.push({ Group: 'Data Quality', Priority: 'High', Title: 'Closed CAD missing outcome', Detail: row.Title, Reference: row.IncidentNumber, IncidentID: row.IncidentID }));
  actionReviews.filter((row) => ['Pending', 'Amendments Required'].includes(row.status)).forEach((row) => rows.push({ Group: 'Review', Priority: row.status === 'Amendments Required' ? 'Critical' : 'High', Title: `${row.action_type} review`, Detail: row.supervisor_feedback || row.rationale || 'Supervisor review required.', Reference: archive.find((item) => item.IncidentID === row.incident_id)?.IncidentNumber || row.incident_id, IncidentID: row.incident_id, ActionReviewID: row.action_review_id, ReviewKind: 'Action', DueAt: row.due_at }));
  incidentReviews.filter((row) => ['Pending', 'Amendments Required'].includes(row.status)).forEach((row) => rows.push({ Group: 'Review', Priority: row.status === 'Amendments Required' ? 'Critical' : 'High', Title: 'CAD supervisor review', Detail: row.feedback || 'Incident review required.', Reference: archive.find((item) => item.IncidentID === row.incident_id)?.IncidentNumber || row.incident_id, IncidentID: row.incident_id, ReviewID: row.review_id, ReviewKind: 'Incident', DueAt: row.due_at }));
  cases.flatMap((record) => record.Actions || []).filter((action) => !['Completed', 'Cancelled'].includes(action.Status)).forEach((action) => rows.push({ Group: 'Casework', Priority: action.Priority, Title: action.Title, Detail: action.Details, Reference: cases.find((item) => item.OperationID === action.OperationID)?.Reference || '', OperationID: action.OperationID, ActionID: action.ActionID, Owner: action.Owner, DueAt: action.DueAt, Status: action.Status }));
  return rows.sort((a, b) => priorityWeight(b.Priority) - priorityWeight(a.Priority) || String(a.DueAt || '9999').localeCompare(String(b.DueAt || '9999')));
}

function supabaseUnitInvitation(row, units, officers, currentOfficer) {
  const unit = units.find((item) => item.UnitID === row.unit_id) || {};
  const officer = officers.find((item) => item.officer_id === row.officer_id) || {};
  return { RequestType: 'Invitation', InvitationID: row.invitation_id, UnitID: row.unit_id, Callsign: unit.Callsign || row.unit_id, OfficerID: row.officer_id, Officer: officer.roblox_username || row.officer_id, Role: row.role || 'Crew', Message: row.message || '', Status: row.status, CanRespond: row.officer_id === currentOfficer?.officer_id };
}

function enrichOperationalIncident(row, people, vehicles, offences, entityLinks, disposals, markers, rawIncidents, bolos, officers, powerUses, powers, officerActions = []) {
  const links = (entityLinks || []).filter((item) => item.incident_id === row.IncidentID);
  const entities = links.map((item) => {
    const person = people.find((record) => record.person_id === item.person_id);
    const vehicle = vehicles.find((record) => record.vehicle_id === item.vehicle_id);
    const entityType = person ? 'Person' : 'Vehicle';
    const entityId = person?.person_id || vehicle?.vehicle_id || '';
    return { InvolvementID: item.involvement_id, EntityType: entityType, EntityID: entityId, Label: person?.display_name || vehicle?.registration || 'Unknown entity', Detail: person?.roblox_username || [vehicle?.colour, vehicle?.make, vehicle?.model].filter(Boolean).join(' '), InvolvementRole: item.involvement_role || 'Subject', Notes: item.notes || '', Markers: (markers || []).filter((marker) => marker.status === 'Active' && (!marker.expires_at || new Date(marker.expires_at) >= new Date(new Date().toDateString())) && (marker.person_id === entityId || marker.vehicle_id === entityId)).map(supabaseOperationalMarker) };
  });
  const incidentDisposals = (disposals || []).filter((item) => item.incident_id === row.IncidentID).map((item) => {
    const person = people.find((record) => record.person_id === item.person_id);
    const vehicle = vehicles.find((record) => record.vehicle_id === item.vehicle_id);
    const offence = offences.find((record) => record.offence_id === item.offence_id);
    return { DisposalID: item.disposal_id, PersonID: item.person_id || '', VehicleID: item.vehicle_id || '', OffenceID: item.offence_id || '', Subject: person?.display_name || vehicle?.registration || '', Offence: offence ? `${offence.code} / ${offence.title}` : '', OutcomeType: item.outcome_type, FineAmount: item.fine_amount || 0, PrisonMinutes: item.prison_minutes || 0, PenaltyPoints: item.penalty_points || 0, Notes: item.notes || '', IssuingOfficer: officers.find((officer) => officer.officer_id === item.issuing_officer_id)?.roblox_username || '', IssuedAt: item.issued_at };
  });
  const alerts = [];
  entities.forEach((entity) => {
    entity.Markers.forEach((marker) => alerts.push({ Title: `${marker.Severity} marker: ${marker.MarkerType}`, Detail: `${entity.Label}: ${marker.Details || 'No additional details.'}` }));
    const linkedIncidentIds = new Set((entityLinks || []).filter((item) => entity.EntityType === 'Person' ? item.person_id === entity.EntityID : item.vehicle_id === entity.EntityID).map((item) => item.incident_id));
    linkedIncidentIds.delete(row.IncidentID);
    const today = new Date().toISOString().slice(0, 10);
    const todayIncidents = (rawIncidents || []).filter((incident) => linkedIncidentIds.has(incident.incident_id) && String(incident.created_at).slice(0, 10) === today);
    todayIncidents.forEach((incident) => {
      const previous = (disposals || []).find((item) => item.incident_id === incident.incident_id && (entity.EntityType === 'Person' ? item.person_id === entity.EntityID : item.vehicle_id === entity.EntityID));
      const offence = offences.find((item) => item.offence_id === previous?.offence_id);
      const outcome = previous?.outcome_type || incident.closure_code || incident.outcome || 'No outcome recorded';
      alerts.push({ Title: 'Repeat contact today', Detail: `${entity.Label} was previously dealt with for ${offence?.title || incident.title || 'another incident'}; outcome: ${outcome}.`, Recommendation: previous?.outcome_type === 'Warning' ? `Previous warning recorded: do not issue another warning without a supervisor-recorded exception. ${offence?.escalation_guidance || 'Review the earlier CAD and apply the next appropriate disposal.'}` : (offence?.escalation_guidance || ''), IncidentID: incident.incident_id, IncidentNumber: incident.incident_number });
    });
    const activeCount = (rawIncidents || []).filter((incident) => linkedIncidentIds.has(incident.incident_id) && !['Resolved', 'Cancelled'].includes(incident.status)).length;
    if (activeCount) alerts.push({ Title: 'Linked active CAD', Detail: `${entity.Label} is linked to ${activeCount} other active incident${activeCount === 1 ? '' : 's'}.` });
    const boloMatches = (bolos || []).filter((bolo) => bolo.status === 'Active' && `${bolo.title} ${bolo.description}`.toLowerCase().includes(entity.Label.toLowerCase()));
    boloMatches.forEach((bolo) => alerts.push({ Title: `Active BOLO: ${bolo.title}`, Detail: `${entity.Label} matches an active ${bolo.priority || 'Normal'} priority BOLO.` }));
  });
  const incidentPowerUses = (powerUses || []).filter((item) => item.incident_id === row.IncidentID).map((item) => supabaseOperationalPowerUse(item, powers || [], officers || [], rawIncidents || []));
  return { ...row, Entities: entities, Disposals: incidentDisposals, PowerUses: incidentPowerUses, OfficerActions: officerActions.filter((item) => item.incident_id === row.IncidentID), CorrelationAlerts: alerts, IncidentData: row.IncidentData || {} };
}

function operationalLocationIntel(incidents) {
  const groups = new Map();
  (incidents || []).filter((row) => row.Location).forEach((row) => {
    const key = row.Location.trim().toLowerCase();
    const current = groups.get(key) || { Location: row.Location, rows: [] };
    current.rows.push(row);
    groups.set(key, current);
  });
  return [...groups.values()].map((group) => {
    const typeCounts = group.rows.reduce((counts, row) => ({ ...counts, [row.IncidentType]: (counts[row.IncidentType] || 0) + 1 }), {});
    const commonType = Object.entries(typeCounts).sort((a, b) => b[1] - a[1])[0]?.[0] || '';
    const entityCounts = group.rows.flatMap((row) => row.Entities || []).reduce((counts, entity) => ({ ...counts, [entity.EntityID]: (counts[entity.EntityID] || 0) + 1 }), {});
    return { Location: group.Location, Incidents: group.rows.length, CommonType: commonType, RepeatEntities: Object.values(entityCounts).filter((count) => count > 1).length };
  }).sort((a, b) => b.Incidents - a.Incidents).slice(0, 12);
}

function operationalDataQuality(incidents, people, vehicles, offences, cases = []) {
  const closedWithoutOutcome = incidents.filter((row) => ['Resolved', 'Cancelled'].includes(row.Status) && !(row.Disposals || []).length && !row.Outcome).length;
  const noEntities = incidents.filter((row) => !(row.Entities || []).length).length;
  const orphanPeople = people.filter((row) => !row.IncidentCount).length;
  const incompleteVehicles = vehicles.filter((row) => !row.Make || !row.Model || !row.Colour).length;
  const overdueCaseActions = cases.flatMap((row) => row.Actions || []).filter((row) => row.DueAt && new Date(row.DueAt) < new Date() && !['Completed', 'Cancelled'].includes(row.Status)).length;
  const emptyCases = cases.filter((row) => !(row.Links || []).length && !['Completed', 'Cancelled'].includes(row.Status)).length;
  const rows = [
    { Title: 'CADs without linked entities', Count: noEntities, Detail: 'Link people or vehicles to improve intelligence value.', Severity: noEntities ? 'Caution' : 'Info' },
    { Title: 'Closed CADs without outcome data', Count: closedWithoutOutcome, Detail: 'Record actions, offences and disposals.', Severity: closedWithoutOutcome ? 'High' : 'Info' },
    { Title: 'Unlinked person records', Count: orphanPeople, Detail: 'Records not currently linked to any CAD.', Severity: orphanPeople ? 'Caution' : 'Info' },
    { Title: 'Incomplete vehicle descriptions', Count: incompleteVehicles, Detail: 'Missing make, model or colour.', Severity: incompleteVehicles ? 'Caution' : 'Info' },
    { Title: 'Overdue casework actions', Count: overdueCaseActions, Detail: 'Assigned investigation actions have passed their deadline.', Severity: overdueCaseActions ? 'High' : 'Info' },
    { Title: 'Casework without linked records', Count: emptyCases, Detail: 'Link CADs, people, vehicles or BOLOs to provide an evidential record.', Severity: emptyCases ? 'Caution' : 'Info' },
    { Title: 'Active offence definitions', Count: offences.filter((row) => row.active !== false).length, Detail: 'Current law catalogue entries.', Severity: 'Info' },
  ];
  return rows.filter((row) => row.Count || row.Title === 'Active offence definitions');
}

function operationalAnalytics(rows) {
  const countBy = (values) => Object.entries(values.reduce((result, value) => {
    const key = value || 'Unspecified';
    result[key] = (result[key] || 0) + 1;
    return result;
  }, {})).map(([Label, Value]) => ({ Label, Value })).sort((a, b) => b.Value - a.Value);
  const durations = rows.map((row) => new Date(row.ClosedAt) - new Date(row.CreatedAt)).filter((value) => Number.isFinite(value) && value >= 0);
  const responses = rows.flatMap((row) => (row.Attendance || []).map((item) => item.OnSceneAt ? new Date(item.OnSceneAt) - new Date(item.AssignedAt) : NaN)).filter((value) => Number.isFinite(value) && value >= 0).sort((a, b) => a - b);
  const reviewed = rows.filter((row) => ['Approved', 'Completed'].includes(row.ReviewStatus)).length;
  const entityCounts = rows.flatMap((row) => row.Entities || []).reduce((result, row) => ({ ...result, [row.EntityID]: (result[row.EntityID] || 0) + 1 }), {});
  return {
    ClosedCount: rows.length,
    AverageDuration: durations.length ? durationText(durations.reduce((sum, value) => sum + value, 0) / durations.length) : 'No data',
    MedianResponse: responses.length ? durationText(responses[Math.floor(responses.length / 2)]) : 'No data',
    ReviewRate: rows.length ? Math.round((reviewed / rows.length) * 100) : 0,
    ByType: countBy(rows.map((row) => row.IncidentType)),
    ByOutcome: countBy(rows.map((row) => row.ClosureCode || row.Outcome)),
    ByDisposal: countBy(rows.flatMap((row) => (row.Disposals || []).map((item) => item.OutcomeType))),
    RepeatSubjects: Object.values(entityCounts).filter((count) => count > 1).length,
    ByHour: countBy(rows.map((row) => `${String(new Date(row.CreatedAt).getHours()).padStart(2, '0')}:00`)),
    ByUnit: countBy(rows.flatMap((row) => String(row.AssignedUnits || '').split(',').map((item) => item.trim()).filter(Boolean))),
  };
}

function supabaseOperationalBolo(row, profiles, sightings = [], incidents = []) {
  return {
    BoloID: row.bolo_id,
    Title: row.title,
    BoloType: row.bolo_type,
    Priority: row.priority,
    Description: row.description,
    Location: row.location,
    ExpiresAt: row.expires_at,
    Status: row.status,
    ImageUrl: row.image_url || '',
    ImageFileName: row.image_file_name || '',
    Sightings: sightings.filter((item) => item.bolo_id === row.bolo_id).map((item) => ({ SightingID: item.sighting_id, IncidentID: item.incident_id || '', IncidentNumber: incidents.find((incident) => incident.incident_id === item.incident_id)?.incident_number || '', Location: item.location, Details: item.details || '', SightedAt: item.sighted_at })),
    CreatedBy: profiles.find((profile) => profile.user_id === row.created_by)?.roblox_username || '',
    CreatedAt: row.created_at,
  };
}

function opsPriorityWeight(priority) {
  return { Emergency: 4, Immediate: 3, Priority: 2, Routine: 1 }[priority] || 0;
}

function opsBoloWeight(priority) {
  return { Critical: 4, High: 3, Normal: 2, Low: 1 }[priority] || 0;
}

async function supabaseRequestRetrospectiveShift(data) {
  const start = new Date(data.StartedAt);
  const end = new Date(data.EndedAt);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || end <= start) return { ok: false, error: 'The shift end must be after its start.' };
  if (end > new Date()) return { ok: false, error: 'A retrospective shift cannot end in the future.' };
  const profile = await supabaseProfileByUserId(state.user.UserID);
  const officer = await supabaseOfficerForMember(profile.member_id);
  if (!officer) return { ok: false, error: 'No linked officer profile.' };
  const { error } = await supabaseClient.from('retrospective_shift_requests').insert({ officer_id: officer.officer_id, started_at: start.toISOString(), ended_at: end.toISOString(), summary: data.Summary || '', reason: data.Reason || '', status: 'Pending' });
  if (error) return { ok: false, error: error.message };
  const supervisor = officer.supervisor_user_id ? await supabaseById('profiles', 'user_id', officer.supervisor_user_id) : null;
  if (supervisor) await supabaseNotify(supervisor.member_id, 'Retrospective shift requested', `${officer.roblox_username} submitted a shift for ${formatDisplayDateTime(start.toISOString())}.`, state.user.UserID);
  return { ok: true };
}

async function supabaseReviewRetrospectiveShift(data) {
  const request = await supabaseById('retrospective_shift_requests', 'request_id', data.RequestID);
  if (!request || request.status !== 'Pending') return { ok: false, error: 'This request is no longer pending.' };
  const start = new Date(data.StartedAt);
  const end = new Date(data.EndedAt);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || end <= start) return { ok: false, error: 'The shift end must be after its start.' };
  const officer = await supabaseById('officers', 'officer_id', request.officer_id);
  if (data.Status === 'Approved') {
    const { error: shiftError } = await supabaseClient.from('shift_logs').insert({ officer_id: officer.officer_id, member_id: officer.member_id, roblox_username: officer.roblox_username, callsign: officer.callsign || '', rank: officer.rank || '', started_at: start.toISOString(), ended_at: end.toISOString(), summary: data.Summary || '', status: 'Completed' });
    if (shiftError) return { ok: false, error: shiftError.message };
  }
  const { error } = await supabaseClient.from('retrospective_shift_requests').update({ status: data.Status, review_reason: data.ReviewReason || '', reviewed_by: state.user.UserID, reviewed_at: new Date().toISOString(), started_at: start.toISOString(), ended_at: end.toISOString(), summary: data.Summary || '' }).eq('request_id', data.RequestID);
  if (!error) await supabaseNotify(officer.member_id, `Retrospective shift ${String(data.Status).toLowerCase()}`, data.ReviewReason || 'Your retrospective shift request has been reviewed.', state.user.UserID);
  return error ? { ok: false, error: error.message } : { ok: true };
}

async function supabaseSaveShift(data) {
  const start = new Date(data.StartedAt);
  const end = new Date(data.EndedAt);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || end <= start) return { ok: false, error: 'The shift end must be after its start.' };
  if (!String(data.ChangeReason || '').trim()) return { ok: false, error: 'A reason for the amendment is required.' };
  const before = await supabaseById('shift_logs', 'shift_id', data.ShiftID);
  const update = { started_at: start.toISOString(), ended_at: end.toISOString(), summary: data.Summary || '', status: 'Completed', updated_at: new Date().toISOString() };
  const { error } = await supabaseClient.from('shift_logs').update(update).eq('shift_id', data.ShiftID);
  if (!error) {
    await supabaseClient.from('shift_audit_events').insert({ shift_id: data.ShiftID, officer_id: before.officer_id, action: 'Edited', reason: data.ChangeReason, before_snapshot: before, after_snapshot: update, performed_by: state.user.UserID });
    const officer = await supabaseById('officers', 'officer_id', before.officer_id);
    await supabaseNotify(officer?.member_id, 'Shift record amended', `Your shift dated ${formatDisplayDateTime(before.started_at)} was amended. Reason: ${data.ChangeReason}`, state.user.UserID);
  }
  return error ? { ok: false, error: error.message } : { ok: true };
}

async function supabaseReviewShift(data) {
  if (!can('VIEW_TASKS')) return { ok: false, error: 'You do not have permission to review shifts.' };
  if (!String(data.ReviewNotes || '').trim() && data.ReviewStatus !== 'Approved') return { ok: false, error: 'Review notes are required for this outcome.' };
  const shift = await supabaseById('shift_logs', 'shift_id', data.ShiftID);
  const wrapup = await supabaseById('shift_wrapups', 'shift_id', data.ShiftID);
  if (!shift || !wrapup) return { ok: false, error: 'Shift debrief not found.' };
  const reviewedAt = new Date().toISOString();
  const { error } = await supabaseClient.from('shift_wrapups').update({ review_status: data.ReviewStatus, review_notes: data.ReviewNotes || '', reviewed_by: state.user.UserID, reviewed_at: reviewedAt }).eq('shift_id', data.ShiftID);
  if (error) return { ok: false, error: error.message };
  await supabaseClient.from('shift_audit_events').insert({ shift_id: data.ShiftID, officer_id: shift.officer_id, action: 'Reviewed', reason: data.ReviewNotes || data.ReviewStatus, before_snapshot: { review_status: wrapup.review_status }, after_snapshot: { review_status: data.ReviewStatus }, performed_by: state.user.UserID });
  await supabaseClient.from('mdt_tasks').update({ status: 'Completed', completed_at: reviewedAt, updated_at: reviewedAt }).eq('source_type', 'Shift Debrief').eq('source_id', data.ShiftID).ilike('title', 'Review shift debrief%');
  await supabaseClient.from('mdt_tasks').update({ status: 'Completed', completed_at: reviewedAt, updated_at: reviewedAt }).eq('source_type', 'Shift Debrief').eq('source_id', data.ShiftID).neq('assigned_officer_id', shift.officer_id);
  const officer = await supabaseById('officers', 'officer_id', shift.officer_id);
  await supabaseNotify(officer?.member_id, `Shift review: ${data.ReviewStatus}`, data.ReviewNotes || 'Your shift debrief has been approved.', state.user.UserID);
  if (data.ReviewStatus === 'Amendments Required') await supabaseClient.from('mdt_tasks').insert({ title: `Amend shift debrief / ${formatDisplayDateTime(shift.started_at)}`, details: data.ReviewNotes || 'Your supervisor has requested amendments.', category: 'Shift Debrief', priority: 'High', status: 'Open', assigned_officer_id: shift.officer_id, source_type: 'Shift Debrief', source_id: data.ShiftID, created_by: state.user.UserID });
  return { ok: true };
}

async function supabaseVoidShift(data) {
  if (!can('VIEW_TASKS')) return { ok: false, error: 'You do not have permission to void shifts.' };
  if (!String(data.Reason || '').trim()) return { ok: false, error: 'A reason for voiding the shift is required.' };
  const shift = await supabaseById('shift_logs', 'shift_id', data.ShiftID);
  if (!shift || shift.voided_at) return { ok: false, error: 'This shift is unavailable or already voided.' };
  const profile = await supabaseProfileByUserId(state.user.UserID);
  const actorOfficer = await supabaseOfficerForMember(profile?.member_id);
  if (actorOfficer?.officer_id === shift.officer_id) return { ok: false, error: 'You cannot void your own shift. Another authorised supervisor must review it.' };
  const voidedAt = new Date().toISOString();
  const update = { voided_at: voidedAt, voided_by: state.user.UserID, void_reason: data.Reason, updated_at: voidedAt };
  const { error } = await supabaseClient.from('shift_logs').update(update).eq('shift_id', data.ShiftID);
  if (error) return { ok: false, error: error.message };
  await supabaseClient.from('shift_audit_events').insert({ shift_id: data.ShiftID, officer_id: shift.officer_id, action: 'Voided', reason: data.Reason, before_snapshot: shift, after_snapshot: update, performed_by: state.user.UserID });
  const officer = await supabaseById('officers', 'officer_id', shift.officer_id);
  await supabaseNotify(officer?.member_id, 'Shift record voided', `Your shift dated ${formatDisplayDateTime(shift.started_at)} was voided. Reason: ${data.Reason}`, state.user.UserID);
  await supabaseAudit(state.user.UserID, 'Void shift', 'Shift', data.ShiftID, { officer_id: shift.officer_id, reason: data.Reason, original: shift });
  return { ok: true };
}

async function supabaseVisibleDocuments() {
  const { data, error } = await supabaseClient
    .from('documents')
    .select('*')
    .order('category', { ascending: true })
    .order('title', { ascending: true });
  if (error) return { ok: false, error: error.message, rows: [] };
  const rows = await Promise.all((data || []).map(async (row) => {
    if (!row.storage_path) return supabaseDocument(row);
    const { data: signed } = await supabaseClient.storage
      .from('mo8-documents')
      .createSignedUrl(row.storage_path, 60 * 60);
    return supabaseDocument(Object.assign({}, row, { signed_url: signed?.signedUrl || '' }));
  }));
  const visibleRows = state.accessPreview ? rows.filter((document) => {
    const requiredRole = String(document.RequiredRole || '').trim();
    const roleAllowed = !requiredRole || state.accessPreview.roles.includes(requiredRole) || rankAtLeast(state.accessPreview.rank, requiredRole);
    const requiredTags = splitTags(document.RequiredTags || '');
    return roleAllowed && (!requiredTags.length || requiredTags.some((tag) => state.accessPreview.tags.includes(tag)));
  }) : rows;
  return { ok: true, rows: visibleRows };
}

async function supabaseVisibleAnnouncements() {
  const { data, error } = await supabaseClient
    .from('announcements')
    .select('*')
    .order('pinned', { ascending: false })
    .order('updated_at', { ascending: false });
  if (error) return { ok: false, error: error.message, rows: [] };
  return { ok: true, rows: (data || []).map(supabaseAnnouncement) };
}

